// Content for The Rabbit Hole (node g43, ages 12-15, Chapter 4): NEW v2 build to GDD 43 (mechanic-embodying),
// the online-misogyny / manosphere node (Thread E/G · Gender & Media). "The funnel and the grift are the
// target: never the kid." 84 researched, India-grounded scenarios across the the-funnel → follow-the-money →
// spot-the-hook → real-strong → have-each-others-backs → the-need-underneath arc, each encoded as one of the
// shared v2 play actions (branch / reflect / strike-rewrite / spot / sort / role-play / match): no binary
// "tap the right card". Lead mechanics: strike-rewrite (bust the claim ×15), spot (catch the hook ×12),
// branch (the choice ×16). THE ONE RULE: NEVER SHAME THE BOY, boys pulled in are usually lonely, anxious and
// looking for identity, and grifters + algorithms exploit that; the FUNNEL and the GRIFT are the target, never
// the kid. Media-literacy-led (how the algorithm funnels, how the grift sells), evenhanded (the manosphere
// harms boys too), and centred on a better answer: POSITIVE MASCULINITY, real strength lifts people, it
// never needs anyone else to be small; strong AND kind; confidence is built, not bought; you're already
// enough AND can grow. Never platforms real influencers/content. Routes the loneliness underneath to help (a
// trusted adult, Tele-MANAS 14416); online harassment to cybercrime.gov.in / 1930, Childline 1098. Builds on
// g25/g26. Rendered by the shared engine (components/games/v2-engine.tsx). gameId "rabbit-hole" (the
// engine-host registry id; the GDD/library aspirational id is "the-rabbit-hole"). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // The funnel: how the algorithm works
  {"id":"rh-001","cat":"the-funnel","type":"spot","hook":"Spot the two clips where the feed turns to contempt.","scene":[{"id":"a","text":"Harmless gym and study tips","trick":false},{"id":"b","text":"'Why girls don't respect you' clips creep in","trick":true},{"id":"c","text":"A reel on stretching after a workout","trick":false},{"id":"d","text":"Soon it's full contempt and us-vs-them","trick":true},{"id":"e","text":"A clip on saving pocket money","trick":false}],"why":"The flagged clips are where relatable tips escalate to contempt, by design.","relearn":"The funnel starts relatable and escalates to contempt by design.","persona":"Veer","source":"the funnel (UN Women 2025)"},
  {"id":"rh-002","cat":"the-funnel","type":"spot","hook":"Spot the two reasons the feed pushes extreme stuff.","scene":[{"id":"a","text":"Calm, fair videos get a quiet response","trick":false},{"id":"b","text":"Outrage and 'enemy' clips get huge engagement","trick":true},{"id":"c","text":"A how-to is watched once and skipped","trick":false},{"id":"d","text":"So the feed serves you more outrage","trick":true},{"id":"e","text":"Useful clips don't get shared much","trick":false}],"why":"Outrage drives engagement, so the feed escalates toward it.","relearn":"Algorithms escalate toward outrage because outrage keeps you watching.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-003","cat":"the-funnel","type":"spot","hook":"Spot the two lines showing who the funnel hunts.","scene":[{"id":"a","text":"Ads for 'fix your life, become high-value'","trick":true},{"id":"b","text":"A normal fitness reel","trick":false},{"id":"c","text":"It promises belonging and someone to blame","trick":true},{"id":"d","text":"A clip about a cricket match","trick":false},{"id":"e","text":"A tip on fixing a cycle puncture","trick":false}],"why":"The flagged lines target lonely boys, selling belonging and a scapegoat.","relearn":"The funnel hooks loneliness with belonging and someone to blame.","persona":"Veer","source":"who it targets"},
  {"id":"rh-004","cat":"the-funnel","type":"spot","hook":"Spot the two bits of relatable bait at the top.","scene":[{"id":"a","text":"\"Want to get fit and confident?\"","trick":true},{"id":"b","text":"A genuinely useful study tip","trick":false},{"id":"c","text":"\"Want girls to finally notice you?\"","trick":true},{"id":"d","text":"A recipe for a quick tiffin","trick":false},{"id":"e","text":"A clip on how to tie a tie","trick":false}],"why":"The flagged lines are bait, relatable and healthy-sounding, which makes them work.","relearn":"The funnel's bait sounds healthy and relatable; that's the hook.","persona":"any","source":"the funnel"},
  {"id":"rh-005","cat":"the-funnel","type":"spot","hook":"Spot the two moments the feed does the steering.","scene":[{"id":"a","text":"A lonely night watching 'self-improvement'","trick":false},{"id":"b","text":"The feed quietly steers toward grievance","trick":true},{"id":"c","text":"He just wanted to feel less stuck","trick":false},{"id":"d","text":"Hours later, it feels like 'the truth'","trick":true},{"id":"e","text":"He closes the app and sleeps","trick":false}],"why":"The flagged moments are the designed feed steering, not a failing in him.","relearn":"Being funnelled isn't your failing; the feed is designed to steer you.","persona":"Veer","source":"no shame / design"},
  {"id":"rh-006","cat":"the-funnel","type":"spot","hook":"Spot the two moves that pull you deeper, not out.","scene":[{"id":"a","text":"Noticing the escalation as it happens","trick":false},{"id":"b","text":"Following more of the same accounts","trick":true},{"id":"c","text":"Naming it 'a funnel' and stepping back","trick":false},{"id":"d","text":"Liking the angriest clips for more like them","trick":true},{"id":"e","text":"Muting the channels that keep escalating","trick":false}],"why":"Following more and liking rage pull you deeper; naming and muting step you out.","relearn":"Naming and muting steps you out; feeding the feed pulls you deeper.","persona":"any","source":"stepping out"},
  {"id":"rh-007","cat":"the-funnel","type":"branch","hook":"Your feed has slid from gym tips into 'girls are the problem' content.","options":[{"text":"Recognise the funnel and reset what you follow","consequence":"You take back the wheel from the algorithm.","outcome":"out","best":true},{"text":"Keep watching; it's just telling it like it is","consequence":"That slide is the funnel; recognise it and reset your feed."}],"debrief":"Resetting who you follow breaks the algorithm's escalation.","relearn":"You can recognise the funnel and reset your feed to break it.","persona":"Veer","source":"agency"},
  {"id":"rh-008","cat":"the-funnel","type":"branch","hook":"A clip makes you feel, for a second, like everything wrong is someone else's fault.","options":[{"text":"Notice the pull, that's the hook, and pause","consequence":"You catch the manipulation in real time.","outcome":"aware","best":true},{"text":"Lean in; it feels good to blame someone","consequence":"That relief is the hook; noticing it resists it."}],"debrief":"The funnel sells the relief of blame; noticing the pull defuses it.","relearn":"That 'all their fault' relief is the hook; notice it and pause.","persona":"any","source":"emotional manipulation"},
  {"id":"rh-009","cat":"the-funnel","type":"branch","hook":"You realise you've been deep in this content for weeks.","options":[{"text":"No shame, just step back and rebalance your feed","consequence":"You move on without beating yourself up.","outcome":"kind","best":true},{"text":"Feel stupid and give up trying","consequence":"It's designed to pull you in; no shame, just step back."}],"debrief":"Stepping out is the win; self-blame isn't needed and isn't fair.","relearn":"Stepping out needs no shame, the funnel is built to be convincing.","persona":"Veer","source":"no shame"},
  {"id":"rh-010","cat":"the-funnel","type":"branch","hook":"A friend says the extreme stuff is just 'edgy jokes, not serious'.","options":[{"text":"Note the jokes are the on-ramp to the real thing","consequence":"You see how 'ironic' content normalises the rest.","outcome":"clear","best":true},{"text":"Agree it's harmless because it's 'just jokes'","consequence":"'Just jokes' is often the on-ramp; stay aware."}],"debrief":"'Ironic' content often softens the ground for the serious version.","relearn":"'Just jokes' is often the funnel's on-ramp, not harmless.","persona":"any","source":"normalisation"},
  {"id":"rh-011","cat":"the-funnel","type":"strike-rewrite","hook":"\"I sought this out, so it's what I really believe.\"","myth":{"un":"I sought this content out, so it must be what I really believe.","re":"Mostly the algorithm served it to you, on purpose; it isn't your considered view.","why":"Recommendation feeds escalate you without you choosing to."},"relearn":"The algorithm served it; it isn't proof of what you truly believe.","persona":"Veer","source":"algorithm / no shame"},
  {"id":"rh-012","cat":"the-funnel","type":"strike-rewrite","hook":"\"If lots of guys believe it, it must be true.\"","myth":{"un":"So many guys believe it, so it must be true.","re":"A funnel pushing the same content to millions makes it feel true, that's reach, not truth.","why":"Popularity engineered by an algorithm isn't evidence."},"relearn":"Mass reach engineered by a funnel isn't proof that something's true.","persona":"any","source":"popularity vs truth"},
  {"id":"rh-013","cat":"the-funnel","type":"reflect","hook":"Lensy: once you can see the funnel, it loses a lot of its power. Notice that?","prompt":"What do you think?","options":["Yes","I can see it now","It feels less true"],"affirm":"Seeing the machinery is exactly what frees you from it.","relearn":"Seeing the funnel's design is what takes away its power.","persona":"any","source":"media literacy"},
  {"id":"rh-014","cat":"the-funnel","type":"reflect","hook":"Lensy: it makes sense that lonely or stressed moments are when the funnel bites hardest. Fair?","prompt":"What do you think?","options":["Yes","That's when I'm vulnerable","Good to know"],"affirm":"Knowing your vulnerable moments helps you guard them, kindly.","relearn":"The funnel bites hardest in lonely moments; knowing that helps you guard them.","persona":"Veer","source":"vulnerability / compassion"},
  // Follow the money: the grift
  {"id":"rh-015","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that reveal the business behind the 'mentor'.","scene":[{"id":"a","text":"Free clips that make you feel not enough","trick":true},{"id":"b","text":"He seems confident on camera","trick":false},{"id":"c","text":"...then a paid 'academy' that fixes it","trick":true},{"id":"d","text":"Some tips are generic and harmless","trick":false},{"id":"e","text":"His videos are free to watch","trick":false}],"why":"Make you feel lacking, then sell the cure: that's the business model.","relearn":"Making you feel 'not enough' then selling the fix is the grift.","persona":"any","source":"the grift"},
  {"id":"rh-016","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that show what you really are to him.","scene":[{"id":"a","text":"Courses, subscriptions and affiliate links everywhere","trick":true},{"id":"b","text":"He calls you 'brother'","trick":false},{"id":"c","text":"Your attention and money are the product","trick":true},{"id":"d","text":"He posts most days","trick":false},{"id":"e","text":"He has a friendly intro music jingle","trick":false}],"why":"The 'brotherhood' is a funnel to courses and subs; you're the product.","relearn":"To the grifter you're the product; the 'brotherhood' sells courses.","persona":"Veer","source":"you're the product"},
  {"id":"rh-017","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that show why the outrage is manufactured.","scene":[{"id":"a","text":"Deliberately shocking 'hot takes'","trick":true},{"id":"b","text":"He films in a nice car","trick":false},{"id":"c","text":"Outrage drives the views that pay him","trick":true},{"id":"d","text":"He has a big follower count","trick":false},{"id":"e","text":"He uses dramatic background music","trick":false}],"why":"Rage-bait exists because outrage drives the engagement that earns money.","relearn":"Manufactured outrage is rage-bait; it exists to earn engagement and money.","persona":"any","source":"rage-bait economics"},
  {"id":"rh-018","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that 'free advice' isn't really free.","scene":[{"id":"a","text":"Every video ends with 'link in bio'","trick":true},{"id":"b","text":"Some tips are generic and fine","trick":false},{"id":"c","text":"The real pitch is always the paid tier","trick":true},{"id":"d","text":"He replies to a few comments","trick":false},{"id":"e","text":"He has a catchy channel name","trick":false}],"why":"When the destination is always a paywall, the 'advice' is bait.","relearn":"If it always funnels to a paywall, the 'free advice' is a sales pitch.","persona":"any","source":"the grift"},
  {"id":"rh-019","cat":"follow-the-money","type":"sort","hook":"Sort each line: a sign of a grift, or genuine help?","items":[{"id":"a","text":"Telling you you're worthless without his course"},{"id":"b","text":"A coach who wants you to need them less"},{"id":"c","text":"Endless upsells and 'secret' tiers"},{"id":"d","text":"Free, clear guidance with no catch"},{"id":"e","text":"'Pay monthly or you'll never make it'"},{"id":"f","text":"'Try the library first, it's free'"}],"bins":[{"id":"grift","label":"A grift","valence":"neg"},{"id":"genuine","label":"Genuine help","valence":"pos"}],"key":{"a":"grift","b":"genuine","c":"grift","d":"genuine","e":"grift","f":"genuine"},"relearn":"Grifts make you dependent and upsell; real help wants you stronger.","persona":"any","source":"grift vs help"},
  {"id":"rh-020","cat":"follow-the-money","type":"sort","hook":"Sort each move: who profits, you or him?","items":[{"id":"a","text":"You buy the 'academy'"},{"id":"b","text":"You build real skills for free"},{"id":"c","text":"You rage-share his clip"},{"id":"d","text":"You find a free local mentor"},{"id":"e","text":"You click his affiliate link"},{"id":"f","text":"You join a free school club"}],"bins":[{"id":"him","label":"He profits","valence":"uhoh"},{"id":"you","label":"You gain","valence":"pos"}],"key":{"a":"him","b":"you","c":"him","d":"you","e":"him","f":"you"},"relearn":"Buying in and rage-sharing pay him; free skills and real mentors grow you.","persona":"any","source":"follow the money"},
  {"id":"rh-021","cat":"follow-the-money","type":"sort","hook":"Sort each option: real self-improvement, or a sales funnel?","items":[{"id":"a","text":"A library book on confidence"},{"id":"b","text":"A 'high-value male' paid masterclass"},{"id":"c","text":"A school counsellor's free support"},{"id":"d","text":"A subscription to 'unlock alpha secrets'"},{"id":"e","text":"A free workout you follow online"},{"id":"f","text":"A '₹9999 mindset reset' bundle"}],"bins":[{"id":"real","label":"Real growth","valence":"pos"},{"id":"funnel","label":"Sales funnel","valence":"neg"}],"key":{"a":"real","b":"funnel","c":"real","d":"funnel","e":"real","f":"funnel"},"relearn":"Real growth is mostly free; 'secret alpha' tiers are a sales funnel.","persona":"any","source":"real vs grift"},
  {"id":"rh-022","cat":"follow-the-money","type":"strike-rewrite","hook":"\"He's giving me the secret to becoming a man.\"","myth":{"un":"This mentor is giving me the secret to becoming a real man.","re":"He's selling a cure for a problem he invented; you don't need his 'secret'.","why":"The insecurity he stokes is the thing he profits from."},"relearn":"He invented the problem to sell the cure; you don't need his 'secret'.","persona":"Veer","source":"the grift"},
  {"id":"rh-023","cat":"follow-the-money","type":"strike-rewrite","hook":"\"If I pay in, I'll finally belong.\"","myth":{"un":"If I buy into the brotherhood, I'll finally belong.","re":"Real belonging isn't sold; paid 'brotherhoods' keep you paying, not connected.","why":"Genuine connection doesn't run on a subscription."},"relearn":"Real belonging isn't a subscription; it's not something you buy in.","persona":"any","source":"belonging"},
  {"id":"rh-024","cat":"follow-the-money","type":"match","hook":"Match each grift move to what it really is.","pairs":[{"left":"'You're not enough'","right":"The setup for a sale"},{"left":"'Link in bio'","right":"The paywall"},{"left":"Rage-bait take","right":"Engagement for profit"},{"left":"'Spots closing tonight'","right":"Fake urgency"},{"left":"'Members made lakhs'","right":"Unverifiable bait"}],"relearn":"Each grift move, whether the put-down, the link or the rage, exists to earn money.","persona":"any","source":"the grift"},
  {"id":"rh-025","cat":"follow-the-money","type":"match","hook":"Match each promise to the catch behind it.","pairs":[{"left":"'Secret to confidence'","right":"Behind a paywall"},{"left":"'Join the brotherhood'","right":"Monthly subscription"},{"left":"'I'll fix your life'","right":"If you keep buying"},{"left":"'Free masterclass'","right":"A long sales pitch"},{"left":"'One-on-one with me'","right":"A pricey upsell"}],"relearn":"Every big promise here comes with a price tag attached.","persona":"any","source":"follow the money"},
  {"id":"rh-026","cat":"follow-the-money","type":"branch","hook":"A 'mentor' clip leaves you feeling you must buy his course to be okay.","options":[{"text":"Notice the sell, you're the product, and close it","consequence":"You keep your money and your self-worth.","outcome":"free","best":true},{"text":"Buy it, maybe he's right that you're lacking","consequence":"He profits from that feeling; you don't need his course."}],"debrief":"The 'not enough' feeling was manufactured to make the sale.","relearn":"That 'I must buy it' feeling was manufactured; you're already okay.","persona":"Veer","source":"the grift / self-worth"},
  {"id":"rh-027","cat":"follow-the-money","type":"reflect","hook":"Lensy: once you see the salesman behind the 'mentor', does the message lose its grip?","prompt":"What do you think?","options":["Yes","He's just selling","It loosens"],"affirm":"Seeing the incentive is what frees you from the message.","relearn":"Seeing the salesman behind the message takes away its grip.","persona":"any","source":"media literacy"},
  // Spot the hook: bust the claims
  {"id":"rh-028","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"You're not a real man unless you dominate others.\"","myth":{"un":"You're not a real man unless you dominate other people.","re":"Worth isn't a ranking; real strength never needs anyone else to be small.","why":"Dominance is insecurity in costume, not strength."},"relearn":"Worth isn't a rank; real strength doesn't need to make others small.","persona":"Veer","source":"the hook / positive masculinity"},
  {"id":"rh-029","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Women or feminism are why your life is hard.\"","myth":{"un":"Women, or feminism, are the reason your life is hard.","re":"Loneliness and rejection are real and common, and not a group's fault to pin.","why":"Blaming a whole group is the funnel's oldest trick."},"relearn":"Real struggles aren't women's or feminism's fault; blame-a-group is the trick.","persona":"any","source":"the hook / scapegoating"},
  {"id":"rh-030","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"There are 'alpha' and 'beta' males, it's just science.\"","myth":{"un":"Men are 'alphas' and 'betas', it's basic science.","re":"That's pseudo-science; people aren't ranked into wolf-pack tiers.","why":"The 'alpha wolf' idea was debunked even in wolves."},"relearn":"'Alpha/beta males' is pseudo-science, not how people actually are.","persona":"any","source":"pseudo-science"},
  {"id":"rh-031","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"It's men versus women out there.\"","myth":{"un":"It's basically men versus women out there.","re":"Us-vs-them is the manipulation; most people want the same respect and connection.","why":"Turning half of humanity into the enemy serves the grifter, not you."},"relearn":"'Men vs women' is the manipulation; most people want the same things.","persona":"any","source":"us-vs-them"},
  {"id":"rh-032","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Showing feelings makes you weak and unmanly.\"","myth":{"un":"Showing any feelings makes you weak and unmanly.","re":"Naming feelings and asking for help takes real strength.","why":"The 'always hard' mask is a cage, not a strength."},"relearn":"Feeling and asking for help is strength, not weakness.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-033","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Being kind or respectful gets you nowhere.\"","myth":{"un":"Being kind or respectful just gets you walked over.","re":"Respect builds the real relationships and reputation people actually want.","why":"Contempt pushes people away; respect draws them in."},"relearn":"Kindness and respect build what you actually want; contempt repels it.","persona":"any","source":"the hook"},
  {"id":"rh-034","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"If a girl rejects you, she owes you an explanation, or worse.\"","myth":{"un":"If a girl isn't interested, she owes you something.","re":"Everyone can say no; rejection stings but no one owes you their interest.","why":"Entitlement is exactly the mindset the funnel breeds."},"relearn":"No one owes you their interest; everyone can say no.","persona":"any","source":"the hook / consent"},
  {"id":"rh-035","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Real men don't need anyone.\"","myth":{"un":"Real men don't need anyone; needing people is weak.","re":"Everyone needs connection; pretending you don't is what isolates you.","why":"Isolation is what the funnel feeds on."},"relearn":"Everyone needs people; 'needing no one' just isolates you.","persona":"Veer","source":"the hook / belonging"},
  {"id":"rh-036","cat":"spot-the-hook","type":"sort","hook":"Sort: a manosphere hook, or a healthy truth?","items":[{"id":"a","text":"'Dominate or you're nothing'"},{"id":"b","text":"'Respect lifts everyone'"},{"id":"c","text":"'Blame women for your pain'"},{"id":"d","text":"'Your worth isn't a rank'"},{"id":"e","text":"'Kindness is just weakness'"},{"id":"f","text":"'You can grow and still be enough'"}],"bins":[{"id":"hook","label":"A hook","valence":"neg"},{"id":"truth","label":"A healthy truth","valence":"pos"}],"key":{"a":"hook","b":"truth","c":"hook","d":"truth","e":"hook","f":"truth"},"relearn":"Domination and blame are hooks; respect and self-worth are the truths.","persona":"any","source":"hook vs truth"},
  {"id":"rh-037","cat":"spot-the-hook","type":"sort","hook":"Sort: real science, or pseudo-science dressed up?","items":[{"id":"a","text":"'Alpha/beta male hierarchy'"},{"id":"b","text":"People have varied, changeable strengths"},{"id":"c","text":"'High-value vs low-value humans'"},{"id":"d","text":"Everyone has equal worth"},{"id":"e","text":"'Sigma males are a real type'"},{"id":"f","text":"Confidence is built, not a 'tier'"}],"bins":[{"id":"pseudo","label":"Pseudo-science","valence":"neg"},{"id":"real","label":"Real / true","valence":"pos"}],"key":{"a":"pseudo","b":"real","c":"pseudo","d":"real","e":"pseudo","f":"real"},"relearn":"Ranking people into 'alpha', 'sigma' or 'value' tiers is pseudo-science.","persona":"any","source":"pseudo-science"},
  {"id":"rh-038","cat":"spot-the-hook","type":"sort","hook":"Sort: builds you up honestly, or hooks you?","items":[{"id":"a","text":"'You're already enough, and can grow'"},{"id":"b","text":"'You're worthless until you obey me'"},{"id":"c","text":"'Improve for yourself'"},{"id":"d","text":"'Hate them to feel strong'"},{"id":"e","text":"'You only matter if you win'"},{"id":"f","text":"'Your value isn't up for a vote'"}],"bins":[{"id":"build","label":"Builds you up","valence":"pos"},{"id":"hook","label":"Hooks you","valence":"neg"}],"key":{"a":"build","b":"hook","c":"build","d":"hook","e":"hook","f":"build"},"relearn":"Honest growth says you're enough and can improve; hooks trade on hate and worthlessness.","persona":"any","source":"build vs hook"},
  {"id":"rh-039","cat":"spot-the-hook","type":"sort","hook":"Sort: the unmet need, vs the toxic 'answer' sold for it.","items":[{"id":"a","text":"Wanting belonging"},{"id":"b","text":"'Join us in hating them'"},{"id":"c","text":"Wanting respect"},{"id":"d","text":"'Dominate to be respected'"},{"id":"e","text":"Wanting to feel less alone"},{"id":"f","text":"'Cut off anyone softer than you'"}],"bins":[{"id":"need","label":"A real need","valence":"pos"},{"id":"toxic","label":"The toxic 'answer'","valence":"neg"}],"key":{"a":"need","b":"toxic","c":"need","d":"toxic","e":"need","f":"toxic"},"relearn":"The needs (belonging, respect) are real; the hateful 'answers' sold for them aren't.","persona":"any","source":"need vs answer"},
  {"id":"rh-040","cat":"spot-the-hook","type":"spot","hook":"Spot the two manipulation moves in the pitch.","scene":[{"id":"a","text":"'Everyone's laughing at you'","trick":true},{"id":"b","text":"'Here's a free workout you can try'","trick":false},{"id":"c","text":"'Only I can save you from being a loser'","trick":true},{"id":"d","text":"'Plenty of people would be glad to know you'","trick":false},{"id":"e","text":"'Rest days are fine, you're not behind'","trick":false}],"why":"Shame ('everyone's laughing') plus a saviour offer ('only I can save you') is manipulation, not mentoring.","relearn":"Shaming you then offering to 'save' you is manipulation.","persona":"any","source":"emotional manipulation"},
  {"id":"rh-041","cat":"spot-the-hook","type":"spot","hook":"Spot the two lines that hijack a real need with contempt.","scene":[{"id":"a","text":"'Girls hate you, so hate them back'","trick":true},{"id":"b","text":"Wanting to be liked is a normal wish","trick":false},{"id":"c","text":"'You're owed attention you didn't get'","trick":true},{"id":"d","text":"Connection grows from respect, not blame","trick":false},{"id":"e","text":"Rejection stings, and it passes","trick":false}],"why":"'Hate them back' and 'you're owed attention' twist a real need for connection into contempt.","relearn":"Under the hook is a real need for connection, met by respect.","persona":"Veer","source":"the need underneath"},
  {"id":"rh-042","cat":"spot-the-hook","type":"reflect","hook":"Lensy: the hooks are designed to be convincing, finding them convincing once isn't a flaw in you. Okay?","prompt":"What do you think?","options":["Yes","That's reassuring","No shame then"],"affirm":"They're engineered by pros; seeing through them now is what counts.","relearn":"The hooks are engineered to convince; seeing through them is the win.","persona":"any","source":"no shame"},
  // Real Strong: positive masculinity
  {"id":"rh-043","cat":"real-strong","type":"reflect","hook":"Lensy: real strength lifts people, it never needs anyone else to be small. Sit with that.","prompt":"What do you think?","options":["I like that","That's real strength","Yes"],"affirm":"That's the whole idea, strength that builds, not belittles.","relearn":"Real strength lifts people; it never needs anyone else to be small.","persona":"Veer","source":"positive masculinity (heart)"},
  {"id":"rh-044","cat":"real-strong","type":"reflect","hook":"Lensy: you can be ambitious and disciplined AND kind and respectful. Does that fit you?","prompt":"What do you think?","options":["Yes","I want that","Both at once"],"affirm":"Strong and kind isn't a contradiction, it's the goal.","relearn":"Ambition and discipline live happily alongside kindness and respect.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-045","cat":"real-strong","type":"reflect","hook":"Lensy: you can want love and respect without putting anyone down to get it. Agree?","prompt":"What do you think?","options":["Yes","Of course","That's better"],"affirm":"Wanting connection is human, and contempt only gets in its way.","relearn":"You can want love and respect without belittling anyone.","persona":"any","source":"positive masculinity"},
  {"id":"rh-046","cat":"real-strong","type":"reflect","hook":"Lensy: confidence is built, not bought. What actually builds yours?","prompt":"Pick one.","options":["Real skills and effort","Good friends","Living by my values"],"affirm":"All of those are real and yours, no subscription required.","relearn":"Real confidence is built through skills, friends and values, not bought.","persona":"Veer","source":"confidence"},
  {"id":"rh-047","cat":"real-strong","type":"reflect","hook":"Lensy: the truth the grift hides, you're already enough, and you can still grow. Both true?","prompt":"What do you think?","options":["Yes","Both","Good to hear"],"affirm":"You're enough as you are, and growth is yours to choose, no contradiction.","relearn":"You're already enough, and you can still grow, both are true.","persona":"any","source":"self-worth"},
  {"id":"rh-048","cat":"real-strong","type":"reflect","hook":"Lensy: which real model of strength do you most admire?","prompt":"Pick one.","options":["Someone calm under pressure","Someone who lifts others up","Someone true to their values"],"affirm":"That's a strength worth growing toward, and it's all within reach.","relearn":"The strength worth admiring is calm, lifting others, and true to values.","persona":"any","source":"role models"},
  {"id":"rh-049","cat":"real-strong","type":"sort","hook":"Sort: healthy strength, or the toxic imitation?","items":[{"id":"a","text":"Protecting people smaller than you"},{"id":"b","text":"Belittling people to feel big"},{"id":"c","text":"Owning a mistake"},{"id":"d","text":"Never admitting you're wrong"},{"id":"e","text":"Staying calm when someone provokes you"},{"id":"f","text":"Needing everyone to fear you"}],"bins":[{"id":"healthy","label":"Real strength","valence":"pos"},{"id":"toxic","label":"Toxic imitation","valence":"neg"}],"key":{"a":"healthy","b":"toxic","c":"healthy","d":"toxic","e":"healthy","f":"toxic"},"relearn":"Protecting and owning mistakes is strength; belittling and bravado isn't.","persona":"any","source":"positive masculinity"},
  {"id":"rh-050","cat":"real-strong","type":"sort","hook":"Sort: meets the need in a healthy way, or a toxic way?","items":[{"id":"a","text":"Belonging via real friends"},{"id":"b","text":"Belonging via hating a group"},{"id":"c","text":"Purpose via things that matter"},{"id":"d","text":"Purpose via dominating others"},{"id":"e","text":"Respect earned by how you treat people"},{"id":"f","text":"'Respect' demanded through fear"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"toxic","label":"Toxic","valence":"neg"}],"key":{"a":"healthy","b":"toxic","c":"healthy","d":"toxic","e":"healthy","f":"toxic"},"relearn":"Real friends and real purpose meet the need; hate and domination don't.","persona":"any","source":"healthy needs"},
  {"id":"rh-051","cat":"real-strong","type":"sort","hook":"Sort: a green flag of positive masculinity, or not?","items":[{"id":"a","text":"Strong and gentle"},{"id":"b","text":"Respects a 'no'"},{"id":"c","text":"Needs others to lose"},{"id":"d","text":"Mocks anyone different"},{"id":"e","text":"Cheers a friend's win"},{"id":"f","text":"Has to be the loudest in the room"}],"bins":[{"id":"green","label":"Positive","valence":"pos"},{"id":"no","label":"Not","valence":"neg"}],"key":{"a":"green","b":"green","c":"no","d":"no","e":"green","f":"no"},"relearn":"Strong-and-gentle and respecting 'no' are positive; needing others to lose isn't.","persona":"any","source":"green flags"},
  {"id":"rh-052","cat":"real-strong","type":"sort","hook":"Sort: equality frees boys (true), or 'men lose' (the myth)?","items":[{"id":"a","text":"Less pressure to always be tough"},{"id":"b","text":"'Equality means men get nothing'"},{"id":"c","text":"Freedom to feel and connect"},{"id":"d","text":"'Sharing makes you less of a man'"},{"id":"e","text":"You can ask for help without shame"},{"id":"f","text":"'Real men never need anyone'"}],"bins":[{"id":"frees","label":"Frees boys (true)","valence":"pos"},{"id":"myth","label":"The myth","valence":"neg"}],"key":{"a":"frees","b":"myth","c":"frees","d":"myth","e":"frees","f":"myth"},"relearn":"Equality frees boys from the 'always tough' cage; 'men lose' is the myth.","persona":"Veer","source":"links g26 / equality"},
  {"id":"rh-053","cat":"real-strong","type":"branch","hook":"You want to improve yourself for real. What's the healthy route?","options":[{"text":"Build skills, real friends and purpose, no contempt","consequence":"You grow in ways that last and lift you.","outcome":"real","best":true},{"text":"Buy the 'alpha' course and look down on others","consequence":"Real growth needs skills and connection, not a paywall."}],"debrief":"Genuine self-improvement is skills, connection and purpose, freely yours.","relearn":"Improve through skills, friends and purpose, not courses.","persona":"Veer","source":"real growth"},
  {"id":"rh-054","cat":"real-strong","type":"branch","hook":"You feel the pull to prove you're 'high value' by putting someone down.","options":[{"text":"Choose to lift instead, that's the stronger move","consequence":"You feel genuinely good and others respect it.","outcome":"strong","best":true},{"text":"Put them down to feel above them","consequence":"Belittling is the weak move; lifting others is real strength."}],"debrief":"The strong move is to raise people, not rank yourself above them.","relearn":"Lifting someone up is stronger than putting them down.","persona":"any","source":"positive masculinity"},
  {"id":"rh-055","cat":"real-strong","type":"role-play","hook":"A friend says respect is 'soft'. Offer the better view.","setup":"Reframe strength. Say:","yourLine":[{"text":"\"Real strength lifts people. You don't have to make anyone small to be big.\"","best":true},{"text":"\"Yeah, you have to be ruthless to win.\""}],"relearn":"Real strength lifts people; you don't make others small to be big.","persona":"Veer","source":"positive masculinity voice"},
  {"id":"rh-056","cat":"real-strong","type":"role-play","hook":"A younger boy asks you what being 'a real man' means.","setup":"Give him a better answer. Say:","yourLine":[{"text":"\"Be strong and kind, work hard, respect people, and be yourself, that's it.\"","best":true},{"text":"\"Dominate everyone and never show feelings.\""}],"relearn":"Tell him: strong and kind, hardworking, respectful, yourself.","persona":"any","source":"mentoring / positive masculinity"},
  {"id":"rh-057","cat":"real-strong","type":"match","hook":"Match the real need to the healthy way to meet it.","pairs":[{"left":"Belonging","right":"Real friends and community"},{"left":"Identity","right":"Your own values"},{"left":"Confidence","right":"Built through effort"},{"left":"Respect","right":"How you treat people"},{"left":"Purpose","right":"Things that actually matter to you"}],"relearn":"Belonging, identity and confidence have healthy sources, not a guru's paywall.","persona":"any","source":"healthy needs"},
  {"id":"rh-058","cat":"real-strong","type":"match","hook":"Match the cage to the freedom equality offers boys.","pairs":[{"left":"'Always be tough'","right":"Allowed to feel"},{"left":"'Always the provider'","right":"Share the load"},{"left":"'Never need help'","right":"Free to ask"},{"left":"'Never cry'","right":"Allowed to be human"},{"left":"'Lead by force'","right":"Lead by respect"}],"relearn":"Equality frees boys from the toughness, provider and 'no help' cages.","persona":"Veer","source":"links g26"},
  // Have each other's backs
  {"id":"rh-059","cat":"have-each-others-backs","type":"branch","hook":"A close friend is starting to repeat manosphere talking points.","options":[{"text":"Stay connected and ask real questions, don't mock him","consequence":"He stays open to you instead of digging in.","outcome":"call-in","best":true},{"text":"Mock him and call him a creep","consequence":"Mockery pushes him deeper; staying connected works better."}],"debrief":"Calling-in (staying close, asking questions) reaches him; calling-out doesn't.","relearn":"Help a friend by staying connected and asking, not mocking.","persona":"any","source":"call-in (evidence)"},
  {"id":"rh-060","cat":"have-each-others-backs","type":"branch","hook":"Your friend in the funnel seems lonely underneath it all.","options":[{"text":"Be the belonging the funnel was offering him","consequence":"He has a real connection that competes with the feed.","outcome":"belonging","best":true},{"text":"Write him off and drop him","consequence":"Dropping him leaves only the funnel; be the real belonging instead."}],"debrief":"Real friendship competes directly with what the funnel sells.","relearn":"Being a real friend offers the belonging the funnel was faking.","persona":"Veer","source":"belonging / call-in"},
  {"id":"rh-061","cat":"have-each-others-backs","type":"branch","hook":"A friend's views are getting genuinely worrying, beyond your help.","options":[{"text":"Keep caring, and loop in a trusted adult","consequence":"He gets support bigger than either of you.","outcome":"help","best":true},{"text":"Handle it all yourself or give up","consequence":"For the worrying stuff, loop in a trusted adult, gently."}],"debrief":"You can stay his friend and still bring in an adult's help.","relearn":"If it's beyond you, keep caring and loop in a trusted adult.","persona":"any","source":"safeguarding / call-in"},
  {"id":"rh-062","cat":"have-each-others-backs","type":"branch","hook":"You're a girl seeing this stuff aimed your way; it tries to make you small.","options":[{"text":"Refuse to absorb it; your worth isn't theirs to set","consequence":"You keep your sense of self intact.","outcome":"resilient","best":true},{"text":"Believe the worst it says about you","consequence":"Don't absorb it, your worth isn't set by online contempt."}],"debrief":"Recognising it as manipulation lets you refuse to internalise it.","relearn":"You can refuse to absorb online misogyny; your worth isn't theirs to set.","persona":"Riya","source":"for everyone / resilience"},
  {"id":"rh-063","cat":"have-each-others-backs","type":"branch","hook":"Boys in your class are quoting a misogynist influencer at girls to get a reaction.","options":[{"text":"Don't reward it; name it calmly or get a teacher","consequence":"You deny the rage-bait its payoff and protect classmates.","outcome":"upstander","best":true},{"text":"Laugh so you fit in","consequence":"Laughing rewards it; naming it or a teacher is better."}],"debrief":"Not feeding the reaction, and naming it, takes away its power.","relearn":"Don't reward provocation; name it calmly or tell a teacher.","persona":"Riya","source":"links g27 / upstander"},
  {"id":"rh-064","cat":"have-each-others-backs","type":"branch","hook":"You realise mocking your friend last week pushed him further in.","options":[{"text":"Reconnect warmly; it's not too late to be his friend","consequence":"You reopen the door the mockery closed.","outcome":"repair","best":true},{"text":"Decide he's a lost cause now","consequence":"It's rarely too late; reconnecting still helps."}],"debrief":"Reconnection can undo the push that call-out caused.","relearn":"It's rarely too late to reconnect and be a real friend again.","persona":"any","source":"call-in / repair"},
  {"id":"rh-065","cat":"have-each-others-backs","type":"role-play","hook":"You want to open a caring conversation with a friend who's changing.","setup":"Lead with care, not accusation. Say:","yourLine":[{"text":"\"Hey, I've missed hanging out, how are you really doing lately?\"","best":true},{"text":"\"You've turned into a sexist idiot.\""}],"relearn":"Open with care and curiosity, not accusation, to reach a friend.","persona":"any","source":"call-in voice"},
  {"id":"rh-066","cat":"have-each-others-backs","type":"role-play","hook":"Your friend repeats a blame-women line. Respond without a fight.","setup":"Ask a real question. Say:","yourLine":[{"text":"\"What's really going on for you? That doesn't sound like the you I know.\"","best":true},{"text":"\"Shut up, you sound pathetic.\""}],"relearn":"A real, caring question reaches further than an insult.","persona":"Veer","source":"call-in voice"},
  {"id":"rh-067","cat":"have-each-others-backs","type":"role-play","hook":"A friend admits the content made him feel less alone, and ashamed of that.","setup":"Take the shame off him. Say:","yourLine":[{"text":"\"That makes sense, it's built to do that. No shame. I'm here, for real.\"","best":true},{"text":"\"That's so weak of you.\""}],"relearn":"Normalise the need, drop the shame, and offer real connection.","persona":"any","source":"no shame / belonging"},
  {"id":"rh-068","cat":"have-each-others-backs","type":"role-play","hook":"A girl friend is shaken by misogynist abuse online. Support her.","setup":"Have her back. Say:","yourLine":[{"text":"\"That's on them, not you. You don't have to take it, let's report it.\"","best":true},{"text":"\"Just ignore it, it's no big deal.\""}],"relearn":"Back up someone targeted: it's on them, and offer to help report it.","persona":"Riya","source":"for everyone / support"},
  {"id":"rh-069","cat":"have-each-others-backs","type":"reflect","hook":"Lensy: writing someone off vs staying connected, which actually helps them out?","prompt":"What do you think?","options":["Staying connected","Being there","Not mocking them"],"affirm":"Connection is what competes with the funnel, mockery just feeds it.","relearn":"Staying connected helps a friend out; writing them off pushes them in.","persona":"any","source":"call-in"},
  {"id":"rh-070","cat":"have-each-others-backs","type":"reflect","hook":"Lensy: for everyone, refusing to absorb or spread online misogyny is its own quiet power. Feel that?","prompt":"What do you think?","options":["Yes","I won't absorb it","Quiet power"],"affirm":"Every person who won't pass it on shrinks its reach.","relearn":"Refusing to absorb or spread misogyny is real, quiet power.","persona":"any","source":"for everyone"},
  {"id":"rh-071","cat":"have-each-others-backs","type":"reflect","hook":"Lensy: what kind of friend do you want to be if someone you love starts slipping?","prompt":"Pick one.","options":["The one who stays","The one who asks","The one who gets help"],"affirm":"Any of those could be the thing that brings them back.","relearn":"Staying, asking and getting help are how you bring a friend back.","persona":"any","source":"identity"},
  {"id":"rh-072","type":"sort","hook":"Sort: pulls a friend back, or pushes them deeper?","items":[{"id":"a","text":"Staying connected"},{"id":"b","text":"Public mockery"},{"id":"c","text":"Asking real questions"},{"id":"d","text":"Writing them off"},{"id":"e","text":"Listening without judging"},{"id":"f","text":"Calling him names in the chat"}],"bins":[{"id":"back","label":"Pulls them back","valence":"pos"},{"id":"deeper","label":"Pushes them in","valence":"neg"}],"key":{"a":"back","b":"deeper","c":"back","d":"deeper","e":"back","f":"deeper"},"relearn":"Connection and questions pull a friend back; mockery and rejection push them in.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  // The need underneath: get help
  {"id":"rh-073","cat":"the-need-underneath","type":"reflect","hook":"Lensy: the loneliness or insecurity the funnel preys on is real, and really common. Okay to admit?","prompt":"What do you think?","options":["Yes","I feel it sometimes","Good to name it"],"affirm":"Naming it honestly is the opposite of weakness, it's the start of help.","relearn":"The loneliness the funnel preys on is real and common; naming it is strength.","persona":"Veer","source":"the need underneath"},
  {"id":"rh-074","cat":"the-need-underneath","type":"reflect","hook":"Lensy: reaching out for support when you feel low is one of the strongest things you can do. Agree?","prompt":"What do you think?","options":["Yes","That's real strength","I can do that"],"affirm":"Asking for help is strength in action, full stop.","relearn":"Reaching for support when low is genuine strength.","persona":"any","source":"help-seeking"},
  {"id":"rh-075","cat":"the-need-underneath","type":"reflect","hook":"Lensy: who or what helps you feel you belong, in real life?","prompt":"Pick one.","options":["A good friend","Family","A team or hobby","Something I'm building"],"affirm":"That's real belonging, worth more than any 'brotherhood' for sale.","relearn":"Real belonging, friends, family, a team, beats anything sold online.","persona":"any","source":"belonging"},
  {"id":"rh-076","cat":"the-need-underneath","type":"branch","hook":"You've been feeling low and isolated, and the funnel keeps offering 'answers'.","options":[{"text":"Talk to a trusted adult or call Tele-MANAS 14416","consequence":"You meet the real need with real support.","outcome":"help","best":true},{"text":"Keep filling the gap with the feed","consequence":"The feed exploits the gap; real support fills it, an adult or 14416."}],"debrief":"The honest fix for loneliness is real connection.","relearn":"Feeling low? A trusted adult or Tele-MANAS 14416 meets the real need.","persona":"Veer","source":"Tele-MANAS (verified)"},
  {"id":"rh-077","cat":"the-need-underneath","type":"branch","hook":"A friend confides he's been feeling worthless, which is why the content appealed.","options":[{"text":"Take it seriously and help him reach support","consequence":"He gets real help for the real hurt.","outcome":"caring","best":true},{"text":"Tell him to just man up","consequence":"'Man up' is the trap; take it seriously and help him find support."}],"debrief":"Meeting the hurt with care, and real help, is what actually works.","relearn":"Help a hurting friend reach support; 'man up' only deepens it.","persona":"any","source":"support / wellbeing"},
  {"id":"rh-078","cat":"the-need-underneath","type":"branch","hook":"You're being harassed online with misogynist abuse and it's getting to you.","options":[{"text":"Save evidence, report it, and tell someone you trust","consequence":"You get support and the abuse is on record.","outcome":"supported","best":true},{"text":"Absorb it silently","consequence":"You don't have to carry it alone; save evidence, report, tell someone."}],"debrief":"Targeted abuse is reportable, and you deserve support.","relearn":"For online misogynist abuse: save evidence, report, and tell someone.","persona":"Riya","source":"harassment routing"},
  {"id":"rh-079","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Asking for help means I've failed as a man.\"","myth":{"un":"Asking for help means I've failed as a man.","re":"Asking for help is strength and good sense; everyone needs it sometimes.","why":"The 'never need help' rule is exactly what isolates and traps boys."},"relearn":"Asking for help is strength, not failure.","persona":"Veer","source":"help-seeking / wellbeing"},
  {"id":"rh-080","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"If I feel lonely, something's wrong with me.\"","myth":{"un":"Feeling lonely means something's wrong with me.","re":"Loneliness is a common human signal, not a defect; it's a cue to connect.","why":"The funnel reframes a normal feeling as a personal failure to exploit it."},"relearn":"Loneliness is a normal signal to connect, not a defect in you.","persona":"any","source":"wellbeing"},
  {"id":"rh-081","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"There's no real help for how I feel.\"","myth":{"un":"There's no real help for how I feel.","re":"There is, trusted people and services like Tele-MANAS 14416 are there for exactly this.","why":"Believing 'no help exists' is part of what keeps you stuck."},"relearn":"Real help exists, trusted people and Tele-MANAS 14416, for how you feel.","persona":"Counsellor","source":"Tele-MANAS (verified)"},
  {"id":"rh-082","cat":"the-need-underneath","type":"match","hook":"Match the need to where real help is (India).","pairs":[{"left":"Loneliness or low mood","right":"Tele-MANAS 14416"},{"left":"Right now, in person","right":"A trusted adult"},{"left":"Online misogynist abuse","right":"cybercrime.gov.in / 1930"},{"left":"A child being harassed","right":"Childline 1098"},{"left":"Wanting to belong","right":"A real-life team or club"}],"relearn":"India help: Tele-MANAS 14416, a trusted adult, cybercrime.gov.in / 1930, Childline 1098.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"rh-083","cat":"the-need-underneath","type":"match","hook":"Match the feeling to the truth that answers it.","pairs":[{"left":"'I'm not enough'","right":"You already are"},{"left":"'I'm alone'","right":"Connection is out there"},{"left":"'It's their fault I hurt'","right":"The hurt is real, the blame isn't"},{"left":"'Nothing will ever help'","right":"Real help exists"},{"left":"'I must always be tough'","right":"You can just be human"}],"relearn":"You're enough, you're not alone, and the hurt is real even when the blame is misplaced.","persona":"any","source":"self-worth"},
  {"id":"rh-084","cat":"the-need-underneath","type":"role-play","hook":"You want to check in on a mate who's gone quiet and angry online.","setup":"Reach out simply. Say:","yourLine":[{"text":"\"Thinking of you, mate. Want to hang out this week, just us?\"","best":true},{"text":"Say nothing; it's not your problem"}],"relearn":"A simple, warm check-in can reach a friend the funnel is isolating.","persona":"any","source":"connection"},
  {"id":"rh-900","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that say this 'free advice' is a sale.","scene":[{"id":"a","text":"'Spots closing tonight, last chance to enrol'","trick":true},{"id":"b","text":"He shares one decent study tip","trick":false},{"id":"c","text":"Fake countdown timer on the sales page","trick":true},{"id":"d","text":"He replies to a few comments","trick":false},{"id":"e","text":"His videos are free to watch","trick":false}],"why":"Fake urgency and a fake timer are pressure tricks to rush a sale, not real scarcity.","relearn":"Fake 'spots closing' urgency is a sales pressure trick, not real scarcity.","persona":"any","source":"fake scarcity"},
  {"id":"rh-901","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in this 'transformation' pitch.","scene":[{"id":"a","text":"Before-after screenshots you can't verify","trick":true},{"id":"b","text":"He says practice takes time","trick":false},{"id":"c","text":"'Members made lakhs' with no proof","trick":true},{"id":"d","text":"He admits he had help too","trick":false},{"id":"e","text":"He names one free book","trick":false}],"why":"Unverifiable before-afters and 'made lakhs' claims are bait dressed up as proof.","relearn":"Unverifiable 'transformations' and income claims are bait, not evidence.","persona":"Veer","source":"fake testimonials"},
  {"id":"rh-902","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags hiding in this 'brotherhood' channel.","scene":[{"id":"a","text":"A free public chat to hang out","trick":false},{"id":"b","text":"'Real members pay for the VIP tier'","trick":true},{"id":"c","text":"You're nudged to recruit your friends in","trick":true},{"id":"d","text":"Some members just chat about games","trick":false},{"id":"e","text":"You can leave any time","trick":false}],"why":"A paywalled 'VIP' tier and pressure to recruit friends are how the funnel grows his income.","relearn":"A paid 'VIP' tier plus 'recruit your friends' is a sales funnel, not a brotherhood.","persona":"any","source":"recruit funnel"},
  {"id":"rh-903","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in why his takes keep getting nastier.","scene":[{"id":"a","text":"Each clip is angrier than the last","trick":true},{"id":"b","text":"He sometimes posts a calm one","trick":false},{"id":"c","text":"He says outrage 'gets him paid'","trick":true},{"id":"d","text":"Comments are full of arguments","trick":false},{"id":"e","text":"He has a normal day job too","trick":false}],"why":"Escalating anger that he admits 'gets him paid' is engineered rage-bait for engagement money.","relearn":"Takes that get angrier to 'get paid' are engineered rage-bait for engagement.","persona":"any","source":"rage-bait economics"},
  {"id":"rh-904","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that this 'mentor' wants you dependent.","scene":[{"id":"a","text":"'You'll fail without me' on repeat","trick":true},{"id":"b","text":"He shares a free checklist","trick":false},{"id":"c","text":"Every answer ends in 'buy the next tier'","trick":true},{"id":"d","text":"He says you can ask a teacher too","trick":false},{"id":"e","text":"Some lessons are genuinely useful","trick":false}],"why":"'You'll fail without me' plus endless upsells keeps you paying, not growing.","relearn":"'You'll fail without me' plus upsells keeps you dependent, not stronger.","persona":"Veer","source":"dependence vs help"},
  {"id":"rh-905","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags behind his flexed 'success'.","scene":[{"id":"a","text":"Rented supercar, captioned 'my grind'","trick":true},{"id":"b","text":"He admits some clips are staged","trick":false},{"id":"c","text":"'Buy my course to live like this'","trick":true},{"id":"d","text":"He has a normal flat off-camera","trick":false},{"id":"e","text":"He talks about long hours","trick":false}],"why":"A rented flex used to sell a course is borrowed proof: the real income is your payment, not his car.","relearn":"A rented 'success' flex used to sell a course is borrowed proof, not real wealth.","persona":"any","source":"borrowed flex"},
  {"id":"rh-906","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in this 'side hustle' upsell.","scene":[{"id":"a","text":"'My system makes money while you sleep'","trick":true},{"id":"b","text":"He says jobs take real skill","trick":false},{"id":"c","text":"Pay ₹4999 now to 'unlock the method'","trick":true},{"id":"d","text":"He suggests learning a real trade","trick":false},{"id":"e","text":"Some advice is just 'save a bit'","trick":false}],"why":"'Money while you sleep' behind an unlock fee is a get-rich pitch; only he earns.","relearn":"'Money while you sleep' behind a fee is a get-rich pitch; only he earns.","persona":"any","source":"side-hustle upsell"},
  {"id":"rh-907","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that 'DM me' is a funnel, not a favour.","scene":[{"id":"a","text":"'DM me and I'll change your life'","trick":true},{"id":"b","text":"He answers some questions publicly","trick":false},{"id":"c","text":"The DM just sends a payment link","trick":true},{"id":"d","text":"He points to a free helpline once","trick":false},{"id":"e","text":"His bio has a real email too","trick":false}],"why":"A 'DM me' that only ever sends a payment link is a sales funnel wearing a personal favour.","relearn":"A 'DM me' that only ends in a payment link is a sales funnel, not a favour.","persona":"any","source":"DM funnel"},
  {"id":"rh-908","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in this 'free trial' offer.","scene":[{"id":"a","text":"'Free for 3 days' in big letters","trick":true},{"id":"b","text":"The price is shown clearly too","trick":false},{"id":"c","text":"Auto-renews at a high price, hidden small","trick":true},{"id":"d","text":"You can cancel from settings","trick":false},{"id":"e","text":"There's a refund policy listed","trick":false}],"why":"A loud 'free trial' hiding an auto-renew is designed so you forget and get charged: that's the catch.","relearn":"A loud 'free trial' with a hidden auto-renew is built to charge you quietly.","persona":"any","source":"trial trap"},
  {"id":"rh-909","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that this 'truth nobody tells you' is a hook.","scene":[{"id":"a","text":"'The secret they don't want you to know'","trick":true},{"id":"b","text":"He explains one idea simply","trick":false},{"id":"c","text":"'Full secret only inside my paid group'","trick":true},{"id":"d","text":"He says he's still learning too","trick":false},{"id":"e","text":"He credits a free resource once","trick":false}],"why":"A 'secret' only ever 'inside the paid group' is a curiosity hook for the sale.","relearn":"A 'secret only in the paid group' is a curiosity hook for the sale.","persona":"Veer","source":"secret-hook"},
  {"id":"rh-910","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that this 'community' is really a paywall.","scene":[{"id":"a","text":"Friendly welcome message to newcomers","trick":false},{"id":"b","text":"'Only paying members are real men here'","trick":true},{"id":"c","text":"Free members get mocked until they pay","trick":true},{"id":"d","text":"There's a free events channel","trick":false},{"id":"e","text":"People share music and memes","trick":false}],"why":"Gating respect behind payment and shaming free members is the paywall selling.","relearn":"Gating respect behind payment is a paywall, not a community.","persona":"any","source":"paywall pressure"},
  {"id":"rh-911","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in how he 'helps for free'.","scene":[{"id":"a","text":"'Comment FREE and I'll send the guide'","trick":true},{"id":"b","text":"He does reply to comments","trick":false},{"id":"c","text":"The 'guide' is a 20-page ad for his course","trick":true},{"id":"d","text":"One tip in it is actually usable","trick":false},{"id":"e","text":"He links a free library site once","trick":false}],"why":"A 'free guide' that's mostly a course ad is bait; the comment just collects you.","relearn":"A 'free guide' that's mostly a course ad is bait to reel you in.","persona":"any","source":"lead-magnet bait"},
  {"id":"rh-912","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that hate-watching still pays him.","scene":[{"id":"a","text":"'Even haters boost my numbers', he brags","trick":true},{"id":"b","text":"Some viewers genuinely disagree","trick":false},{"id":"c","text":"He baits arguments to lift watch-time","trick":true},{"id":"d","text":"He has off-platform interests too","trick":false},{"id":"e","text":"Comments are mostly strangers","trick":false}],"why":"Baiting arguments to lift watch-time means even angry viewing pays him: outrage is the product.","relearn":"Baiting arguments lifts his watch-time, so even hate-watching pays him.","persona":"any","source":"watch-time economics"},
  {"id":"rh-913","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that 'masculinity tips' are a storefront.","scene":[{"id":"a","text":"Affiliate links under every single video","trick":true},{"id":"b","text":"He films at home, plainly","trick":false},{"id":"c","text":"'Use my code' supplements he's paid to push","trick":true},{"id":"d","text":"He admits one product didn't work","trick":false},{"id":"e","text":"He recommends free gym workouts too","trick":false}],"why":"Affiliate links and paid 'use my code' pushes make the 'tips' a storefront.","relearn":"Affiliate links and paid 'use my code' pushes make it a storefront.","persona":"any","source":"affiliate storefront"},
  {"id":"rh-914","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in this 'mentor invented your problem'.","scene":[{"id":"a","text":"'You're broken and unmanly', every clip","trick":true},{"id":"b","text":"He sometimes says rest matters","trick":false},{"id":"c","text":"'My academy is the only fix', every clip","trick":true},{"id":"d","text":"He admits he's not a doctor","trick":false},{"id":"e","text":"One video is just a recipe","trick":false}],"why":"Calling you broken, then selling the 'only fix', invents a problem to sell a cure.","relearn":"Calling you broken then selling the 'fix' invents a problem to sell a cure.","persona":"Veer","source":"invented problem"},
  {"id":"rh-915","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags that this 'ranking quiz' is a sales tool.","scene":[{"id":"a","text":"'Take my quiz: are you alpha or beta?'","trick":true},{"id":"b","text":"The quiz is free to take","trick":false},{"id":"c","text":"Every result says 'fix it with my course'","trick":true},{"id":"d","text":"It asks your email at the end","trick":false},{"id":"e","text":"He posts the link in his bio","trick":false}],"why":"A quiz whose every result sells his course is a sales tool; 'alpha/beta' is made up.","relearn":"A quiz that always ends in 'buy my course' is a sales tool, not a test.","persona":"any","source":"quiz funnel"},
  {"id":"rh-916","cat":"follow-the-money","type":"spot","hook":"Spot the two red flags in this 'limited cohort' pitch.","scene":[{"id":"a","text":"'Only 10 seats ever', yet it reopens monthly","trick":true},{"id":"b","text":"He lists what the course covers","trick":false},{"id":"c","text":"'Price doubles at midnight' on a fresh timer","trick":true},{"id":"d","text":"There's a written refund policy","trick":false},{"id":"e","text":"He answers a syllabus question","trick":false}],"why":"Seats that always reopen and a resetting timer are fake scarcity to rush you.","relearn":"'Limited seats' that reopen and resetting timers are fake scarcity.","persona":"any","source":"fake scarcity"},
  {"id":"rh-917","cat":"follow-the-money","type":"sort","hook":"Sort each line: a grift tell, or genuine help?","items":[{"id":"a","text":"'Buy now or stay a loser forever'"},{"id":"b","text":"'Here's a free plan, no email needed'"},{"id":"c","text":"'Spots vanish at midnight!' fake timer"},{"id":"d","text":"'Try it, then decide what suits you'"},{"id":"e","text":"'Only my paid tier has the answer'"},{"id":"f","text":"'A teacher or library can help too'"}],"bins":[{"id":"grift","label":"Grift tell","valence":"neg"},{"id":"genuine","label":"Genuine help","valence":"pos"}],"key":{"a":"grift","b":"genuine","c":"grift","d":"genuine","e":"grift","f":"genuine"},"relearn":"Pressure, fake timers and 'only my paywall' are grift tells; free help isn't.","persona":"any","source":"grift vs help"},
  {"id":"rh-918","cat":"follow-the-money","type":"sort","hook":"Sort: does this earn him money, or actually grow you?","items":[{"id":"a","text":"You rage-share his clip to argue"},{"id":"b","text":"You join a free local football team"},{"id":"c","text":"You buy the 'alpha academy'"},{"id":"d","text":"You read a borrowed library book"},{"id":"e","text":"You click his affiliate supplement link"},{"id":"f","text":"You ask a teacher for study help"}],"bins":[{"id":"him","label":"He profits","valence":"uhoh"},{"id":"you","label":"You grow","valence":"pos"}],"key":{"a":"him","b":"you","c":"him","d":"you","e":"him","f":"you"},"relearn":"Rage-shares, course buys and affiliate clicks pay him; free teams, books and teachers grow you.","persona":"any","source":"follow the money"},
  {"id":"rh-919","cat":"follow-the-money","type":"sort","hook":"Sort: mostly-free growth, or a paid sales funnel?","items":[{"id":"a","text":"A free online workout you can follow"},{"id":"b","text":"A paid 'unlock your alpha' masterclass"},{"id":"c","text":"A free school counsellor chat"},{"id":"d","text":"A sub to 'secret high-value tactics'"},{"id":"e","text":"A free guide from a public library"},{"id":"f","text":"A 'VIP brotherhood' billed monthly"}],"bins":[{"id":"real","label":"Real growth","valence":"pos"},{"id":"funnel","label":"Sales funnel","valence":"neg"}],"key":{"a":"real","b":"funnel","c":"real","d":"funnel","e":"real","f":"funnel"},"relearn":"Real growth is mostly free; 'secret' paid tiers are a sales funnel.","persona":"any","source":"real vs funnel"},
  {"id":"rh-920","cat":"follow-the-money","type":"sort","hook":"Sort each line: real reason, or manufactured urgency?","items":[{"id":"a","text":"'Price doubles at midnight!' on a reset timer"},{"id":"b","text":"'Library shuts at 6, go before then'"},{"id":"c","text":"'Only 3 seats left' that never runs out"},{"id":"d","text":"'Match starts at 5, reach by 4:45'"},{"id":"e","text":"'Last chance ever' that reopens weekly"},{"id":"f","text":"'Form due Friday', a real date"}],"bins":[{"id":"fake","label":"Manufactured","valence":"neg"},{"id":"real","label":"Real reason","valence":"pos"}],"key":{"a":"fake","b":"real","c":"fake","d":"real","e":"fake","f":"real"},"relearn":"Reset timers and 'last chance' that reopens are fake; real dates stay fixed.","persona":"any","source":"fake urgency"},
  {"id":"rh-921","cat":"follow-the-money","type":"sort","hook":"Sort: who's the real customer in each setup?","items":[{"id":"a","text":"You watch his free clips for hours"},{"id":"b","text":"An advertiser pays for your watch-time"},{"id":"c","text":"You use the free public library"},{"id":"d","text":"A sponsor pays him to push a product"},{"id":"e","text":"You read a book borrowed free"},{"id":"f","text":"A brand buys your attention via him"}],"bins":[{"id":"product","label":"You're the product","valence":"uhoh"},{"id":"free","label":"Genuinely free","valence":"pos"}],"key":{"a":"product","b":"product","c":"free","d":"product","e":"free","f":"product"},"relearn":"When advertisers pay for your attention, you're the product being sold.","persona":"Veer","source":"you're the product"},
  {"id":"rh-922","cat":"follow-the-money","type":"sort","hook":"Sort: builds confidence for free, or sells it back to you?","items":[{"id":"a","text":"Practising a skill until it clicks"},{"id":"b","text":"Paying to 'unlock confidence secrets'"},{"id":"c","text":"Friends who back you up"},{"id":"d","text":"A subscription to 'feel like a man'"},{"id":"e","text":"Helping out and seeing it matter"},{"id":"f","text":"A paid 'mindset reset' bundle"}],"bins":[{"id":"built","label":"Built free","valence":"pos"},{"id":"sold","label":"Sold to you","valence":"neg"}],"key":{"a":"built","b":"sold","c":"built","d":"sold","e":"built","f":"sold"},"relearn":"Confidence is built through skills, friends and helping, not unlocked by a paid bundle.","persona":"any","source":"confidence built not bought"},
  {"id":"rh-923","cat":"follow-the-money","type":"sort","hook":"Sort each promise: a price tag, or genuinely free?","items":[{"id":"a","text":"'Secret to confidence', link in bio"},{"id":"b","text":"'Join the brotherhood', billed monthly"},{"id":"c","text":"A coach who says 'just turn up, free'"},{"id":"d","text":"'I'll fix your life', if you keep paying"},{"id":"e","text":"A free school club anyone can join"},{"id":"f","text":"A neighbour who coaches cricket free"}],"bins":[{"id":"priced","label":"Price tag","valence":"neg"},{"id":"free","label":"Genuinely free","valence":"pos"}],"key":{"a":"priced","b":"priced","c":"free","d":"priced","e":"free","f":"free"},"relearn":"Every big 'secret' promise has a price tag; real support is often free.","persona":"any","source":"price tag"},
  {"id":"rh-924","cat":"follow-the-money","type":"sort","hook":"Sort each move: it pays him, or it frees you?","items":[{"id":"a","text":"Subscribing to his paid 'inner circle'"},{"id":"b","text":"Closing the app and going for a walk"},{"id":"c","text":"Buying his branded supplements"},{"id":"d","text":"Texting a real friend instead"},{"id":"e","text":"Sharing his rage clip to 'own' someone"},{"id":"f","text":"Resetting your feed away from him"}],"bins":[{"id":"pays","label":"Pays him","valence":"uhoh"},{"id":"frees","label":"Frees you","valence":"pos"}],"key":{"a":"pays","b":"frees","c":"pays","d":"frees","e":"pays","f":"frees"},"relearn":"Subs, merch and rage-shares pay him; walking away and real friends don't.","persona":"any","source":"follow the money"},
  {"id":"rh-925","cat":"follow-the-money","type":"sort","hook":"Sort each tier name: made-up sales label, or a real, free thing?","items":[{"id":"a","text":"'Alpha-male certification'"},{"id":"b","text":"A public library card"},{"id":"c","text":"'High-value man platinum tier'"},{"id":"d","text":"A free school counselling slot"},{"id":"e","text":"'Sigma inner-circle access'"},{"id":"f","text":"A local sports club membership"}],"bins":[{"id":"label","label":"Made-up sales label","valence":"neg"},{"id":"realfree","label":"Real & free","valence":"pos"}],"key":{"a":"label","b":"realfree","c":"label","d":"realfree","e":"label","f":"realfree"},"relearn":"'Alpha/sigma tiers' are invented sales labels; libraries, clubs and counsellors are real and free.","persona":"any","source":"made-up tiers"},
  {"id":"rh-926","cat":"follow-the-money","type":"sort","hook":"Sort: a tell that 'free advice' funnels to a paywall, or not?","items":[{"id":"a","text":"Every clip ends 'link in bio'"},{"id":"b","text":"A clip that just answers the question"},{"id":"c","text":"'Full version only in the paid app'"},{"id":"d","text":"A tip with no upsell at all"},{"id":"e","text":"'Comment, then DM me to enrol'"},{"id":"f","text":"He points you to a free website"}],"bins":[{"id":"paywall","label":"Funnels to paywall","valence":"neg"},{"id":"clean","label":"No catch","valence":"pos"}],"key":{"a":"paywall","b":"clean","c":"paywall","d":"clean","e":"paywall","f":"clean"},"relearn":"'Link in bio', 'paid app only' and 'DM to enrol' all funnel to a paywall.","persona":"any","source":"paywall tells"},
  {"id":"rh-927","cat":"follow-the-money","type":"sort","hook":"Sort each step: free bait, or the paid catch?","items":[{"id":"a","text":"Free clip that makes you feel 'not enough'"},{"id":"b","text":"A paid 'starter academy'"},{"id":"c","text":"Free 'quiz' that flags you as 'beta'"},{"id":"d","text":"A monthly 'inner circle' upsell"},{"id":"e","text":"Free DM offering 'one-on-one help'"},{"id":"f","text":"A pricey 'mastermind' final tier"}],"bins":[{"id":"bait","label":"Free bait","valence":"uhoh"},{"id":"catch","label":"The paid catch","valence":"neg"}],"key":{"a":"bait","b":"catch","c":"bait","d":"catch","e":"bait","f":"catch"},"relearn":"Free clips, quizzes and DMs are bait; the paid tiers are the catch.","persona":"Veer","source":"funnel stages"},
  {"id":"rh-928","cat":"follow-the-money","type":"sort","hook":"Sort each claim about his income: honest, or hidden?","items":[{"id":"a","text":"'This video is sponsored', shown clearly"},{"id":"b","text":"Quietly paid to push, never disclosed"},{"id":"c","text":"'I earn from course sales', said openly"},{"id":"d","text":"'Members made lakhs' with zero proof"},{"id":"e","text":"A clear, listed course price"},{"id":"f","text":"A 'free secret' that's a paid tier"}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"hidden","label":"Hidden money","valence":"neg"}],"key":{"a":"honest","b":"hidden","c":"honest","d":"hidden","e":"honest","f":"hidden"},"relearn":"Disclosed pay and listed prices are honest; 'free secrets' hide the money.","persona":"any","source":"income honesty"},
  {"id":"rh-929","cat":"follow-the-money","type":"strike-rewrite","hook":"\"His paid academy is the only way I'll improve.\"","myth":{"un":"His paid academy is the only way I'll ever improve myself.","re":"Most real growth is free: skills, friends, a coach, a library. No academy needed.","why":"'Only my paywall works' is a sales line, not the truth about how people grow."},"relearn":"His paywall isn't the only way; most real growth costs nothing.","persona":"Veer","source":"only-paywall myth"},
  {"id":"rh-930","cat":"follow-the-money","type":"strike-rewrite","hook":"\"If members are making lakhs, the course must work.\"","myth":{"un":"His 'members made lakhs' screenshots prove the course really works.","re":"Unverifiable income screenshots are bait; you can't check them, and most are cherry-picked or fake.","why":"Showing a few unprovable wins is how every grift makes the next sale."},"relearn":"Unverifiable 'made lakhs' screenshots are bait, not proof a course works.","persona":"any","source":"fake testimonials"},
  {"id":"rh-931","cat":"follow-the-money","type":"strike-rewrite","hook":"\"The countdown timer means I really must buy now.\"","myth":{"un":"The 'price doubles at midnight' timer means I have to buy right now.","re":"Those timers reset for every new visitor: it's manufactured urgency, not a real deadline.","why":"Fake scarcity is designed to rush you past your own second thoughts."},"relearn":"Sales countdown timers reset for everyone: it's fake urgency, not a real deadline.","persona":"any","source":"fake scarcity"},
  {"id":"rh-932","cat":"follow-the-money","type":"strike-rewrite","hook":"\"He's giving all this away for free, so he must care.\"","myth":{"un":"He gives so much advice for free, so he must genuinely care about me.","re":"The free stuff is bait that funnels to a paywall: caring help doesn't end every time at 'now pay'.","why":"'Free' that always points to a sale is marketing, not care."},"relearn":"'Free' advice that always funnels to a paywall is marketing, not care.","persona":"Veer","source":"free-bait"},
  {"id":"rh-933","cat":"follow-the-money","type":"strike-rewrite","hook":"\"Buying in is how I finally join the brotherhood.\"","myth":{"un":"Paying for the VIP tier is how I finally become part of the brotherhood.","re":"You can't buy belonging: a paid tier keeps you paying, real friends just turn up.","why":"Charging for 'brotherhood' is the funnel, not the friendship."},"relearn":"You can't buy belonging; a paid 'brotherhood' keeps you paying, not connected.","persona":"any","source":"belonging isn't a sub"},
  {"id":"rh-934","cat":"follow-the-money","type":"strike-rewrite","hook":"\"He must be right that I'm not enough. Why else would he say it so much?\"","myth":{"un":"He keeps saying I'm not enough, so it must be true about me.","re":"He repeats 'you're not enough' because that feeling is what makes you buy the fix he sells.","why":"Manufactured insecurity is the first step of the sale, not a fact about you."},"relearn":"'You're not enough' is manufactured to sell you the fix, not a fact about you.","persona":"Veer","source":"manufactured insecurity"},
  {"id":"rh-935","cat":"follow-the-money","type":"strike-rewrite","hook":"\"His rage clips are just him telling hard truths.\"","myth":{"un":"His angry, shocking clips are just him brave enough to tell hard truths.","re":"The outrage is manufactured rage-bait: anger drives the views and arguments that pay him.","why":"If anger is the product, 'hard truth' is just the packaging."},"relearn":"Manufactured outrage is rage-bait; the anger drives the views that pay him.","persona":"any","source":"rage-bait economics"},
  {"id":"rh-936","cat":"follow-the-money","type":"strike-rewrite","hook":"\"Even when I argue with him, I'm fighting back.\"","myth":{"un":"When I argue in his comments, at least I'm pushing back against him.","re":"Arguing boosts his watch-time and reach: even hate-watching pays him; muting costs him more.","why":"Engagement is his income, so outrage-replies feed the very thing you're against."},"relearn":"Arguing and hate-watching still pay him; muting and moving on costs him most.","persona":"any","source":"engagement feeds him"},
  {"id":"rh-937","cat":"follow-the-money","type":"match","hook":"Match each grift move to what it really is.","pairs":[{"left":"'You're not enough'","right":"The setup for a sale"},{"left":"'Link in bio'","right":"The paywall door"},{"left":"A rage-bait take","right":"Engagement bought for profit"},{"left":"'Spots closing tonight'","right":"Manufactured urgency"},{"left":"'Members made lakhs'","right":"Unverifiable bait"}],"relearn":"Each move (put-down, link, rage, timer, screenshot) exists to earn money.","persona":"any","source":"grift decoder"},
  {"id":"rh-938","cat":"follow-the-money","type":"match","hook":"Match each big promise to the catch hiding behind it.","pairs":[{"left":"'Secret to confidence'","right":"Locked behind a paywall"},{"left":"'Join the brotherhood'","right":"A monthly subscription"},{"left":"'I'll fix your life'","right":"Only if you keep paying"},{"left":"'Free masterclass'","right":"An hour-long sales pitch"},{"left":"'One-on-one with me'","right":"A high-priced upsell"}],"relearn":"Every big promise here comes with a price tag clipped to the back.","persona":"any","source":"promise vs catch"},
  {"id":"rh-939","cat":"follow-the-money","type":"match","hook":"Match each grift tactic to the genuine version of the same thing.","pairs":[{"left":"Paid 'alpha academy'","right":"A free library and a coach"},{"left":"'VIP brotherhood' sub","right":"Friends who just turn up"},{"left":"'Unlock your confidence' fee","right":"Skills you build by practising"},{"left":"Affiliate supplement push","right":"Free workouts and good sleep"},{"left":"'DM me to enrol'","right":"Asking a teacher for help"}],"relearn":"For every paid grift version there's a free, genuine one that actually grows you.","persona":"any","source":"grift vs genuine"},
  {"id":"rh-940","cat":"follow-the-money","type":"match","hook":"Match each thing he says to what it tells you about his money.","pairs":[{"left":"'This clip is sponsored'","right":"Open about being paid"},{"left":"Quiet, undisclosed paid push","right":"Hiding who pays him"},{"left":"A clear, listed course price","right":"You see the real cost"},{"left":"'Free secret' that's a paid tier","right":"The 'free' part is a trick"},{"left":"'Made lakhs', no proof","right":"Bait you can't verify"}],"relearn":"Disclosed pay and listed prices are honest; 'free secrets' hide it.","persona":"any","source":"income honesty"},
  {"id":"rh-941","cat":"follow-the-money","type":"match","hook":"Match each funnel stage to its job in the sale.","pairs":[{"left":"Free relatable clip","right":"The hook that pulls you in"},{"left":"'Alpha or beta?' quiz","right":"Makes you feel you need fixing"},{"left":"Cheap 'starter academy'","right":"The first paid step"},{"left":"Monthly 'inner circle'","right":"Keeps the money flowing"},{"left":"₹15000 'mastermind'","right":"The big-ticket upsell"}],"relearn":"Each stage (hook, quiz, starter, sub, mastermind) moves you deeper into paying.","persona":"Veer","source":"funnel stages"},
  {"id":"rh-942","cat":"follow-the-money","type":"match","hook":"Match each thing you might do to who actually gains from it.","pairs":[{"left":"Buy his branded supplements","right":"He gains your money"},{"left":"Join a free local club","right":"You gain real friends"},{"left":"Rage-share his clip","right":"He gains reach"},{"left":"Borrow a book from a library","right":"You gain a free skill"},{"left":"Reset your feed","right":"You gain your time back"}],"relearn":"Buying and rage-sharing feed him; clubs, libraries and feed resets grow you.","persona":"any","source":"who gains"},
  {"id":"rh-943","cat":"follow-the-money","type":"match","hook":"Match each pressure line to the trick it's using on you.","pairs":[{"left":"'Only 3 seats left'","right":"Fake scarcity"},{"left":"'Stay a loser or buy now'","right":"Shame as a lever"},{"left":"'Price doubles at midnight'","right":"A reset countdown trick"},{"left":"'Everyone's already in'","right":"Fake popularity"},{"left":"'DM me, it's just us'","right":"A funnel dressed as a favour"}],"relearn":"Scarcity, shame, fake timers and false popularity are all levers to rush the sale.","persona":"any","source":"pressure decoder"},
  {"id":"rh-944","cat":"follow-the-money","type":"match","hook":"Match each worry under the grift to where real help is.","pairs":[{"left":"'I feel like I'm not enough'","right":"A trusted adult or Tele-MANAS 14416"},{"left":"'I want somewhere to belong'","right":"A free club, team or friends"},{"left":"'I want to get fitter'","right":"Free workouts and good sleep"},{"left":"'I'm lonely a lot'","right":"Talk to someone you trust"},{"left":"'I want to learn a skill'","right":"A library or teacher, free"}],"relearn":"The needs the grift exploits are real; free help meets them better.","persona":"Counsellor","source":"need to real help"},
  {"id":"rh-945","cat":"follow-the-money","type":"branch","hook":"A clip leaves you sure you must buy his course to 'finally be enough'.","options":[{"text":"See the 'not enough' feeling was sold to me, and close it","consequence":"You keep your money and self-worth.","outcome":"free","best":true},{"text":"Buy it before the fake timer runs out","consequence":"He profits from a feeling he manufactured."}],"debrief":"That 'must buy it' urge was made to sell; you're already enough.","relearn":"The 'must buy it' feeling was manufactured; you don't owe the sale.","persona":"Veer","source":"manufactured insecurity"},
  {"id":"rh-946","cat":"follow-the-money","type":"branch","hook":"A 'mentor' DMs: 'Comment your number, I'll change your life.'","options":[{"text":"See the sales funnel and don't share my details","consequence":"You dodge the pitch and keep your data.","outcome":"safe","best":true},{"text":"Share my number, he sounds like he cares","consequence":"The 'personal' DM just sends everyone a payment link."}],"debrief":"A 'personal' DM that only sends a payment link is a funnel, not a favour.","relearn":"A 'personal' DM that ends in a payment link is a sales funnel.","persona":"any","source":"DM funnel"},
  {"id":"rh-947","cat":"follow-the-money","type":"branch","hook":"Your friend's about to pay big for a 'become an alpha' academy.","options":[{"text":"Show him it's free elsewhere, suggest a club","consequence":"He keeps his money and tries what builds him.","outcome":"backed","best":true},{"text":"Mock him for nearly falling for it","consequence":"He gets defensive and buys it to spite you."}],"debrief":"Showing a friend the free path beats mocking; mockery pushes him in.","relearn":"Show a friend the free path; mocking pushes him toward the sale.","persona":"any","source":"back a friend"},
  {"id":"rh-948","cat":"follow-the-money","type":"branch","hook":"A 'free masterclass' turns out to be a one-hour sales pitch.","options":[{"text":"Clock it as an ad, take a free tip, leave","consequence":"You lose nothing and learn the format.","outcome":"savvy","best":true},{"text":"Buy the upsell so the hour wasn't 'wasted'","consequence":"Sunk-cost is exactly what the format triggers."}],"debrief":"A 'free masterclass' that's mostly a pitch is an ad; take a tip and walk.","relearn":"A 'free masterclass' that's mostly a pitch is an ad; take a tip and leave.","persona":"any","source":"masterclass funnel"},
  {"id":"rh-949","cat":"follow-the-money","type":"branch","hook":"He posts 'Real men pay; broke betas comment. Which are you?'","options":[{"text":"See the shame-then-sell move and scroll on","consequence":"You keep your money and calm; the bait gets no grip.","outcome":"free","best":true},{"text":"Pay to prove you're not a 'broke beta'","consequence":"Shaming you into buying is the whole tactic."}],"debrief":"Shaming you, then selling the 'cure', is manipulation; 'alpha/beta' isn't real.","relearn":"Shame-then-sell is the tactic; the 'alpha/beta' ranking is made up.","persona":"Veer","source":"shame-then-sell"},
  {"id":"rh-950","cat":"follow-the-money","type":"branch","hook":"You notice a creator earns more every time his takes get nastier.","options":[{"text":"Mute him and reset my feed to stuff that builds me","consequence":"His reach drops; your feed stops feeding it.","outcome":"reset","best":true},{"text":"Keep hate-watching to see what's next","consequence":"Hate-watching is still watch-time; you're paying him."}],"debrief":"His income is your attention; muting and resetting your feed is what costs him.","relearn":"Outrage is his income; muting and resetting your feed costs him most.","persona":"any","source":"starve the funnel"},
  {"id":"rh-951","cat":"follow-the-money","type":"branch","hook":"A 'side hustle guru' wants a fee to 'unlock the method that made me rich'.","options":[{"text":"Notice his real income is selling the method, and pass","consequence":"You keep your money; a real skill serves you better.","outcome":"smart","best":true},{"text":"Pay up, he's rich so it must work","consequence":"The flex is often rented or just buyers' fees."}],"debrief":"If the 'method' that made him rich is selling it, you're the income.","relearn":"If his real income is selling the 'method', you're the customer.","persona":"any","source":"guru income"},
  {"id":"rh-952","cat":"follow-the-money","type":"reflect","hook":"Lensy: once you see the salesman behind the 'mentor', does the message lose its grip?","prompt":"Sit with that: what shifts for you?","options":["Yeah, it loosens","He's just selling","I'd scroll past now"],"affirm":"Seeing the incentive is what frees you from the message. Fair?","relearn":"Seeing the salesman behind the message takes away its grip.","persona":"any","source":"media literacy"},
  {"id":"rh-953","cat":"follow-the-money","type":"reflect","hook":"Lensy: when something's 'free' but always ends at a paywall, what question helps you?","prompt":"What would you ask yourself?","options":["'Who's paying, and how?'","'What's the catch?'","'Where does this funnel go?'"],"affirm":"Asking who profits is a superpower: it works on every pitch you'll ever see.","relearn":"Asking 'who profits, and how?' cuts through any 'free' pitch.","persona":"any","source":"follow-the-money habit"},
  {"id":"rh-954","cat":"follow-the-money","type":"reflect","hook":"Lensy: a clip leaves you feeling 'not enough'. What's a kinder, truer read?","prompt":"Which lands for you?","options":["That feeling was sold to me","I'm already enough, and growing","It's the setup for a sale"],"affirm":"The 'not enough' feeling is the product: you don't have to buy what made it.","relearn":"The 'not enough' feeling is manufactured to sell you the fix.","persona":"Veer","source":"manufactured insecurity"},
  {"id":"rh-955","cat":"follow-the-money","type":"reflect","hook":"Lensy: what could you do with the time and money a grift wanted from you?","prompt":"What comes to mind?","options":["Train at a free club","Hang with real friends","Learn a skill from a library"],"affirm":"Every one of those builds you for free, no subscription required.","relearn":"The time and money a grift wants can build you for free instead.","persona":"any","source":"free alternatives"},
  {"id":"rh-956","cat":"follow-the-money","type":"reflect","hook":"Lensy: a creator brags 'even haters make me money'. How does that change your move?","prompt":"What feels right?","options":["I'd just mute him","Stop arguing in comments","Reset my feed away"],"affirm":"You get to choose where your attention goes, and that's the thing he's selling.","relearn":"Your attention is the product; choosing where it goes is real power.","persona":"any","source":"attention is the product"},
  {"id":"rh-957","cat":"follow-the-money","type":"reflect","hook":"Lensy: a friend admits he spent money chasing a 'become a man' course. What matters most?","prompt":"What would you lead with?","options":["No judgement, it's a clever trap","The need underneath was real","Let's find a free way together"],"affirm":"The funnels are built to convince: meeting him with care beats any 'told you so'.","relearn":"These funnels are engineered to convince; care beats judgement.","persona":"Counsellor","source":"the need underneath"},
  {"id":"rh-958","cat":"follow-the-money","type":"reflect","hook":"Lensy: what's a tell, just for you, that a 'mentor' is really a salesman?","prompt":"Pick what rings true.","options":["Everything ends in 'buy'","He needs me to feel lacking","Free advice, then a paywall"],"affirm":"Trust that radar: naming the sell is what loosens its hold.","relearn":"Naming the sell behind a 'mentor' loosens its hold on you.","persona":"any","source":"your own radar"},
  {"id":"rh-959","cat":"follow-the-money","type":"role-play","hook":"A friend says 'I'm buying the alpha academy, it'll finally fix me.' Say the line that backs him.","setup":"He's about to pay ₹9999. You want to help without shaming him.","yourLine":[{"text":"'That stuff's mostly free, man, wanna hit the gym and figure it out together instead?'","best":true},{"text":"'Lol, you'd actually fall for that?'"},{"text":"'Whatever, it's your money.'"}],"relearn":"Offer the free path and your company; mockery just pushes a friend toward the sale.","persona":"any","source":"back a friend"},
  {"id":"rh-960","cat":"follow-the-money","type":"role-play","hook":"A 'mentor' DMs: 'Drop your number, I'll personally mentor you.' Say the line that protects you.","setup":"It feels flattering, but the pattern looks like a funnel.","yourLine":[{"text":"'No thanks, if real help's free elsewhere, I don't need to pay for a DM.'","best":true},{"text":"'Okay, here's my number, I guess.'"},{"text":"'Maybe later, I'll think about it...'"}],"relearn":"You can decline a 'personal' DM funnel cleanly; real help doesn't need your number.","persona":"any","source":"decline the funnel"},
  {"id":"rh-961","cat":"follow-the-money","type":"role-play","hook":"Your group chat is hyping a 'last 3 spots!' course. Say the line that names the trick.","setup":"Everyone's panicking about the countdown. You can slow it down.","yourLine":[{"text":"'Those timers reset for everyone. It's fake urgency, not a real deadline.'","best":true},{"text":"'Quick, we'll miss it, just buy!'"},{"text":"'I dunno, maybe it's legit...'"}],"relearn":"Naming fake urgency out loud frees the whole group from the rush.","persona":"any","source":"name the urgency"},
  {"id":"rh-962","cat":"follow-the-money","type":"role-play","hook":"A classmate calls a creator's rage clips 'just hard truths'. Say the line that follows the money.","setup":"You've noticed the angrier he gets, the more he sells.","yourLine":[{"text":"'Notice he earns more the angrier he gets? That's rage-bait, not truth.'","best":true},{"text":"'Yeah, he's pretty brave I guess.'"},{"text":"'Eh, I don't really care.'"}],"relearn":"Pointing out that outrage pays him reframes 'hard truths' as rage-bait.","persona":"any","source":"follow the money aloud"},
  {"id":"rh-963","cat":"follow-the-money","type":"role-play","hook":"He posts 'broke betas in the comments, real men in my paid group'. Say the line that refuses the bait.","setup":"It's designed to shame you into paying. You don't have to bite.","yourLine":[{"text":"'Shaming people into buying isn't mentoring. It's just the sales pitch.'","best":true},{"text":"'Fine, I'll buy it to prove I'm not broke.'"},{"text":"'Bro you're the broke one, idiot.'"}],"relearn":"Naming shame-then-sell refuses the bait without buying or insulting back.","persona":"Veer","source":"refuse the shame-sell"},
  {"id":"rh-964","cat":"follow-the-money","type":"role-play","hook":"A guru flexes a supercar to sell a course. Say the line that sees the borrowed proof.","setup":"The 'success' is the pitch. You can read it for what it is.","yourLine":[{"text":"'Half those flexes are rented. The only money's the fees we'd pay him.'","best":true},{"text":"'Wow, if I buy in maybe I'll get a car too.'"},{"text":"'He must be legit, look at that car.'"}],"relearn":"A rented flex is borrowed proof; the real income is the fees buyers pay.","persona":"any","source":"borrowed flex"},
  {"id":"rh-965","cat":"follow-the-money","type":"role-play","hook":"A friend keeps arguing with a creator in the comments. Say the line that starves the grift.","setup":"He thinks he's 'owning' the guy, but it's all engagement.","yourLine":[{"text":"'Every reply feeds his reach, muting him costs him way more than arguing.'","best":true},{"text":"'Yeah, destroy him in the replies!'"},{"text":"'I mean, keep going, it's funny.'"}],"relearn":"Muting starves the grift; arguing in the comments only feeds his reach.","persona":"any","source":"starve the grift"},
  {"id":"rh-966","cat":"follow-the-money","type":"role-play","hook":"A friend admits he spent allowance on a 'man up' course and feels stupid. Say the line that meets him.","setup":"He's embarrassed. The funnel was built to fool people.","yourLine":[{"text":"'No shame. Those funnels are built to fool everyone. Let's find a free way forward.'","best":true},{"text":"'Yeah, that was pretty dumb of you.'"},{"text":"'Should've asked me first, obviously.'"}],"relearn":"Drop the shame and offer a free way forward: the trap was engineered, not his fault.","persona":"Counsellor","source":"meet the need"},
  {"id":"rh-990","type":"branch","hook":"Your best friend keeps sending clips that rank girls 1 to 10. What do you do?","options":[{"text":"Say it makes you uncomfortable, and ask what's going on with him","consequence":"He hears you and stays open.","outcome":"call-in","best":true},{"text":"Forward the clips to mock him in the group chat","consequence":"He feels ganged up on and digs in."}],"debrief":"Naming how it lands, plus a real question, keeps the door open.","relearn":"Say how it lands and ask what's up, instead of mocking him.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-991","type":"branch","hook":"A boy in class won't stop quoting a 'mentor' who says girls are objects.","options":[{"text":"Calmly say that's not true and you won't laugh along","consequence":"You take away the reaction he wanted.","outcome":"upstander","best":true},{"text":"Scream at him in front of everyone","consequence":"A scene gives him the drama he wanted."}],"debrief":"Calm naming denies provocation its payoff and backs the girls there.","relearn":"Name it calmly and refuse to laugh, instead of a big reaction.","persona":"Riya","source":"upstander","cat":"have-each-others-backs"},
  {"id":"rh-992","type":"branch","hook":"Your cousin says he 'feels alive' only watching this rage stuff late at night.","options":[{"text":"Say you get the lonely feeling, and ask to hang out more","consequence":"He gets a connection that competes with the feed.","outcome":"belonging","best":true},{"text":"Tell him he's pathetic and log off","consequence":"Shame sends him back to the only place that 'gets' him."}],"debrief":"Meeting the loneliness underneath is what the feed was faking.","relearn":"Meet the loneliness with real connection, instead of shaming him.","persona":"any","source":"belonging / need-underneath","cat":"have-each-others-backs"},
  {"id":"rh-993","type":"branch","hook":"A friend's posts have gone from gym tips to 'women ruined everything' in a month.","options":[{"text":"Ask him in person how he's really doing lately","consequence":"A caring question reaches the person behind the posts.","outcome":"call-in","best":true},{"text":"Comment 'cringe' under every post","consequence":"Public cringe pushes him further in; ask him in private."}],"debrief":"Curiosity in private reaches further than a public put-down.","relearn":"Ask how he's really doing in person, instead of dunking in public.","persona":"Veer","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-994","type":"branch","hook":"Someone is posting nasty, sexist replies under a girl's photos in the class chat.","options":[{"text":"Message her: that's on him, want help reporting it?","consequence":"She knows she's backed, not alone.","outcome":"support","best":true},{"text":"Stay quiet so you don't get dragged in","consequence":"Silence leaves her alone with it."}],"debrief":"Backing the person targeted shifts the weight off them.","relearn":"Message the targeted person and offer to help report it.","persona":"any","source":"support","cat":"have-each-others-backs"},
  {"id":"rh-995","type":"branch","hook":"Your friend's 'jokes' about girls are getting darker; he calls you 'soft' if you object.","options":[{"text":"Hold your line warmly: not funny to me, still your mate","consequence":"You stay connected without co-signing it.","outcome":"call-in","best":true},{"text":"Laugh along so he doesn't call you soft","consequence":"Laughing rewards it and normalises the next."}],"debrief":"You can refuse the joke and keep the friendship at once.","relearn":"Hold your line warmly, instead of laughing to fit in.","persona":"Veer","source":"call-in / refuse","cat":"have-each-others-backs"},
  {"id":"rh-996","type":"branch","hook":"A girl you know is starting to believe the 'you're worth less' stuff aimed at her.","options":[{"text":"Remind her it's manipulation; her worth isn't theirs to set","consequence":"She has a truer mirror than the contempt.","outcome":"resilient","best":true},{"text":"Tell her to just get a thicker skin","consequence":"'Thicker skin' leaves her alone with it."}],"debrief":"Naming it as manipulation helps her refuse to absorb it.","relearn":"Remind her it's manipulation and her worth is her own.","persona":"Riya","source":"refuse / support","cat":"have-each-others-backs"},
  {"id":"rh-997","type":"branch","hook":"Your friend's views have turned scary and he's hinted at hurting someone.","options":[{"text":"Keep being his friend AND tell a trusted adult today","consequence":"He gets help bigger than either of you.","outcome":"safeguard","best":true},{"text":"Promise to keep it secret no matter what","consequence":"Some things are too big to carry alone."}],"debrief":"You can stay his friend and still bring an adult in.","relearn":"Stay his friend and tell a trusted adult, not promise silence.","persona":"any","source":"safeguard","cat":"have-each-others-backs"},
  {"id":"rh-998","type":"branch","hook":"You said something cruel to a slipping friend last term and he's gone cold.","options":[{"text":"Reach out and own it: I was harsh, I miss you, can we talk?","consequence":"Owning it reopens the door your words closed.","outcome":"repair","best":true},{"text":"Decide he's too far gone to bother with","consequence":"Writing him off seals the door; it's rarely too late to reconnect."}],"debrief":"Owning a harsh moment can undo the push it caused.","relearn":"Reach out and own the harsh moment, instead of writing him off.","persona":"any","source":"repair","cat":"have-each-others-backs"},
  {"id":"rh-999","type":"branch","hook":"In the boys' group chat, one lad starts a 'rate the girls' thread.","options":[{"text":"Say not doing that, they're our classmates, change the subject","consequence":"You set the tone; others stop too.","outcome":"upstander","best":true},{"text":"Add your own rating so you don't seem boring","consequence":"Joining in spreads it."}],"debrief":"One calm refusal often gives everyone permission to stop.","relearn":"Refuse and change the subject, instead of joining to fit in.","persona":"any","source":"upstander / refuse","cat":"have-each-others-backs"},
  {"id":"rh-1000","type":"branch","hook":"A friend admits he watches this stuff because he feels invisible at home.","options":[{"text":"Tell him that ache is real and you've got him, no shame","consequence":"He feels seen by a person, not a feed.","outcome":"belonging","best":true},{"text":"Tell him to man up and get over it","consequence":"'Man up' only deepens the ache."}],"debrief":"Normalising the need and dropping the shame meets what he missed.","relearn":"Tell him the ache is real and you've got him, not man up.","persona":"Counsellor","source":"need-underneath / belonging","cat":"have-each-others-backs"},
  {"id":"rh-1001","type":"branch","hook":"You're a girl and a boy keeps DMing contempt-bait to get a rise out of you.","options":[{"text":"Don't feed it: screenshot, block, tell an adult if it continues","consequence":"You deny the reaction and keep a record.","outcome":"resilient","best":true},{"text":"Fire back insults every time","consequence":"Trading insults feeds the bait."}],"debrief":"Refusing the reaction, plus a record, takes his power away.","relearn":"Screenshot, block, and tell an adult, not feed the bait.","persona":"Riya","source":"refuse / report","cat":"have-each-others-backs"},
  {"id":"rh-1002","type":"branch","hook":"Your younger brother starts repeating 'alpha' lines he heard online.","options":[{"text":"Stay curious: where'd you hear that? Who made it?","consequence":"He learns to question the source.","outcome":"call-in","best":true},{"text":"Confiscate his phone and end the conversation","consequence":"Cutting him off teaches nothing."}],"debrief":"Curiosity about the source teaches the skill; a ban doesn't.","relearn":"Stay curious about the source, not just confiscate the phone.","persona":"any","source":"call-in / media-literacy","cat":"have-each-others-backs"},
  {"id":"rh-1003","type":"branch","hook":"A friend says he can't talk to you now because his online 'brotherhood' disapproves.","options":[{"text":"Tell him the door's always open, no pressure, whenever","consequence":"He has a way back when they let him down.","outcome":"call-in","best":true},{"text":"Tell him fine, lose my number then","consequence":"Slamming the door leaves only the funnel."}],"debrief":"An open door beats an ultimatum when the crowd turns on him.","relearn":"Leave the door open with no pressure, not cut him off.","persona":"Veer","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1004","type":"branch","hook":"Two friends start fighting because one defended the misogynist stuff.","options":[{"text":"Cool it down, then talk to each one calmly, one at a time","consequence":"Lower heat lets both actually hear each other.","outcome":"call-in","best":true},{"text":"Pick a side and pile on with the group","consequence":"Piling on hardens both; cool the heat and talk one-to-one."}],"debrief":"Heat makes people dig in; calm one-to-one talk reaches them.","relearn":"Cool it and talk one-to-one, instead of piling on.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1005","type":"branch","hook":"A classmate is sharing a humiliating edited photo of a girl from your year.","options":[{"text":"Refuse to share, tell him to delete it, and back her up","consequence":"You stop the spread and she isn't left to fight it alone.","outcome":"upstander","best":true},{"text":"Share it once 'just to see'","consequence":"Every share widens the harm; refuse and help it stop."}],"debrief":"Not sharing, plus backing her, shrinks the harm fast.","relearn":"Refuse to share and back her up, instead of passing it on.","persona":"any","source":"upstander / support","cat":"have-each-others-backs"},
  {"id":"rh-1006","type":"branch","hook":"Your friend keeps saying girls owe him attention because he's 'a nice guy'.","options":[{"text":"Gently push back: no one owes you that, a no is okay","consequence":"He hears it from someone on his side.","outcome":"call-in","best":true},{"text":"Agree to keep the peace","consequence":"Agreeing lets the idea harden."}],"debrief":"A kind, honest push-back from a friend lands deeper.","relearn":"Push back kindly that nobody owes attention, not just agree.","persona":"Veer","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1007","type":"branch","hook":"A girl in your group says she's thinking of quitting the class chat over the abuse.","options":[{"text":"Tell her you'll call it out so she doesn't have to leave","consequence":"She's not the one forced out.","outcome":"support","best":true},{"text":"Tell her leaving is easiest for everyone","consequence":"That pushes the targeted person out."}],"debrief":"The targeted person shouldn't be the one who has to disappear.","relearn":"Offer to call it out so she can stay, not tell her to leave.","persona":"Riya","source":"support / upstander","cat":"have-each-others-backs"},
  {"id":"rh-1008","type":"branch","hook":"Your friend insists the 'blame women' content is just facts he can share.","options":[{"text":"Ask to check one claim together against a real source","consequence":"He sees the trick without being told off.","outcome":"call-in","best":true},{"text":"Just tell him he's brainwashed","consequence":"'Brainwashed' makes him defensive."}],"debrief":"Investigating a claim together teaches more than an accusation.","relearn":"Check a claim together, instead of calling him brainwashed.","persona":"any","source":"call-in / media-literacy","cat":"have-each-others-backs"},
  {"id":"rh-1009","type":"branch","hook":"You notice a quiet new kid being pulled into an older boy's 'mentor' group.","options":[{"text":"Invite him into your real group and check in on him","consequence":"He gets belonging that isn't a pipeline.","outcome":"belonging","best":true},{"text":"Assume someone else will look out for him","consequence":"Then the pipeline stays his only option."}],"debrief":"Real, no-strings belonging competes with the recruiting kind.","relearn":"Invite him in and check on him, not assume others will.","persona":"any","source":"belonging","cat":"have-each-others-backs"},
  {"id":"rh-1010","type":"branch","hook":"A friend texts at midnight that he feels worthless and 'no one would notice'.","options":[{"text":"Stay with him and help him reach Tele-MANAS 14416 or a trusted adult","consequence":"He's not alone, and real help is one step away.","outcome":"help","best":true},{"text":"Reply 'you'll be fine' and sleep","consequence":"Brushing it off leaves him alone with it."}],"debrief":"Take it seriously, stay, and route to real help.","relearn":"Stay and help him reach Tele-MANAS 14416 or a trusted adult.","persona":"Counsellor","source":"need-underneath / help","cat":"have-each-others-backs"},
  {"id":"rh-1011","type":"branch","hook":"Your group is about to dogpile a boy online for a sexist comment.","options":[{"text":"Suggest one of you DM him privately instead of dogpiling","consequence":"A private word can reach him where a pile-on never will.","outcome":"call-in","best":true},{"text":"Lead the dogpile to make an example of him","consequence":"A pile-on hardens him and feeds the drama; try a private word."}],"debrief":"A private call-in reaches the person; a public pile-on just performs.","relearn":"DM him privately, instead of leading a dogpile.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1012","type":"branch","hook":"A targeted girl asks for help reporting the harassment but you're not sure how.","options":[{"text":"Save the evidence and report at cybercrime.gov.in / 1930 together","consequence":"She isn't doing the scary part alone.","outcome":"report","best":true},{"text":"Tell her you don't know, so she's on her own","consequence":"Leaving her to it adds to the burden."}],"debrief":"Saving evidence and reporting together backs her with action.","relearn":"Help her save evidence and report at cybercrime.gov.in / 1930.","persona":"any","source":"support / report","cat":"have-each-others-backs"},
  {"id":"rh-1013","type":"role-play","hook":"You want to check in on a mate who's gone quiet and angry online.","setup":"Open with care, not a lecture. Say:","yourLine":[{"text":"\"Haven't seen you in ages, mate. How are things really going?\"","best":true},{"text":"\"You've become unbearable online, you know that?\""}],"relearn":"Open with care and a real question, not a lecture.","persona":"any","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1014","type":"role-play","hook":"A friend repeats that girls are 'the reason men struggle'. Respond without a fight.","setup":"Stay curious about him. Say:","yourLine":[{"text":"\"That sounds heavy. What's actually going on for you right now?\"","best":true},{"text":"\"You're an idiot for believing that.\""}],"relearn":"A curious question about him reaches further than an insult.","persona":"Veer","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1015","type":"role-play","hook":"You're a girl and a boy in class makes a sexist 'joke' to get a laugh.","setup":"Name it, calm and clear. Say:","yourLine":[{"text":"\"That's not a joke to me. Not okay.\"","best":true},{"text":"\"Haha, whatever, you're so funny.\""}],"relearn":"Name it calmly instead of laughing it off.","persona":"Riya","source":"upstander voice","cat":"have-each-others-backs"},
  {"id":"rh-1016","type":"role-play","hook":"A friend admits the content is the only place he doesn't feel alone, and he's ashamed.","setup":"Take the shame off him. Say:","yourLine":[{"text":"\"That makes sense, it's built to feel like that. No shame. I'm here.\"","best":true},{"text":"\"Wow, that's so pathetic of you.\""}],"relearn":"Normalise the need and drop the shame, then offer real connection.","persona":"any","source":"no-shame voice","cat":"have-each-others-backs"},
  {"id":"rh-1017","type":"role-play","hook":"Your friend is being piled on by your group for a dumb comment.","setup":"Be the one who reaches out. Say:","yourLine":[{"text":"\"Ignore the noise. Talk to me. What's going on with you?\"","best":true},{"text":"\"Yeah, you deserve all this, honestly.\""}],"relearn":"Reach out to the person behind the pile-on, don't join it.","persona":"any","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1018","type":"role-play","hook":"A girl friend is shaken after misogynist abuse landed in her inbox.","setup":"Have her back, plainly. Say:","yourLine":[{"text":"\"That's on them, not you. You don't have to take it, let's report it.\"","best":true},{"text":"\"You're probably overreacting, just ignore it.\""}],"relearn":"Tell her it's on them and offer to help report it.","persona":"Riya","source":"support voice","cat":"have-each-others-backs"},
  {"id":"rh-1019","type":"role-play","hook":"Your brother repeats that 'real men don't need anyone'.","setup":"Push back warmly. Say:","yourLine":[{"text":"\"Everyone needs people. I need you around. That's not weakness.\"","best":true},{"text":"\"Fine, do it all alone then, see if I care.\""}],"relearn":"Push back warmly that needing people is human, not weakness.","persona":"Veer","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1020","type":"role-play","hook":"A friend says he's done with you because his online group told him to be.","setup":"Keep the door open. Say:","yourLine":[{"text":"\"No pressure. But I'm here whenever you want, always.\"","best":true},{"text":"\"Cool, don't bother coming back then.\""}],"relearn":"Keep the door open with no pressure, not an ultimatum.","persona":"any","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1021","type":"role-play","hook":"You want to invite a lonely-seeming classmate into your group.","setup":"Offer real belonging. Say:","yourLine":[{"text":"\"We're getting food after school, come with us?\"","best":true},{"text":"\"You always look so miserable, what's wrong with you?\""}],"relearn":"Offer simple, real belonging instead of pointing out his mood.","persona":"any","source":"belonging voice","cat":"have-each-others-backs"},
  {"id":"rh-1022","type":"role-play","hook":"A friend insists a no from a girl means she 'owes him an explanation'.","setup":"Say the true thing, kindly. Say:","yourLine":[{"text":"\"A no is a full answer, mate. Nobody owes you more than that.\"","best":true},{"text":"\"Yeah, she totally led you on, that's harsh.\""}],"relearn":"A no is a complete answer; no one owes more.","persona":"Veer","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1023","type":"role-play","hook":"You overhear a younger boy quoting 'high-value / low-value' rankings.","setup":"Plant a doubt, gently. Say:","yourLine":[{"text":"\"Who decided that ranking, though? Sounds like someone selling something.\"","best":true},{"text":"\"Yeah, you're definitely low-value, sorry.\""}],"relearn":"Question who profits from the ranking, don't rank him back.","persona":"any","source":"media-literacy voice","cat":"have-each-others-backs"},
  {"id":"rh-1024","type":"role-play","hook":"A targeted girl says she feels small after a week of online contempt.","setup":"Hand her back the mirror. Say:","yourLine":[{"text":"\"Their opinion doesn't set your worth. I see who you actually are.\"","best":true},{"text":"\"Maybe just stay off your phone forever then.\""}],"relearn":"Remind her their contempt doesn't set her worth.","persona":"Riya","source":"refuse / support voice","cat":"have-each-others-backs"},
  {"id":"rh-1025","type":"role-play","hook":"Your friend is about to repost a clip dunking on a girl from school.","setup":"Stop it before it spreads. Say:","yourLine":[{"text":"\"Don't repost that, it's her life. Let's not make it worse.\"","best":true},{"text":"\"Tag me in it, that's hilarious.\""}],"relearn":"Ask him not to repost; refusing to spread it is real power.","persona":"any","source":"refuse voice","cat":"have-each-others-backs"},
  {"id":"rh-1026","type":"role-play","hook":"A friend confides he feels worthless and you're worried about him.","setup":"Take it seriously, point to help. Say:","yourLine":[{"text":"\"I'm really glad you told me. Let's call Tele-MANAS 14416 together?\"","best":true},{"text":"\"Don't be dramatic, everyone feels like that.\""}],"relearn":"Take it seriously and offer to reach Tele-MANAS 14416 together.","persona":"Counsellor","source":"need-underneath voice","cat":"have-each-others-backs"},
  {"id":"rh-1027","type":"role-play","hook":"You're nervous but want to back a girl being mocked in the group chat.","setup":"Step in, even if it's shaky. Say:","yourLine":[{"text":"\"Leave her alone. This isn't funny and I'm not laughing.\"","best":true},{"text":"\"...\" (say nothing and hope it stops)"}],"relearn":"Even a shaky 'leave her alone' backs the person targeted.","persona":"any","source":"upstander voice","cat":"have-each-others-backs"},
  {"id":"rh-1028","type":"reflect","hook":"Lensy: a mate goes quiet for weeks. What's your first move?","prompt":"Pick one.","options":["Text them something dumb to make them laugh","Show up at their door","Tell an adult you both trust"],"affirm":"There's no wrong first move: showing up at all is the point.","relearn":"A joke, a visit or pulling in an adult are all real ways to reach a mate who's gone quiet.","persona":"any","source":"identity","cat":"have-each-others-backs"},
  {"id":"rh-1029","type":"reflect","hook":"Lensy: a friend opens up and feels less alone with you. How does that sit?","prompt":"What do you feel?","options":["Glad I'm here","That's what friends do","Quietly proud"],"affirm":"Being someone's real connection is its own kind of strength.","relearn":"Being a friend's real connection meets the need the funnel faked.","persona":"any","source":"belonging","cat":"have-each-others-backs"},
  {"id":"rh-1030","type":"reflect","hook":"Lensy: you refused to forward a cruel clip about a girl. Notice that?","prompt":"What do you think?","options":["It mattered","Small but real","I'd do it again"],"affirm":"Every person who won't pass it on shrinks how far it spreads.","relearn":"Refusing to spread it is real, quiet power.","persona":"any","source":"refuse","cat":"have-each-others-backs"},
  {"id":"rh-1031","type":"reflect","hook":"Lensy: someone aimed contempt at you and you didn't let it in. How's that?","prompt":"Sit with it.","options":["My worth's my own","I won't absorb it","That's mine to decide"],"affirm":"Their opinion was never the thing that sets your worth.","relearn":"You can refuse to absorb contempt; your worth is your own.","persona":"Riya","source":"refuse","cat":"have-each-others-backs"},
  {"id":"rh-1032","type":"reflect","hook":"Lensy: writing a friend off, or staying connected, which actually pulls them back?","prompt":"What do you think?","options":["Staying connected","Being there","Not giving up on them"],"affirm":"Connection competes with the funnel; writing them off just feeds it.","relearn":"Staying connected pulls a friend back; writing them off pushes them in.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1033","type":"reflect","hook":"Lensy: you stepped in for someone being targeted. What does that say about you?","prompt":"Pick one.","options":["I show up","I won't watch silently","I have people's backs"],"affirm":"Showing up for someone targeted is a kind of courage.","relearn":"Backing someone targeted is courage worth keeping.","persona":"any","source":"upstander","cat":"have-each-others-backs"},
  {"id":"rh-1034","type":"reflect","hook":"Lensy: a friend's stuff got too big for you and you told an adult. How do you feel?","prompt":"What's true for you?","options":["Right call","Still his friend","Glad he's safer"],"affirm":"Bringing in help when it's beyond you is caring, not betraying.","relearn":"Looping in a trusted adult when it's beyond you is caring.","persona":"any","source":"safeguard","cat":"have-each-others-backs"},
  {"id":"rh-1035","type":"reflect","hook":"Lensy: which kind of brave is it to call a friend in instead of calling him out?","prompt":"What do you think?","options":["The patient kind","The caring kind","The harder kind"],"affirm":"Staying kind when it'd be easier to dunk is its own brave.","relearn":"Calling a friend in, not out, is the harder, caring kind of brave.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1036","type":"reflect","hook":"Lensy: a mate let you down by co-signing the cruel stuff. Where to from here?","prompt":"Sit with it.","options":["Tell him how it felt","Give it time","Leave a door open"],"affirm":"You get to be honest about the hurt and still leave a door open.","relearn":"You can name the hurt and still leave a door open.","persona":"any","source":"repair","cat":"have-each-others-backs"},
  {"id":"rh-1037","type":"reflect","hook":"Lensy: what's one way you'd want a friend to back you if you were the target?","prompt":"Pick one.","options":["Just be there","Say it's not on me","Help me report it"],"affirm":"What you'd want for yourself is a good guide for backing others.","relearn":"How you'd want to be backed is a good guide for backing others.","persona":"any","source":"support","cat":"have-each-others-backs"},
  {"id":"rh-1038","type":"reflect","hook":"Lensy: a quieter friend looked lonely, so you invited him in. How's that land?","prompt":"What do you feel?","options":["Costs me nothing","Felt right","Glad I noticed"],"affirm":"A small invitation can outshine anything sold online.","relearn":"A small, real invitation competes with what the funnel sells.","persona":"any","source":"belonging","cat":"have-each-others-backs"},
  {"id":"rh-1039","type":"sort","hook":"Sort: pulls a friend back, or pushes them deeper?","items":[{"id":"a","text":"Asking how he's really doing"},{"id":"b","text":"Calling him a creep in the chat"},{"id":"c","text":"Inviting him to hang out"},{"id":"d","text":"Posting 'cringe' on his stuff"},{"id":"e","text":"Listening without a lecture"},{"id":"f","text":"Writing him off as a lost cause"}],"bins":[{"id":"back","label":"Pulls them back","valence":"pos"},{"id":"deeper","label":"Pushes them in","valence":"neg"}],"key":{"a":"back","b":"deeper","c":"back","d":"deeper","e":"back","f":"deeper"},"relearn":"Connection and curiosity pull a friend back; mockery and rejection push them in.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1040","type":"sort","hook":"Sort: a call-in, or a call-out?","items":[{"id":"a","text":"\"What's really going on for you?\""},{"id":"b","text":"Tagging the group to shame him"},{"id":"c","text":"Checking a claim together"},{"id":"d","text":"Screenshotting to mock him later"},{"id":"e","text":"\"I'm still your mate either way\""},{"id":"f","text":"Announcing he's brainwashed"}],"bins":[{"id":"in","label":"Call-in (stays close)","valence":"pos"},{"id":"out","label":"Call-out (pushes off)","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"A call-in stays close and curious; a call-out shames and pushes off.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1041","type":"sort","hook":"Sort: backs a targeted girl, or leaves her alone with it?","items":[{"id":"a","text":"\"That's on them, not you\""},{"id":"b","text":"\"Just toughen up\""},{"id":"c","text":"Offering to help report it"},{"id":"d","text":"\"Maybe leave the chat\""},{"id":"e","text":"Refusing to laugh along"},{"id":"f","text":"Staying silent to avoid drama"}],"bins":[{"id":"back","label":"Backs her","valence":"pos"},{"id":"alone","label":"Leaves her alone","valence":"neg"}],"key":{"a":"back","b":"alone","c":"back","d":"alone","e":"back","f":"alone"},"relearn":"Backing her means the burden shifts off her, not onto her.","persona":"Riya","source":"support","cat":"have-each-others-backs"},
  {"id":"rh-1042","type":"sort","hook":"Sort: meets the need underneath, or deepens it?","items":[{"id":"a","text":"\"That lonely feeling is real\""},{"id":"b","text":"\"Man up and get over it\""},{"id":"c","text":"Inviting him to do stuff together"},{"id":"d","text":"\"That's so weak of you\""},{"id":"e","text":"Helping him reach real support"},{"id":"f","text":"Telling him to just be alone"}],"bins":[{"id":"meets","label":"Meets the need","valence":"pos"},{"id":"deepens","label":"Deepens it","valence":"neg"}],"key":{"a":"meets","b":"deepens","c":"meets","d":"deepens","e":"meets","f":"deepens"},"relearn":"Naming the need and offering connection meets it; 'man up' deepens it.","persona":"Counsellor","source":"need-underneath","cat":"have-each-others-backs"},
  {"id":"rh-1043","type":"sort","hook":"Sort: speak up now, or careful: wait and route it?","items":[{"id":"a","text":"A sexist 'joke' in class"},{"id":"b","text":"A friend hinting at hurting someone"},{"id":"c","text":"A 'rate the girls' thread starting"},{"id":"d","text":"A friend's views turning genuinely scary"},{"id":"e","text":"A cruel reply under a girl's post"},{"id":"f","text":"A friend talking about self-harm"}],"bins":[{"id":"now","label":"Name it now","valence":"tell"},{"id":"adult","label":"Careful: loop in an adult","valence":"uhoh"}],"key":{"a":"now","b":"adult","c":"now","d":"adult","e":"now","f":"adult"},"relearn":"Everyday provocation you can name; serious or scary stuff routes to a trusted adult.","persona":"any","source":"safeguard / upstander","cat":"have-each-others-backs"},
  {"id":"rh-1044","type":"sort","hook":"Sort: refusing to absorb it, or letting it in?","items":[{"id":"a","text":"\"Their opinion isn't my worth\""},{"id":"b","text":"Believing the worst it says"},{"id":"c","text":"Blocking and moving on"},{"id":"d","text":"Replaying the insults all night"},{"id":"e","text":"Naming it as manipulation"},{"id":"f","text":"Changing how you act to please it"}],"bins":[{"id":"refuse","label":"Refusing to absorb","valence":"pos"},{"id":"absorb","label":"Letting it in","valence":"neg"}],"key":{"a":"refuse","b":"absorb","c":"refuse","d":"absorb","e":"refuse","f":"absorb"},"relearn":"You can name it, block it, and keep your worth your own.","persona":"Riya","source":"refuse","cat":"have-each-others-backs"},
  {"id":"rh-1045","type":"sort","hook":"Sort: keeps the door open, or slams it shut?","items":[{"id":"a","text":"\"I'm here whenever you want\""},{"id":"b","text":"\"Lose my number\""},{"id":"c","text":"Owning a harsh thing you said"},{"id":"d","text":"\"You're a lost cause now\""},{"id":"e","text":"Reaching out first after a fight"},{"id":"f","text":"Telling everyone he's a creep"}],"bins":[{"id":"open","label":"Keeps door open","valence":"pos"},{"id":"shut","label":"Slams it shut","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"An open door and an owned mistake reconnect; ultimatums and labels slam it shut.","persona":"any","source":"repair","cat":"have-each-others-backs"},
  {"id":"rh-1046","type":"match","hook":"Match each friend's real need to the healthy answer.","pairs":[{"left":"Feels lonely at home","right":"A standing invite to hang out"},{"left":"Feels invisible","right":"A friend who actually notices him"},{"left":"Wants to feel respected","right":"A group that lifts, not ranks"},{"left":"Scared no one would care","right":"Someone who checks in first"},{"left":"Ashamed he feels low","right":"\"No shame, that's human\""}],"relearn":"Each real need has a healthy answer a friend can offer.","persona":"Counsellor","source":"need-underneath","cat":"have-each-others-backs"},
  {"id":"rh-1047","type":"match","hook":"Match the call-out move to its kinder call-in version.","pairs":[{"left":"\"You're brainwashed\"","right":"\"Want to check that claim with me?\""},{"left":"\"You've become a creep\"","right":"\"How are you really doing?\""},{"left":"Posting 'cringe' publicly","right":"A quiet DM instead"},{"left":"\"Lose my number\"","right":"\"Door's open whenever\""},{"left":"Shaming him in the group","right":"Talking one-to-one"}],"relearn":"Every call-out has a call-in that reaches the person instead.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1048","type":"match","hook":"Match the worry to where it routes for real help.","pairs":[{"left":"A friend feels low and lonely","right":"Tele-MANAS 14416 or a trusted adult"},{"left":"Someone is abused online","right":"Save evidence, report at 1930"},{"left":"A friend hints at self-harm","right":"Stay; tell an adult now"},{"left":"Harassment keeps coming","right":"Block, document, tell someone"},{"left":"Not sure who to turn to","right":"A trusted adult you know"}],"relearn":"Loneliness routes to Tele-MANAS 14416 or a trusted adult; harassment to 1930.","persona":"Counsellor","source":"help / report","cat":"have-each-others-backs"},
  {"id":"rh-1049","type":"match","hook":"Match what a targeted person needs to how you can back them.","pairs":[{"left":"To not feel alone","right":"\"I've got you\""},{"left":"To know it's not their fault","right":"\"That's on them, not you\""},{"left":"Help with the scary part","right":"\"Let's report it together\""},{"left":"To not be pushed out","right":"\"I'll call it out so you can stay\""},{"left":"Their worth back","right":"\"Their opinion isn't who you are\""}],"relearn":"Backing the targeted person means presence, blame on the abuser, and real help.","persona":"Riya","source":"support","cat":"have-each-others-backs"},
  {"id":"rh-1050","type":"match","hook":"Match the funnel's fake offer to what real friendship gives instead.","pairs":[{"left":"A 'brotherhood' you pay for","right":"Friends who cost nothing"},{"left":"Belonging if you blame women","right":"Belonging just as you are"},{"left":"Status from ranking others","right":"Respect from lifting others"},{"left":"A crowd that drops you if you doubt","right":"A friend who stays through doubts"},{"left":"A cure for being 'not enough'","right":"\"You're already enough\""}],"relearn":"Real friendship gives free what the funnel only rents.","persona":"any","source":"belonging","cat":"have-each-others-backs"},
  {"id":"rh-1051","type":"match","hook":"Match the slipping-friend moment to a caring opener you could use.","pairs":[{"left":"He's gone quiet for weeks","right":"\"Missed you. How are things?\""},{"left":"He repeats a blame line","right":"\"What's going on for you?\""},{"left":"He admits he feels alone","right":"\"That makes sense. I'm here.\""},{"left":"His group turned on him","right":"\"Door's open, no pressure.\""},{"left":"You were harsh last time","right":"\"I was unfair. Can we talk?\""}],"relearn":"Each moment has a caring opener that reaches the friend.","persona":"any","source":"call-in voice","cat":"have-each-others-backs"},
  {"id":"rh-1052","type":"match","hook":"Match the bystander reflex to the upstander move that backs someone.","pairs":[{"left":"Laughing so you fit in","right":"\"Not funny to me\""},{"left":"Staying silent to avoid drama","right":"\"Leave her alone\""},{"left":"Forwarding the cruel clip","right":"\"I'm not sharing that\""},{"left":"Joining the rating thread","right":"\"They're our classmates\""},{"left":"Hoping someone else steps in","right":"Being the one who does"}],"relearn":"Every bystander reflex has an upstander move that backs the target.","persona":"any","source":"upstander","cat":"have-each-others-backs"},
  {"id":"rh-1053","type":"match","hook":"Match the harsh response to what actually helps a friend instead.","pairs":[{"left":"\"Man up\"","right":"\"That feeling's real\""},{"left":"\"You're pathetic\"","right":"\"No shame, I'm here\""},{"left":"\"Just ignore it\"","right":"\"Let's deal with it together\""},{"left":"\"Get a thicker skin\"","right":"\"It's manipulation, not you\""},{"left":"\"You're a lost cause\"","right":"\"It's not too late\""}],"relearn":"What helps a friend is care and presence, not toughen-up lines.","persona":"any","source":"need-underneath","cat":"have-each-others-backs"},
  {"id":"rh-1054","type":"spot","hook":"Spot the two lines that would push a slipping friend deeper, not back.","scene":[{"id":"a","text":"\"How are you actually doing lately?\"","trick":false},{"id":"b","text":"\"You've turned into a total creep.\"","trick":true},{"id":"c","text":"\"I'm still your mate, whatever happens.\"","trick":false},{"id":"d","text":"\"Everyone thinks you're a lost cause now.\"","trick":true},{"id":"e","text":"\"Want to hang out this weekend?\"","trick":false}],"why":"Naming him a creep and writing him off shame him and push him further in.","relearn":"Shaming and writing a friend off push him deeper; stay connected.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1055","type":"spot","hook":"Spot the two responses that leave a targeted girl alone with the abuse.","scene":[{"id":"a","text":"\"That's on them, not you.\"","trick":false},{"id":"b","text":"\"You're probably overreacting.\"","trick":true},{"id":"c","text":"\"Want help reporting it?\"","trick":false},{"id":"d","text":"\"Just leave the chat, easier for everyone.\"","trick":true},{"id":"e","text":"\"I'll back you up if it keeps up.\"","trick":false}],"why":"'Overreacting' and 'just leave' push the burden onto her instead of the abuser.","relearn":"Back the targeted person; don't put the burden of leaving on her.","persona":"Riya","source":"support","cat":"have-each-others-backs"},
  {"id":"rh-1056","type":"spot","hook":"Spot the two moves that are a call-out (shaming), not a call-in.","scene":[{"id":"a","text":"DM him: \"What's going on with you?\"","trick":false},{"id":"b","text":"Tag the group to publicly shame him","trick":true},{"id":"c","text":"\"I miss hanging out, you good?\"","trick":false},{"id":"d","text":"Comment 'cringe' on every post","trick":true},{"id":"e","text":"\"Let's check that claim together.\"","trick":false}],"why":"Public shaming and 'cringe' comments are call-outs that push him to dig in.","relearn":"A call-in stays private and curious; public shaming pushes him to dig in.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1057","type":"spot","hook":"Spot the two replies that deepen a lonely friend's hurt instead of meeting it.","scene":[{"id":"a","text":"\"That lonely feeling is real and common.\"","trick":false},{"id":"b","text":"\"Man up and get over it.\"","trick":true},{"id":"c","text":"\"No shame, I'm here for real.\"","trick":false},{"id":"d","text":"\"That's so weak of you.\"","trick":true},{"id":"e","text":"\"Let's do something together this week.\"","trick":false}],"why":"'Man up' and 'so weak' shame the need and deepen the hurt the funnel preys on.","relearn":"Meet a lonely friend's need with care; shaming it only deepens the hurt.","persona":"Counsellor","source":"need-underneath","cat":"have-each-others-backs"},
  {"id":"rh-1058","type":"spot","hook":"Spot the two bystander moves that feed the abuse instead of backing the target.","scene":[{"id":"a","text":"Refusing to share the cruel clip","trick":false},{"id":"b","text":"Laughing along so you fit in","trick":true},{"id":"c","text":"Telling him to delete it","trick":false},{"id":"d","text":"Forwarding it 'just to see'","trick":true},{"id":"e","text":"Messaging her that you've got her","trick":false}],"why":"Laughing along and forwarding it spread the harm and reward the provocation.","relearn":"Refusing to laugh or forward backs the target; spreading it feeds the harm.","persona":"any","source":"upstander","cat":"have-each-others-backs"},
  {"id":"rh-1059","type":"spot","hook":"Spot the two things that slam the door on a friend you want back.","scene":[{"id":"a","text":"\"I'm here whenever you want.\"","trick":false},{"id":"b","text":"\"Lose my number, we're done.\"","trick":true},{"id":"c","text":"\"I was harsh before, I'm sorry.\"","trick":false},{"id":"d","text":"\"You're beyond saving now.\"","trick":true},{"id":"e","text":"\"No pressure, door's open.\"","trick":false}],"why":"An ultimatum and 'beyond saving' slam the door the repair was trying to open.","relearn":"An open door and an owned mistake reconnect; ultimatums slam it shut.","persona":"any","source":"repair","cat":"have-each-others-backs"},
  {"id":"rh-1060","type":"spot","hook":"Spot the two reactions that let online contempt set your worth.","scene":[{"id":"a","text":"\"Their opinion isn't my worth.\"","trick":false},{"id":"b","text":"Believing the worst it says about you","trick":true},{"id":"c","text":"Blocking and moving on","trick":false},{"id":"d","text":"Changing yourself to please the haters","trick":true},{"id":"e","text":"Naming it as manipulation","trick":false}],"why":"Believing it and reshaping yourself for the haters hand them power over your worth.","relearn":"Refuse to absorb online contempt; your worth isn't theirs to set.","persona":"Riya","source":"refuse","cat":"have-each-others-backs"},
  {"id":"rh-1061","type":"spot","hook":"Spot the two times to stop helping alone and loop in a trusted adult.","scene":[{"id":"a","text":"A friend made a dumb sexist joke once","trick":false},{"id":"b","text":"A friend hints he might hurt someone","trick":true},{"id":"c","text":"A friend shared a clip you disliked","trick":false},{"id":"d","text":"A friend talks about not wanting to be here","trick":true},{"id":"e","text":"A friend quoted an 'alpha' line","trick":false}],"why":"Hints of hurting someone or himself are too big to carry alone: tell an adult.","relearn":"When it's genuinely scary, keep caring and loop in a trusted adult.","persona":"any","source":"safeguard","cat":"have-each-others-backs"},
  {"id":"rh-1062","type":"strike-rewrite","hook":"A line you might have heard about helping a slipping friend.","myth":{"un":"Mock a friend out of it: embarrass him and he'll stop.","re":"Stay connected and ask real questions: a call-in, not a call-out.","why":"Mockery makes a friend defensive and pushes him deeper; staying close reaches him."},"relearn":"Help a friend by staying connected and asking, not mocking.","persona":"any","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1063","type":"strike-rewrite","hook":"A line about a friend who's gone too far.","myth":{"un":"Once a friend's into this stuff, he's a lost cause: write him off.","re":"It's rarely too late to reconnect; repair is possible.","why":"Writing him off leaves only the funnel, while reaching out can reopen the door."},"relearn":"It's rarely too late to reconnect and be a real friend again.","persona":"any","source":"repair","cat":"have-each-others-backs"},
  {"id":"rh-1064","type":"strike-rewrite","hook":"A line about contempt aimed your way online.","myth":{"un":"If enough strangers online say you're worthless, it must be a bit true.","re":"Your worth isn't theirs to set; you can refuse to absorb the contempt.","why":"Engineered contempt is manipulation, not a measurement of who you are."},"relearn":"You can refuse to absorb online misogyny; your worth isn't theirs to set.","persona":"Riya","source":"refuse","cat":"have-each-others-backs"},
  {"id":"rh-1065","type":"strike-rewrite","hook":"A line about stepping in when someone's targeted.","myth":{"un":"Staying out of it is the smart, safe move, not your problem.","re":"Backing someone targeted helps; the blame is on the abuser, not them.","why":"Silence leaves the targeted person alone, while support shifts the weight off them."},"relearn":"Back someone targeted; it's on the abuser, not them.","persona":"any","source":"support","cat":"have-each-others-backs"},
  {"id":"rh-1066","type":"strike-rewrite","hook":"A line about a friend admitting he feels low.","myth":{"un":"If your mate's feeling low, tell him to man up: that's what helps.","re":"Take the feeling seriously and help him reach support; 'man up' only deepens it.","why":"Shaming the feeling pushes it underground, while care and real help meet it."},"relearn":"'Man up' deepens it; help a hurting friend reach support instead.","persona":"Counsellor","source":"need-underneath","cat":"have-each-others-backs"},
  {"id":"rh-1067","type":"strike-rewrite","hook":"A line about provocation in the class chat.","myth":{"un":"If you react big to the bait, you'll shut the troublemaker down.","re":"Don't reward provocation: name it calmly or tell a teacher.","why":"A big reaction is the payoff the bait wants; calm naming takes its power away."},"relearn":"Don't reward provocation; name it calmly or tell a teacher.","persona":"Riya","source":"upstander","cat":"have-each-others-backs"},
  {"id":"rh-1068","type":"strike-rewrite","hook":"A line about how far a friend's problem is yours to fix.","myth":{"un":"A real friend handles everything himself and never tells anyone.","re":"If it's genuinely worrying, keep caring and loop in a trusted adult.","why":"Some things are too big to carry alone; bringing in help is caring, not betraying."},"relearn":"If it's beyond you, keep caring and loop in a trusted adult.","persona":"any","source":"safeguard","cat":"have-each-others-backs"},
  {"id":"rh-1069","type":"strike-rewrite","hook":"A line about how to reach a friend who's changed.","myth":{"un":"Open with the accusation: call out exactly what he's done wrong.","re":"Open with care and curiosity; a caring question reaches further than an insult.","why":"Accusation makes him defend the views, while curiosity reaches the person."},"relearn":"Open with care and curiosity, not accusation.","persona":"Veer","source":"call-in","cat":"have-each-others-backs"},
  {"id":"rh-1080","cat":"real-strong","type":"reflect","hook":"Lensy: the strongest people you know are usually the calmest. Notice that too?","prompt":"What do you think?","options":["Yes","Calm is strong","I've seen that"],"affirm":"Calm under pressure is a quiet power no bravado can fake.","relearn":"Real strength is often calm, not loud or aggressive.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1081","cat":"real-strong","type":"reflect","hook":"Lensy: you can lose an argument and still be the bigger person. Sit with that.","prompt":"What do you think?","options":["Yes","That's true","I'd like that"],"affirm":"Letting go of needing to 'win' every time is its own strength.","relearn":"You can be wrong or lose a point and still hold real strength.","persona":"any","source":"self-worth"},
  {"id":"rh-1082","cat":"real-strong","type":"reflect","hook":"Lensy: helping a friend study or train, with nothing in it for you, is strength. Feel that?","prompt":"What do you think?","options":["Yes","That's a good thing","I do that"],"affirm":"Lifting someone with no payback is exactly what real strength does.","relearn":"Helping others with nothing in it for you is real strength.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1083","cat":"real-strong","type":"reflect","hook":"Lensy: you don't owe anyone a 'tough guy' performance to be respected. Agree?","prompt":"What do you think?","options":["Yes","That's a relief","I don't"],"affirm":"Being real beats performing tough; respect follows the genuine you.","relearn":"You don't have to perform 'tough' to earn respect.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1084","cat":"real-strong","type":"reflect","hook":"Lensy: what's one real skill you're proud of building, no shortcut, no course?","prompt":"Pick one.","options":["Sport or fitness","Studies or a subject","Music or art","Fixing or making things"],"affirm":"That's real, it's yours, and no influencer sold it to you.","relearn":"Real confidence comes from skills you actually build yourself.","persona":"any","source":"confidence"},
  {"id":"rh-1085","cat":"real-strong","type":"reflect","hook":"Lensy: a man who apologises first is showing strength, not weakness. Does that land?","prompt":"What do you think?","options":["Yes","Takes guts","I see that"],"affirm":"Apologising first takes more courage than never backing down.","relearn":"Apologising first is strength, not weakness.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1086","cat":"real-strong","type":"reflect","hook":"Lensy: you can admire someone's success without putting yourself down. Both okay?","prompt":"What do you think?","options":["Yes","Both","Good to know"],"affirm":"Another person's win doesn't shrink you, there's room for everyone.","relearn":"You can admire others' success without ranking yourself below them.","persona":"any","source":"self-worth"},
  {"id":"rh-1087","cat":"real-strong","type":"reflect","hook":"Lensy: protecting someone who's being picked on takes real courage. Recognise that?","prompt":"What do you think?","options":["Yes","That's brave","I'd want to"],"affirm":"Standing up for someone smaller is strength used the right way.","relearn":"Using your strength to protect, not dominate, is the real thing.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1088","cat":"real-strong","type":"reflect","hook":"Lensy: discipline you choose for yourself feels nothing like discipline someone sells you. Notice the difference?","prompt":"What do you think?","options":["Yes","Big difference","Mine feels better"],"affirm":"Self-chosen discipline grows you; a sold 'grind' just grows their wallet.","relearn":"Discipline you choose for yourself beats any 'grindset' sold online.","persona":"Veer","source":"real growth"},
  {"id":"rh-1089","cat":"real-strong","type":"reflect","hook":"Lensy: being someone your younger cousin or sibling can look up to, what would that take?","prompt":"Pick one.","options":["Being kind to them","Keeping my word","Staying steady when things are hard"],"affirm":"Any of those makes you the kind of strong worth copying.","relearn":"Real strength is the kind a younger kid could safely look up to.","persona":"any","source":"role models"},
  {"id":"rh-1090","cat":"real-strong","type":"reflect","hook":"Lensy: you can be confident and still be unsure sometimes. Both can be true. Agree?","prompt":"What do you think?","options":["Yes","Both","That fits me"],"affirm":"Confidence isn't pretending to know everything, it's being okay not to.","relearn":"Confidence and self-doubt can coexist; you don't have to fake certainty.","persona":"any","source":"self-worth"},
  {"id":"rh-1091","cat":"real-strong","type":"reflect","hook":"Lensy: a good leader makes the people around them better, not smaller. Does that fit your idea of strong?","prompt":"What do you think?","options":["Yes","That's a leader","I'd follow that"],"affirm":"Real leadership lifts the team, it never runs on fear.","relearn":"Strong leadership makes people around you better, not smaller.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1092","cat":"real-strong","type":"reflect","hook":"Lensy: you get to define what kind of man you want to be, no influencer decides it for you. Feel that?","prompt":"What do you think?","options":["Yes","It's mine to decide","Good"],"affirm":"Your definition of yourself isn't for sale and isn't theirs to set.","relearn":"You define the kind of man you want to be, not an algorithm.","persona":"Veer","source":"identity"},
  {"id":"rh-1093","cat":"real-strong","type":"reflect","hook":"Lensy: keeping a promise even when it's hard, that's a strength people remember. Agree?","prompt":"What do you think?","options":["Yes","Reliability matters","I want to be that"],"affirm":"Being someone whose word holds is strength people quietly trust.","relearn":"Keeping your word, especially when it's hard, is real strength.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1094","cat":"real-strong","type":"reflect","hook":"Lensy: treating your sister or mother with respect at home is part of being strong, not separate from it. Sit with that.","prompt":"What do you think?","options":["Yes","Of course","That's right"],"affirm":"How you treat the women in your life is the truest test of strength.","relearn":"Respecting the women in your own home is part of real strength.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1095","cat":"real-strong","type":"reflect","hook":"Lensy: you can be competitive and still want your rivals to do well. Both?","prompt":"What do you think?","options":["Yes","Both","I like that"],"affirm":"Wanting to win and wishing others well aren't enemies.","relearn":"You can compete hard and still respect and root for others.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1096","cat":"real-strong","type":"reflect","hook":"Lensy: the version of you that's patient with a struggling kid, that's strength too. Recognise it?","prompt":"What do you think?","options":["Yes","Patience is strong","I see it"],"affirm":"Patience with someone weaker is strength holding itself back kindly.","relearn":"Patience and gentleness with the weaker are forms of strength.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1097","cat":"real-strong","type":"reflect","hook":"Lensy: 'be yourself' sounds basic, but it's the thing no grift can sell you. Notice that?","prompt":"What do you think?","options":["Yes","It's free","It's mine"],"affirm":"Being genuinely you costs nothing and beats any sold persona.","relearn":"Being yourself is the one thing no 'alpha' course can sell you.","persona":"any","source":"self-worth"},
  {"id":"rh-1098","cat":"real-strong","type":"reflect","hook":"Lensy: which of these would you most want said about you one day?","prompt":"Pick one.","options":["'He always had my back'","'He stayed kind under pressure'","'He kept his word'"],"affirm":"That's a strength worth building your whole self around.","relearn":"The strength worth aiming for is the kind people remember warmly.","persona":"any","source":"role models"},
  {"id":"rh-1099","cat":"real-strong","type":"sort","hook":"Sort: real confidence, or a bought 'alpha' costume?","items":[{"id":"a","text":"Earned through a skill you practised"},{"id":"b","text":"Worn like a costume to look superior"},{"id":"c","text":"Steady whether people watch or not"},{"id":"d","text":"Needs an audience to feel real"},{"id":"e","text":"Lets you admit what you don't know"},{"id":"f","text":"Can never be seen to be unsure"}],"bins":[{"id":"real","label":"Real confidence","valence":"pos"},{"id":"fake","label":"Bought costume","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Real confidence is steady and earned; the 'alpha' costume needs an audience.","persona":"Veer","source":"confidence"},
  {"id":"rh-1100","cat":"real-strong","type":"sort","hook":"Sort: a sign of real maturity, or just bravado?","items":[{"id":"a","text":"Listening before you react"},{"id":"b","text":"Shouting down anyone who disagrees"},{"id":"c","text":"Saying 'I don't know' when you don't"},{"id":"d","text":"Pretending to know everything"},{"id":"e","text":"Walking away from a pointless fight"},{"id":"f","text":"Picking a fight to look hard"}],"bins":[{"id":"mature","label":"Maturity","valence":"pos"},{"id":"bravado","label":"Bravado","valence":"neg"}],"key":{"a":"mature","b":"bravado","c":"mature","d":"bravado","e":"mature","f":"bravado"},"relearn":"Listening, admitting gaps and walking away are mature; bravado isn't.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1101","cat":"real-strong","type":"sort","hook":"Sort: this lifts people, or it puts them down?","items":[{"id":"a","text":"Hyping a teammate after a loss"},{"id":"b","text":"Roasting someone to look funny"},{"id":"c","text":"Sharing credit for a win"},{"id":"d","text":"Taking all the credit yourself"},{"id":"e","text":"Defending a kid who's being mocked"},{"id":"f","text":"Joining in to mock them"}],"bins":[{"id":"lift","label":"Lifts people","valence":"pos"},{"id":"down","label":"Puts down","valence":"neg"}],"key":{"a":"lift","b":"down","c":"lift","d":"down","e":"lift","f":"down"},"relearn":"Real strength lifts people up; it never needs to put anyone down.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1102","cat":"real-strong","type":"sort","hook":"Sort: a healthy way to handle anger, or a toxic one?","items":[{"id":"a","text":"Taking a breath before you speak"},{"id":"b","text":"Lashing out to feel in control"},{"id":"c","text":"Telling someone you trust how you feel"},{"id":"d","text":"Bottling it up till you explode"},{"id":"e","text":"Going for a run to cool down"},{"id":"f","text":"Punching a wall to look tough"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"toxic","label":"Toxic","valence":"neg"}],"key":{"a":"healthy","b":"toxic","c":"healthy","d":"toxic","e":"healthy","f":"toxic"},"relearn":"Real strength handles anger by cooling down and talking, not by lashing out.","persona":"Veer","source":"wellbeing"},
  {"id":"rh-1103","cat":"real-strong","type":"sort","hook":"Sort: builds genuine respect, or just fear?","items":[{"id":"a","text":"Keeping your promises"},{"id":"b","text":"Threatening people who cross you"},{"id":"c","text":"Treating juniors as equals"},{"id":"d","text":"Bullying anyone weaker"},{"id":"e","text":"Owning up when you mess up"},{"id":"f","text":"Blaming others for your mistakes"}],"bins":[{"id":"respect","label":"Earns respect","valence":"pos"},{"id":"fear","label":"Only fear","valence":"neg"}],"key":{"a":"respect","b":"fear","c":"respect","d":"fear","e":"respect","f":"fear"},"relearn":"Real respect is earned by how you treat people, never demanded through fear.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1104","cat":"real-strong","type":"sort","hook":"Sort: a real way to grow, or a sales funnel selling you growth?","items":[{"id":"a","text":"A free workout plan from your coach"},{"id":"b","text":"A paid 'become a king' bootcamp"},{"id":"c","text":"Reading and asking real mentors"},{"id":"d","text":"A locked 'inner circle' tier"},{"id":"e","text":"Practising a skill daily yourself"},{"id":"f","text":"'DM me to unlock the secret'"}],"bins":[{"id":"real","label":"Real growth","valence":"pos"},{"id":"funnel","label":"Sales funnel","valence":"neg"}],"key":{"a":"real","b":"funnel","c":"real","d":"funnel","e":"real","f":"funnel"},"relearn":"Real growth is mostly free and earned; 'unlock the secret' tiers are a funnel.","persona":"any","source":"real vs grift"},
  {"id":"rh-1105","cat":"real-strong","type":"sort","hook":"Sort: strong AND kind together, or the toughness cage?","items":[{"id":"a","text":"Comforting a friend who's crying"},{"id":"b","text":"'Real men never show feelings'"},{"id":"c","text":"Asking how someone's really doing"},{"id":"d","text":"'Caring is for the weak'"},{"id":"e","text":"Saying sorry and meaning it"},{"id":"f","text":"'Apologising is losing'"}],"bins":[{"id":"both","label":"Strong and kind","valence":"pos"},{"id":"cage","label":"The cage","valence":"neg"}],"key":{"a":"both","b":"cage","c":"both","d":"cage","e":"both","f":"cage"},"relearn":"Strong and kind is the goal; the 'never feel, never care' cage isn't strength.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1106","cat":"real-strong","type":"sort","hook":"Sort: a healthy source of self-worth, or one that can be taken away?","items":[{"id":"a","text":"Living by your own values"},{"id":"b","text":"Being 'above' other people"},{"id":"c","text":"Skills you keep practising"},{"id":"d","text":"How many followers you have"},{"id":"e","text":"Being a good friend"},{"id":"f","text":"Always 'winning' against others"}],"bins":[{"id":"solid","label":"Solid worth","valence":"pos"},{"id":"shaky","label":"Easily lost","valence":"neg"}],"key":{"a":"solid","b":"shaky","c":"solid","d":"shaky","e":"solid","f":"shaky"},"relearn":"Self-worth built on values and friendship is solid; 'being above others' isn't.","persona":"any","source":"self-worth"},
  {"id":"rh-1107","cat":"real-strong","type":"sort","hook":"Sort: a green flag in how someone treats girls, or a red one?","items":[{"id":"a","text":"Listens when she says no"},{"id":"b","text":"Calls her 'low value'"},{"id":"c","text":"Treats her as a friend, not a prize"},{"id":"d","text":"Keeps a 'body count' scorecard"},{"id":"e","text":"Respects her even after a rejection"},{"id":"f","text":"Says she 'owes' him for being nice"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Respecting a 'no' and treating girls as people are green flags; scorecards aren't.","persona":"any","source":"green flags / consent"},
  {"id":"rh-1108","cat":"real-strong","type":"sort","hook":"Sort: real ambition, or a grindset costume?","items":[{"id":"a","text":"Working toward a goal you chose"},{"id":"b","text":"Hustling just to flex online"},{"id":"c","text":"Resting so you can keep going"},{"id":"d","text":"'Sleep is for the weak'"},{"id":"e","text":"Measuring progress against yourself"},{"id":"f","text":"Measuring worth by who you beat"}],"bins":[{"id":"real","label":"Real ambition","valence":"pos"},{"id":"costume","label":"Grindset costume","valence":"neg"}],"key":{"a":"real","b":"costume","c":"real","d":"costume","e":"real","f":"costume"},"relearn":"Real ambition has rest and your own goals; the 'grindset' is a costume to flex.","persona":"Veer","source":"real growth"},
  {"id":"rh-1109","cat":"real-strong","type":"sort","hook":"Sort: a strength that's truly yours, or one borrowed to look big?","items":[{"id":"a","text":"A talent you practised for years"},{"id":"b","text":"Bragging about a famous 'mentor'"},{"id":"c","text":"Kindness people feel from you"},{"id":"d","text":"Quoting an influencer's hot take"},{"id":"e","text":"Courage you showed yourself"},{"id":"f","text":"A flashy car in the background"}],"bins":[{"id":"yours","label":"Truly yours","valence":"pos"},{"id":"borrowed","label":"Borrowed shine","valence":"neg"}],"key":{"a":"yours","b":"borrowed","c":"yours","d":"borrowed","e":"yours","f":"borrowed"},"relearn":"Real strength is yours; quoting a guru or flexing props is borrowed shine.","persona":"any","source":"self-worth"},
  {"id":"rh-1110","cat":"real-strong","type":"sort","hook":"Sort: handles a rejection with strength, or with entitlement?","items":[{"id":"a","text":"Accepting her no and moving on"},{"id":"b","text":"Spreading rumours to get back"},{"id":"c","text":"Staying polite even if it stings"},{"id":"d","text":"Calling her names online"},{"id":"e","text":"Letting yourself feel it, then healing"},{"id":"f","text":"Deciding 'all girls are the same'"}],"bins":[{"id":"strong","label":"Real strength","valence":"pos"},{"id":"entitled","label":"Entitlement","valence":"neg"}],"key":{"a":"strong","b":"entitled","c":"strong","d":"entitled","e":"strong","f":"entitled"},"relearn":"Handling a no with grace is strength; revenge and 'all girls' talk is entitlement.","persona":"any","source":"the hook / consent"},
  {"id":"rh-1111","cat":"real-strong","type":"sort","hook":"Sort: this would make a younger boy stronger, or just colder?","items":[{"id":"a","text":"'It's okay to ask for help'"},{"id":"b","text":"'Trust no one, ever'"},{"id":"c","text":"'Treat people the way you'd want'"},{"id":"d","text":"'Look down on the weak'"},{"id":"e","text":"'Your feelings are normal'"},{"id":"f","text":"'Crying makes you a loser'"}],"bins":[{"id":"stronger","label":"Stronger","valence":"pos"},{"id":"colder","label":"Just colder","valence":"neg"}],"key":{"a":"stronger","b":"colder","c":"stronger","d":"colder","e":"stronger","f":"colder"},"relearn":"What truly makes a boy stronger is warmth and help, not coldness and contempt.","persona":"any","source":"mentoring / positive masculinity"},
  {"id":"rh-1112","cat":"real-strong","type":"branch","hook":"Friends dare you to roast a quiet kid to prove you're 'one of the strong ones'.","options":[{"text":"Pass, and quietly include him instead","consequence":"You stay genuinely strong and gain a real friend.","outcome":"strong","best":true},{"text":"Roast him so the group laughs","consequence":"Punching down isn't strength; including him is the stronger move."}],"debrief":"Real strength never needs a smaller person to look big.","relearn":"Including someone is stronger than roasting them for a laugh.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1113","cat":"real-strong","type":"branch","hook":"You're tempted to buy the 'high-value man' course your feed keeps pushing.","options":[{"text":"Put the money into a real skill or class instead","consequence":"You build something real no one can sell back to you.","outcome":"real","best":true},{"text":"Buy the course to finally 'fix' yourself","consequence":"It sells a fix for an invented lack; a real skill grows you more."}],"debrief":"Genuine growth is built, not bought from a paywall.","relearn":"Spend on real skills, not a 'high-value man' course.","persona":"Veer","source":"real growth / the grift"},
  {"id":"rh-1114","cat":"real-strong","type":"branch","hook":"You lost a match badly in front of everyone and feel like hiding.","options":[{"text":"Congratulate the winner and plan how to improve","consequence":"You show the steadiness that real strength is made of.","outcome":"steady","best":true},{"text":"Storm off and blame the ref","consequence":"Blaming and storming off is the weaker move; steadiness is strength."}],"debrief":"How you carry a loss shows more strength than any win.","relearn":"Carrying a loss with grace is real strength; blaming isn't.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1115","cat":"real-strong","type":"branch","hook":"A reel insists you must be 'feared' to be respected at school.","options":[{"text":"Earn respect by being reliable and fair instead","consequence":"People trust you, which lasts far longer than fear.","outcome":"respected","best":true},{"text":"Act intimidating so people back off","consequence":"Fear isn't respect; being reliable and fair earns the real thing."}],"debrief":"Respect you earn beats fear you force, every time.","relearn":"Real respect is earned by being fair and reliable, not feared.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1116","cat":"real-strong","type":"branch","hook":"Your gym group keeps saying caring about marks or family is 'beta'.","options":[{"text":"Keep caring about what matters to you","consequence":"You stay grounded in a real, fuller version of strong.","outcome":"grounded","best":true},{"text":"Drop the things you care about to seem 'alpha'","consequence":"'Alpha/beta' is pseudo-science; caring about real things is strength."}],"debrief":"You don't have to shed what you value to seem strong.","relearn":"Caring about studies, family and goals is strength, not 'beta'.","persona":"any","source":"pseudo-science / self-worth"},
  {"id":"rh-1117","cat":"real-strong","type":"branch","hook":"You realise you've been copying an influencer's harsh, mocking way of talking.","options":[{"text":"Go back to talking like yourself, with respect","consequence":"People relax around you and you feel like you again.","outcome":"yourself","best":true},{"text":"Keep the persona; it gets a reaction","consequence":"The persona isn't you; respect is the stronger fit."}],"debrief":"The real you is stronger than a borrowed act.","relearn":"Being respectfully yourself beats copying a harsh persona.","persona":"Veer","source":"identity / self-worth"},
  {"id":"rh-1118","cat":"real-strong","type":"role-play","hook":"A younger boy says he cried and feels ashamed. Reset that for him.","setup":"Take the shame off him. Say:","yourLine":[{"text":"\"Crying's normal, even for the toughest people. It doesn't make you less.\"","best":true},{"text":"\"Yeah, better toughen up before someone sees.\""}],"relearn":"Tell a younger boy that crying is normal and doesn't make him less.","persona":"any","source":"positive masculinity / wellbeing"},
  {"id":"rh-1119","cat":"real-strong","type":"role-play","hook":"A mate brags he never says sorry because 'apologising is weak'.","setup":"Offer the stronger view. Say:","yourLine":[{"text":"\"Owning a mistake takes more guts than never backing down. That's the strong move.\"","best":true},{"text":"\"True, never apologise, keep the upper hand.\""}],"relearn":"Owning a mistake takes more strength than never apologising.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1120","cat":"real-strong","type":"role-play","hook":"A friend says real men should 'keep score' with girls. Reframe it.","setup":"Set a better standard. Say:","yourLine":[{"text":"\"Treating girls as people, not a scoreboard, is the actual strong move.\"","best":true},{"text":"\"Yeah, the higher the count, the more of a man you are.\""}],"relearn":"Treating girls as people, not a scoreboard, is the strong choice.","persona":"any","source":"positive masculinity / consent"},
  {"id":"rh-1121","cat":"real-strong","type":"role-play","hook":"Your cousin asks how to be confident without 'looking down on people'.","setup":"Show him it's possible. Say:","yourLine":[{"text":"\"Build a skill you're proud of and be kind, real confidence needs no one below you.\"","best":true},{"text":"\"You can't, you have to feel above others to feel good.\""}],"relearn":"Real confidence is built on skill and kindness, not on looking down.","persona":"any","source":"confidence"},
  {"id":"rh-1122","cat":"real-strong","type":"role-play","hook":"A teammate mocks another for being 'too soft'. Stand up for strong-and-kind.","setup":"Back the kinder kid. Say:","yourLine":[{"text":"\"Being kind isn't soft, it takes real strength. Lay off him.\"","best":true},{"text":"\"Haha yeah, he's such a softie.\""}],"relearn":"Stand up for a kind friend: kindness is strength, not softness.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1123","cat":"real-strong","type":"role-play","hook":"A friend wants to skip sleep and food to chase a 'grindset'. Care for him.","setup":"Offer the real version. Say:","yourLine":[{"text":"\"Rest is part of getting strong, not the enemy. Burning out isn't winning.\"","best":true},{"text":"\"Sleep is for losers, push harder.\""}],"relearn":"Rest is part of real strength; the 'no sleep grindset' isn't winning.","persona":"any","source":"real growth / wellbeing"},
  {"id":"rh-1124","cat":"real-strong","type":"match","hook":"Match the real strength to what it looks like in everyday life.","pairs":[{"left":"Courage","right":"Standing up for a kid being mocked"},{"left":"Patience","right":"Helping a friend who's struggling"},{"left":"Honesty","right":"Owning a mistake out loud"},{"left":"Self-control","right":"Walking away from a pointless fight"},{"left":"Loyalty","right":"Having a friend's back for real"}],"relearn":"Real strengths show up as everyday kindness, honesty and self-control.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1125","cat":"real-strong","type":"match","hook":"Match the toxic 'rule' to the freer truth that replaces it.","pairs":[{"left":"'Win at any cost'","right":"Play hard, stay fair"},{"left":"'Show no feelings'","right":"Name what you feel"},{"left":"'Dominate to be respected'","right":"Earn respect by how you treat people"},{"left":"'Need no one'","right":"Lean on people you trust"},{"left":"'Worth is a ranking'","right":"Everyone has equal worth"}],"relearn":"Each toxic 'rule' has a freer, truer version that's actual strength.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1126","cat":"real-strong","type":"match","hook":"Match each role model to the strength they show.","pairs":[{"left":"The calm captain","right":"Steady under pressure"},{"left":"The patient coach","right":"Lifts others up"},{"left":"The honest friend","right":"Tells you the truth kindly"},{"left":"The fair leader","right":"Treats everyone with respect"},{"left":"The quiet helper","right":"Gives without needing credit"}],"relearn":"The strengths worth admiring are steadiness, lifting others, honesty and fairness.","persona":"any","source":"role models"},
  {"id":"rh-1127","cat":"real-strong","type":"match","hook":"Match the put-down 'a real man would...' to what real strength actually does.","pairs":[{"left":"'...never lose an argument'","right":"Can say 'you're right'"},{"left":"'...never cry'","right":"Lets himself feel"},{"left":"'...never ask for help'","right":"Asks when he needs to"},{"left":"'...keep women in line'","right":"Treats them as equals"},{"left":"'...crush the weak'","right":"Protects them"}],"relearn":"Real strength does the opposite of every 'real man would' put-down.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1128","cat":"real-strong","type":"match","hook":"Match the feeling to the strong, healthy thing to do with it.","pairs":[{"left":"Angry","right":"Cool down, then talk it out"},{"left":"Jealous","right":"Focus on your own growth"},{"left":"Rejected","right":"Feel it, then move on with grace"},{"left":"Insecure","right":"Build a real skill"},{"left":"Lonely","right":"Reach out to someone you trust"}],"relearn":"Every hard feeling has a strong, healthy thing to do with it.","persona":"any","source":"wellbeing"},
  {"id":"rh-1129","cat":"real-strong","type":"match","hook":"Match the empty flex to the real strength it's trying to imitate.","pairs":[{"left":"Bragging about money","right":"Being generous quietly"},{"left":"Loud bravado","right":"Calm self-assurance"},{"left":"Putting others down","right":"Lifting others up"},{"left":"Demanding respect","right":"Earning it"},{"left":"A borrowed persona","right":"Being yourself"}],"relearn":"Every empty flex is a hollow imitation of a real, quieter strength.","persona":"any","source":"self-worth"},
  {"id":"rh-1130","cat":"real-strong","type":"strike-rewrite","hook":"\"Being vulnerable with friends will get you laughed at.\"","myth":{"un":"If you open up to friends, you'll just get laughed at.","re":"Real friends meet honesty with support; opening up is what makes a bond strong.","why":"The 'never be vulnerable' rule keeps boys isolated, which is the funnel's fuel."},"relearn":"Opening up to real friends builds strong bonds; it isn't weakness.","persona":"Veer","source":"the hook / belonging"},
  {"id":"rh-1131","cat":"real-strong","type":"strike-rewrite","hook":"\"Nice guys finish last, so stop being kind.\"","myth":{"un":"Nice guys finish last, so being kind is a losing move.","re":"Kindness with backbone builds the trust and respect people actually keep around.","why":"'Kindness loses' is a hook to push you toward contempt, which repels people."},"relearn":"Kindness with backbone wins trust; 'nice guys finish last' is a hook.","persona":"any","source":"the hook"},
  {"id":"rh-1132","cat":"real-strong","type":"strike-rewrite","hook":"\"You have to be a bit cruel or people walk all over you.\"","myth":{"un":"You have to be a bit cruel, or people will walk all over you.","re":"You can be firm and set boundaries without cruelty; respect and clear limits do the job.","why":"Cruelty isn't strength, it's a costume worn by people who feel small."},"relearn":"Firm boundaries, not cruelty, stop people walking over you.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1133","cat":"real-strong","type":"strike-rewrite","hook":"\"Real strength means never letting anyone see you struggle.\"","myth":{"un":"Real strength means never letting anyone see you struggle.","re":"Letting trusted people see your struggle, and asking for help, is real strength.","why":"Hiding every struggle is the 'always hard' mask, and it isolates you."},"relearn":"Letting trusted people see you struggle is strength, not weakness.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1134","cat":"real-strong","type":"strike-rewrite","hook":"\"Confidence is something you can buy if you find the right coach.\"","myth":{"un":"Confidence is something you can buy from the right paid coach.","re":"Confidence is built through real skills, effort and good people, not bought.","why":"'Buy your confidence' is the grift's whole pitch, the cure for an invented lack."},"relearn":"Confidence is built through skills and effort, never bought from a coach.","persona":"any","source":"confidence / the grift"},
  {"id":"rh-1135","cat":"real-strong","type":"strike-rewrite","hook":"\"A man's value is how many people look up to him.\"","myth":{"un":"A man's value is measured by how many people look up to him.","re":"Your worth isn't a follower count or a ranking; it's steady and already yours.","why":"Tying worth to status keeps you chasing it, which is exactly what the grift wants."},"relearn":"Your worth isn't a ranking or a follower count; it's already yours.","persona":"any","source":"self-worth"},
  {"id":"rh-1136","cat":"real-strong","type":"strike-rewrite","hook":"\"Looking after your health and feelings is for girls.\"","myth":{"un":"Looking after your health and feelings is a girl thing.","re":"Caring for your body and mind is basic strength, for everyone, no gender attached.","why":"Framing self-care as 'for girls' is the toughness cage that harms boys."},"relearn":"Caring for your body and mind is strength for everyone, not 'for girls'.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1137","cat":"real-strong","type":"strike-rewrite","hook":"\"If you're not dominating, you're being dominated.\"","myth":{"un":"If you're not dominating someone, you're the one being dominated.","re":"Most of life isn't a dominance contest; respect and cooperation work better than ranking.","why":"The 'dominate or be dominated' frame is pseudo-science used to keep you anxious."},"relearn":"Life isn't 'dominate or be dominated'; respect beats ranking people.","persona":"any","source":"pseudo-science"},
  {"id":"rh-1138","cat":"real-strong","type":"spot","hook":"Spot the two lines that fake strength by putting people down.","scene":[{"id":"a","text":"\"I helped my friend train\"","trick":false},{"id":"b","text":"\"I roasted that kid till he went quiet\"","trick":true},{"id":"c","text":"\"I owned up when I got it wrong\"","trick":false},{"id":"d","text":"\"I keep everyone reminded they're below me\"","trick":true},{"id":"e","text":"\"I stayed calm when he wound me up\"","trick":false}],"why":"Roasting someone and keeping people 'below' you fake strength by belittling.","relearn":"Real strength lifts people; putting others down only fakes it.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1139","cat":"real-strong","type":"spot","hook":"Spot the two 'rules' that are really the toughness cage in disguise.","scene":[{"id":"a","text":"\"It's fine to ask a friend for help\"","trick":false},{"id":"b","text":"\"Real men never show a single feeling\"","trick":true},{"id":"c","text":"\"You can be strong and gentle\"","trick":false},{"id":"d","text":"\"Needing anyone makes you weak\"","trick":true},{"id":"e","text":"\"Crying doesn't make you less of a man\"","trick":false}],"why":"'Never feel anything' and 'needing anyone is weak' are the cage that harms boys.","relearn":"'Never feel' and 'need no one' are cages, not strength.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1140","cat":"real-strong","type":"spot","hook":"Spot the two lines that are entitlement, not strength.","scene":[{"id":"a","text":"\"She said no, so I wished her well and left\"","trick":false},{"id":"b","text":"\"She owes me for being nice to her\"","trick":true},{"id":"c","text":"\"I respect a no even when it stings\"","trick":false},{"id":"d","text":"\"If she rejects me, she'll regret it\"","trick":true},{"id":"e","text":"\"Everyone gets to choose, including her\"","trick":false}],"why":"'She owes me' and 'she'll regret it' are entitlement; respecting a no is strength.","relearn":"No one owes you their interest; entitlement isn't strength.","persona":"any","source":"the hook / consent"},
  {"id":"rh-1141","cat":"real-strong","type":"spot","hook":"Spot the two 'self-improvement' lines that are really a sales pitch.","scene":[{"id":"a","text":"\"Practise a skill a bit every day\"","trick":false},{"id":"b","text":"\"You're nothing until you buy my academy\"","trick":true},{"id":"c","text":"\"Read, and ask people you trust\"","trick":false},{"id":"d","text":"\"DM me to unlock the alpha secret\"","trick":true},{"id":"e","text":"\"Rest counts as part of getting strong\"","trick":false}],"why":"'Buy my academy' and 'DM for the secret' are the grift, not real growth.","relearn":"Real growth is mostly free; 'buy the secret' is a sales pitch.","persona":"any","source":"real vs grift"},
  {"id":"rh-1142","cat":"real-strong","type":"spot","hook":"Spot the two lines selling fake confidence.","scene":[{"id":"a","text":"\"I feel solid because I earned this skill\"","trick":false},{"id":"b","text":"\"I only feel big when others feel small\"","trick":true},{"id":"c","text":"\"I'm okay admitting what I don't know\"","trick":false},{"id":"d","text":"\"I can never be seen to be unsure\"","trick":true},{"id":"e","text":"\"I'm steady whether or not people watch\"","trick":false}],"why":"Needing others small and never seeming unsure is the fake 'alpha' costume.","relearn":"Real confidence is steady and earned; the costume needs you to look down.","persona":"Veer","source":"confidence"},
  {"id":"rh-1143","cat":"real-strong","type":"spot","hook":"Spot the two tips that make a younger boy colder, not stronger.","scene":[{"id":"a","text":"\"Treat people how you'd want to be treated\"","trick":false},{"id":"b","text":"\"Trust no one but yourself\"","trick":true},{"id":"c","text":"\"It's okay to feel things and talk\"","trick":false},{"id":"d","text":"\"Look down on anyone weaker\"","trick":true},{"id":"e","text":"\"Stand up for kids who get picked on\"","trick":false}],"why":"'Trust no one' and 'look down on the weak' make a boy colder, not stronger.","relearn":"Warmth makes a boy stronger; contempt and distrust don't.","persona":"any","source":"mentoring / positive masculinity"},
  {"id":"rh-1144","cat":"real-strong","type":"spot","hook":"Spot the two lines that copy a harsh influencer instead of being real.","scene":[{"id":"a","text":"\"How are you actually doing, mate?\"","trick":false},{"id":"b","text":"\"Stay silent, emotions are for the weak\"","trick":true},{"id":"c","text":"\"Nice one, you earned that\"","trick":false},{"id":"d","text":"\"Everyone's beneath me until they prove worth\"","trick":true},{"id":"e","text":"\"Let's sort this out together\"","trick":false}],"why":"The cold 'emotions are weak' and 'everyone's beneath me' lines are a copied persona.","relearn":"Being warm and real beats copying a harsh online persona.","persona":"Veer","source":"identity / self-worth"},
  {"id":"rh-1145","cat":"real-strong","type":"spot","hook":"Spot the two 'manly rules' that are really the grindset costume.","scene":[{"id":"a","text":"\"Rest so you can keep going strong\"","trick":false},{"id":"b","text":"\"Sleep is for the weak, grind nonstop\"","trick":true},{"id":"c","text":"\"Measure progress against yourself\"","trick":false},{"id":"d","text":"\"You're a loser unless you out-hustle all\"","trick":true},{"id":"e","text":"\"Pick goals that matter to you\"","trick":false}],"why":"'No sleep' and 'out-hustle all or you're a loser' are the grindset costume.","relearn":"Real ambition has rest and your own goals; the grindset is a costume.","persona":"any","source":"real growth"},
  {"id":"rh-1170","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"A good woman is a man's reward for self-improvement.\"","myth":{"un":"A girlfriend is the prize you earn by 'levelling up' as a man.","re":"People aren't trophies handed out for reaching a level; a partner is an equal who chooses you.","why":"'Earn a woman' treats a person as a reward, which kills real connection."},"relearn":"People aren't prizes you earn; a partner is an equal who chooses you.","persona":"any","source":"the hook / consent"},
  {"id":"rh-1171","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Being vulnerable just gives people ammunition to use on you.\"","myth":{"un":"Open up and you're only handing people ammunition.","re":"Sharing with people you trust is how real closeness and support get built.","why":"The 'never open up' rule is exactly what keeps the funnel's boys isolated."},"relearn":"Opening up to people you trust builds closeness, not ammunition.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1172","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"If you're not improving every day, you're falling behind other men.\"","myth":{"un":"Skip one day and you've already lost the race against other men.","re":"Growth isn't a daily race against anyone; rest and steady effort both count.","why":"The 'always behind' panic keeps you hooked on whoever sells the cure."},"relearn":"Growth isn't a daily race against others; rest counts too.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1174","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"She friend-zoned you, so she used you.\"","myth":{"un":"If she just wants friendship, she used you and owes you more.","re":"Wanting friendship isn't using you; no one owes romance for kindness.","why":"'Friend-zone' reframes a normal no as a debt she must repay."},"relearn":"Friendship isn't being used; no one owes romance for kindness.","persona":"any","source":"the hook / consent"},
  {"id":"rh-1175","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Crying is something a man should never let anyone see.\"","myth":{"un":"A real man never lets anyone see him cry.","re":"Crying is a normal release everyone needs; hiding it doesn't make you stronger.","why":"'Never cry' is the same mask that isolates the boys the funnel targets."},"relearn":"Crying is normal for everyone; hiding it isn't strength.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1176","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Approach a hundred girls. It's just a numbers game.\"","myth":{"un":"Dating is a numbers game; just run the script on enough girls.","re":"People aren't targets to run a script on; real connection isn't a sales funnel.","why":"Treating people as numbers is the grift's pickup-course pitch, not how friendship works."},"relearn":"People aren't a numbers game; connection isn't a script.","persona":"any","source":"the hook / pickup"},
  {"id":"rh-1177","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Women are only attracted to money and status, never the real you.\"","myth":{"un":"Girls only care about money and status, never who you really are.","re":"Plenty of people value kindness, humour and honesty; that cynicism just keeps you bitter.","why":"'They only want money' excuses contempt and sells you a 'status' upgrade."},"relearn":"Many people value kindness and honesty, not just money or status.","persona":"any","source":"the hook / cynicism"},
  {"id":"rh-1178","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Therapy and counselling are for people who can't handle life.\"","myth":{"un":"Counselling is for people too weak to handle their own life.","re":"Talking to a counsellor is a skill-building tool, like coaching for your mind.","why":"Mocking help keeps boys away from the very support that works."},"relearn":"Counselling is a tool for anyone, not a sign of weakness.","persona":"Counsellor","source":"the hook / help-seeking"},
  {"id":"rh-1179","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"You have to be feared to be respected.\"","myth":{"un":"If people don't fear you a little, they'll never respect you.","re":"Fear makes people avoid you; respect comes from being fair and reliable.","why":"'Be feared' sells intimidation as strength, but it just leaves you alone."},"relearn":"Respect comes from being fair and reliable, not feared.","persona":"any","source":"the hook / respect"},
  {"id":"rh-1180","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Feminism is a war on men.\"","myth":{"un":"Feminism is basically a war being waged against men.","re":"Equality isn't a war; the same fairness that frees girls also frees boys from rigid roles.","why":"Framing fairness as an attack is the us-vs-them hook in action."},"relearn":"Equality isn't a war on men; fairness frees boys too.","persona":"any","source":"us-vs-them"},
  {"id":"rh-1181","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"A man who does housework or cooks has been domesticated.\"","myth":{"un":"A man who cooks or cleans has let himself be tamed.","re":"Running a home is a shared adult skill, not a loss of manhood.","why":"Shaming everyday care work keeps an old role that helps no one."},"relearn":"Cooking and chores are adult skills, not a loss of manhood.","persona":"any","source":"the hook / roles"},
  {"id":"rh-1183","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"He's just saying what everyone's too scared to say.\"","myth":{"un":"He's brave: just saying the truths everyone's too scared to admit.","re":"Saying a cruel thing loudly isn't brave or true; shock is just how he gets views.","why":"'Brave truth-teller' is a costume that dresses up rage-bait as honesty."},"relearn":"Saying something cruel loudly isn't brave or true; it's bait for views.","persona":"any","source":"media literacy"},
  {"id":"rh-1184","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Real men provide everything alone and never ask for help.\"","myth":{"un":"A real man carries the whole load alone and never asks for help.","re":"No one is meant to carry everything alone; sharing the load is how families actually work.","why":"The 'sole provider, no help' rule is a cage that wears boys down."},"relearn":"No one carries it all alone; sharing the load is how it works.","persona":"any","source":"the hook / roles"},
  {"id":"rh-1185","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Apologising makes you look weak, so never do it.\"","myth":{"un":"Saying sorry makes you look weak; never back down.","re":"Owning a mistake and saying sorry is a sign of strength and steadiness.","why":"'Never apologise' protects ego at the cost of every real relationship."},"relearn":"Owning a mistake and apologising is strength, not weakness.","persona":"any","source":"the hook / accountability"},
  {"id":"rh-1186","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Some men are just born winners and the rest are born to lose.\"","myth":{"un":"You're either born a winner or born to lose, and that's that.","re":"People aren't born into fixed 'winner' and 'loser' tiers; skills and worth grow over time.","why":"A fake fixed hierarchy makes you despair or pay to 'climb' it."},"relearn":"No one is born a fixed winner or loser; people grow.","persona":"any","source":"pseudo-science"},
  {"id":"rh-1187","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"If she changed her mind, she was 'testing' you.\"","myth":{"un":"When a girl says no or changes her mind, she's just testing you.","re":"A no is a no, not a test to push past; 'she's testing you' is how the script teaches boys to ignore consent.","why":"Reframing a no as a 'test' is the exact trick that erodes consent."},"relearn":"A no isn't a test; 'she's testing you' is a trick to ignore consent.","persona":"any","source":"the hook / consent"},
  {"id":"rh-1188","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Lonely? That just proves the world is against you.\"","myth":{"un":"Feeling lonely proves the whole world is rigged against you.","re":"Loneliness is a common signal to reach for connection, not proof of a conspiracy.","why":"Turning a normal feeling into 'they're all against you' is the funnel's fuel."},"relearn":"Loneliness is a signal to connect, not proof the world's against you.","persona":"Veer","source":"the need underneath"},
  {"id":"rh-1189","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Mock anyone who disagrees. That's how you win an argument.\"","myth":{"un":"You win an argument by mocking and humiliating whoever disagrees.","re":"Mockery ends a conversation; it never changes a mind or earns respect.","why":"'Own them' is performance for an audience, not actually being right."},"relearn":"Mockery ends conversations; it never wins respect or changes minds.","persona":"any","source":"media literacy"},
  {"id":"rh-1190","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Trusting people is naive; assume everyone's out to use you.\"","myth":{"un":"Trusting anyone is naive: assume everyone's out to use you.","re":"Most people aren't out to get you; total distrust just leaves you isolated.","why":"Constant suspicion is the mindset that keeps the funnel's grip tight."},"relearn":"Most people aren't out to use you; total distrust just isolates you.","persona":"any","source":"the hook / cynicism"},
  {"id":"rh-1194","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"You can spot a person's whole worth from how they look.\"","myth":{"un":"You can rank a person's entire worth from a glance at their looks.","re":"Looks tell you nothing about someone's worth, character or kindness.","why":"'Rate people on sight' is the same human-ranking trick the funnel runs."},"relearn":"Looks tell you nothing about a person's worth or character.","persona":"any","source":"pseudo-science"},
  {"id":"rh-1195","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Anger is the only feeling a strong man is allowed.\"","myth":{"un":"The only feeling a strong man may show is anger.","re":"All feelings are allowed; bottling everything into anger is what actually hurts you.","why":"'Only anger is manly' is the funnel funnelling every feeling into rage."},"relearn":"All feelings are allowed; funnelling them into anger only hurts you.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1196","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Having close friends you talk to is a bit 'beta'.\"","myth":{"un":"Boys with close friends they actually talk to are a bit 'beta'.","re":"Close friendships are one of the strongest things you can have, not a weakness.","why":"Labelling friendship 'beta' is the ranking trick aimed at your support."},"relearn":"Close friendships are a strength, not a 'beta' weakness.","persona":"Veer","source":"the hook / belonging"},
  {"id":"rh-1197","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"If a joke punches down on girls and you don't laugh, you're soft.\"","myth":{"un":"Not laughing at a put-down joke about girls makes you soft.","re":"Choosing not to laugh at cruelty is a quiet kind of strength, not softness.","why":"'You're soft if you don't laugh' is peer pressure doing the funnel's work."},"relearn":"Not laughing at cruelty is strength, not softness.","persona":"any","source":"the hook / peer pressure"},
  {"id":"rh-1198","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Once you 'redpill', you can never go back to being naive.\"","myth":{"un":"Once you've 'woken up', going back would just make you naive again.","re":"Changing your mind when you see the trick is wisdom, not going backward.","why":"'No going back' is a one-way door the grift installs to keep you in."},"relearn":"Changing your mind when you see the trick is wisdom, not naivety.","persona":"any","source":"media literacy"},
  {"id":"rh-1200","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Real men don't have anxiety; they just push through.\"","myth":{"un":"Real men don't get anxious: they just push it down and power on.","re":"Anxiety is a normal human signal; naming it and getting support is the strong move.","why":"'Just push through' tells boys to ignore a signal that needs care."},"relearn":"Anxiety is normal; naming it and getting support is the strong move.","persona":"Counsellor","source":"the need underneath"},
  {"id":"rh-1201","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"If your dad was strict and cold, that's how to be a man.\"","myth":{"un":"A cold, strict father is the blueprint for how to be a man.","re":"You get to choose your own model of manhood, including warmth your dad maybe couldn't show.","why":"Romanticising coldness passes the same cage to the next boy."},"relearn":"You choose your own model of manhood, warmth included.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1202","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Caring about the planet or others is a distraction from your grind.\"","myth":{"un":"Caring about other people or the world just distracts from your grind.","re":"Caring about something bigger than yourself is part of a meaningful, strong life.","why":"'Only grind matters' shrinks your world down to whatever he's selling."},"relearn":"Caring about others and the world is part of a strong, meaningful life.","persona":"any","source":"positive masculinity"},
  {"id":"rh-1203","cat":"spot-the-hook","type":"strike-rewrite","hook":"\"Your worth as a man is set by how women rate you.\"","myth":{"un":"How attractive women rate you decides your worth as a man.","re":"Your worth isn't a score other people set; it's not handed out by anyone's rating.","why":"Outsourcing your value to others' approval is what keeps you chasing the fix."},"relearn":"Your worth isn't a rating others set; it's not theirs to hand out.","persona":"any","source":"the hook / self-worth"},
  {"id":"rh-1205","cat":"spot-the-hook","type":"sort","hook":"Sort each line: a manosphere claim, or a media fact?","items":[{"id":"a","text":"'Outrage clips are built to anger you'"},{"id":"b","text":"'Women cause your problems'"},{"id":"c","text":"'A crowd agreeing isn't proof'"},{"id":"d","text":"'There are alpha and beta humans'"},{"id":"e","text":"'The feed served you this on purpose'"},{"id":"f","text":"'He's the only honest voice'"}],"bins":[{"id":"claim","label":"A claim","valence":"neg"},{"id":"fact","label":"A media fact","valence":"pos"}],"key":{"a":"fact","b":"claim","c":"fact","d":"claim","e":"fact","f":"claim"},"relearn":"Outrage-by-design and an engineered feed are facts; the blame lines are claims.","persona":"any","source":"claim vs fact"},
  {"id":"rh-1206","cat":"spot-the-hook","type":"sort","hook":"Sort: pulls a real strength, or sells a fake one?","items":[{"id":"a","text":"'Stay calm under pressure'"},{"id":"b","text":"'Intimidate so people fear you'"},{"id":"c","text":"'Keep your word'"},{"id":"d","text":"'Never let anyone see weakness'"},{"id":"e","text":"'Own your mistakes'"},{"id":"f","text":"'Crush anyone in your way'"}],"bins":[{"id":"real","label":"Real strength","valence":"pos"},{"id":"fake","label":"A fake one","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Calm, keeping your word and owning mistakes are real; fear, hiding and crushing are imitations.","persona":"any","source":"real vs imitation"},
  {"id":"rh-1207","cat":"spot-the-hook","type":"sort","hook":"Sort: why a clip pulls you, or the bust of the hook?","items":[{"id":"a","text":"'Blame feels like instant relief'"},{"id":"b","text":"But the relief is itself the hook"},{"id":"c","text":"'He names a loneliness you feel'"},{"id":"d","text":"Then answers it with contempt"},{"id":"e","text":"'Belonging to a side feels good'"},{"id":"f","text":"But the 'side' funnels to paid tiers"}],"bins":[{"id":"pull","label":"Why it pulls","valence":"uhoh"},{"id":"bust","label":"The bust","valence":"tell"}],"key":{"a":"pull","b":"bust","c":"pull","d":"bust","e":"pull","f":"bust"},"relearn":"The pull is real; the bust shows the trick behind each.","persona":"Veer","source":"why it pulls vs the bust"},
  {"id":"rh-1208","cat":"spot-the-hook","type":"sort","hook":"Sort each tactic: dressed-up insult, or a real argument?","items":[{"id":"a","text":"'Cope, you're just jealous'"},{"id":"b","text":"'Here's the evidence I'm using'"},{"id":"c","text":"'Only betas would disagree'"},{"id":"d","text":"'I could be wrong, let's check'"},{"id":"e","text":"'Stay mad, snowflake'"},{"id":"f","text":"'Fair point, here's my reasoning'"}],"bins":[{"id":"insult","label":"Dressed-up insult","valence":"neg"},{"id":"real","label":"A real argument","valence":"pos"}],"key":{"a":"insult","b":"real","c":"insult","d":"real","e":"insult","f":"real"},"relearn":"'Cope', 'beta' and 'snowflake' are insults, not arguments; evidence and 'I could be wrong' are real.","persona":"any","source":"insult vs argument"},
  {"id":"rh-1209","cat":"spot-the-hook","type":"sort","hook":"Sort: a healthy way to handle a rejection, or a hook's way?","items":[{"id":"a","text":"'It stings, and it'll pass'"},{"id":"b","text":"'She owes you for your time'"},{"id":"c","text":"'Plenty of people are out there'"},{"id":"d","text":"'All girls are like that'"},{"id":"e","text":"'Wish them well and move on'"},{"id":"f","text":"'Get even and make her regret it'"}],"bins":[{"id":"healthy","label":"A healthy way","valence":"pos"},{"id":"hook","label":"The hook's way","valence":"neg"}],"key":{"a":"healthy","b":"hook","c":"healthy","d":"hook","e":"healthy","f":"hook"},"relearn":"'It passes' and 'move on well' are healthy; 'she owes you' and 'get even' are the hook.","persona":"any","source":"rejection: healthy vs hook"},
  {"id":"rh-1210","cat":"spot-the-hook","type":"sort","hook":"Sort: a put-down dressed as advice, or honest advice?","items":[{"id":"a","text":"'Fix yourself, loser, or stay alone'"},{"id":"b","text":"'Small steps add up, you've got this'"},{"id":"c","text":"'You're behind every real man'"},{"id":"d","text":"'Rest is part of getting stronger'"},{"id":"e","text":"'Nobody respects a man like you'"},{"id":"f","text":"'Ask for help when you're stuck'"}],"bins":[{"id":"putdown","label":"A put-down","valence":"neg"},{"id":"honest","label":"Honest advice","valence":"pos"}],"key":{"a":"putdown","b":"honest","c":"putdown","d":"honest","e":"putdown","f":"honest"},"relearn":"Real advice encourages; a put-down shames you, then sells the cure.","persona":"any","source":"put-down vs advice"},
  {"id":"rh-1211","cat":"spot-the-hook","type":"sort","hook":"Sort: a fact about the feed, or a myth about you?","items":[{"id":"a","text":"'Extreme clips travel faster'"},{"id":"b","text":"'You believe it because you chose it'"},{"id":"c","text":"'The feed escalates to keep you on'"},{"id":"d","text":"'If you watched it, it fits you'"},{"id":"e","text":"'One pause can reset your feed'"},{"id":"f","text":"'You're broken if it appealed'"}],"bins":[{"id":"algo","label":"A feed fact","valence":"pos"},{"id":"myth","label":"A myth about you","valence":"neg"}],"key":{"a":"algo","b":"myth","c":"algo","d":"myth","e":"algo","f":"myth"},"relearn":"The feed escalates and resets; 'you chose it' and 'you're broken' are myths.","persona":"Veer","source":"feed fact vs myth"},
  {"id":"rh-1212","cat":"spot-the-hook","type":"sort","hook":"Sort each promise: real growth's offer, or a grift's?","items":[{"id":"a","text":"'You'll grow more independent'"},{"id":"b","text":"'Only my paid tier has the secret'"},{"id":"c","text":"'Mostly free, at your own pace'"},{"id":"d","text":"'Buy now or stay a loser'"},{"id":"e","text":"'You can question and check it'"},{"id":"f","text":"'Trust me, not outsiders'"}],"bins":[{"id":"growth","label":"Real growth","valence":"pos"},{"id":"grift","label":"A grift","valence":"neg"}],"key":{"a":"growth","b":"grift","c":"growth","d":"grift","e":"growth","f":"grift"},"relearn":"Real growth frees you to question; a grift gates the 'secret' and isolates you.","persona":"any","source":"growth vs grift"},
  {"id":"rh-1213","cat":"spot-the-hook","type":"sort","hook":"Sort: real confidence, or insecurity in costume?","items":[{"id":"a","text":"'Okay with being wrong sometimes'"},{"id":"b","text":"'Needs to win every argument'"},{"id":"c","text":"'Lets others shine too'"},{"id":"d","text":"'Puts people down to feel tall'"},{"id":"e","text":"'Asks questions without shame'"},{"id":"f","text":"'Brags to drown out doubt'"}],"bins":[{"id":"confident","label":"Real confidence","valence":"pos"},{"id":"insecure","label":"Insecurity","valence":"neg"}],"key":{"a":"confident","b":"insecure","c":"confident","d":"insecure","e":"confident","f":"insecure"},"relearn":"Being okay with wrong and lifting others is confidence; needing to win is insecurity.","persona":"any","source":"confidence vs insecurity"},
  {"id":"rh-1214","cat":"spot-the-hook","type":"spot","hook":"Spot the two lines that funnel a fitness video toward contempt.","scene":[{"id":"a","text":"'Here's a beginner home workout'","trick":false},{"id":"b","text":"'Soft men let women walk over them'","trick":true},{"id":"c","text":"'Stretch first so you don't pull a muscle'","trick":false},{"id":"d","text":"'Get jacked so they regret ignoring you'","trick":true},{"id":"e","text":"'Progress is slow, be patient'","trick":false}],"why":"'Soft men get walked over' and 'so they regret it' twist a fitness clip into resentment.","relearn":"A workout is fine; the contempt slipped in beside it is the funnel.","persona":"Veer","source":"the funnel / on-ramp"},
  {"id":"rh-1215","cat":"spot-the-hook","type":"spot","hook":"Spot the two lines that turn a 'self-improvement' pitch into a sale.","scene":[{"id":"a","text":"'Read more, sleep well, move daily'","trick":false},{"id":"b","text":"'The real secret is behind my paywall'","trick":true},{"id":"c","text":"'Talk to people you trust'","trick":false},{"id":"d","text":"'Link in bio, act before it's gone'","trick":true},{"id":"e","text":"'Be patient with yourself'","trick":false}],"why":"'Secret behind my paywall' and 'link in bio, act now' are the sales funnel, not advice.","relearn":"If 'free advice' always funnels to a paywall, it's a sales pitch.","persona":"any","source":"follow-the-money"},
  {"id":"rh-1216","cat":"spot-the-hook","type":"spot","hook":"Spot the two pseudo-science lines dressed as facts.","scene":[{"id":"a","text":"'People have many changeable strengths'","trick":false},{"id":"b","text":"'Science proves alpha and beta males'","trick":true},{"id":"c","text":"'Confidence can be built with practice'","trick":false},{"id":"d","text":"'Your DNA sorts you into a tier'","trick":true},{"id":"e","text":"'Anyone can learn new skills'","trick":false}],"why":"'Alpha/beta is science' and 'DNA sorts you into a tier' are pseudo-science, not facts.","relearn":"Ranking people into born 'tiers' is pseudo-science dressed up.","persona":"any","source":"pseudo-science"},
  {"id":"rh-1217","cat":"spot-the-hook","type":"spot","hook":"Spot the two lines that reframe a girl's 'no' as something she owes.","scene":[{"id":"a","text":"'She said no, so that's a no'","trick":false},{"id":"b","text":"'After all you did, she owes you a yes'","trick":true},{"id":"c","text":"'Rejection stings, then it passes'","trick":false},{"id":"d","text":"'Her no is just a test to push past'","trick":true},{"id":"e","text":"'You can wish her well and move on'","trick":false}],"why":"'She owes you a yes' and 'her no is a test to push past' both erase consent.","relearn":"A no is a no; 'she owes you' and 'it's a test' are tricks to ignore it.","persona":"any","source":"spot-the-hook / consent"},
  {"id":"rh-1218","cat":"spot-the-hook","type":"spot","hook":"Spot the two lines that shame, then sell a 'cure'.","scene":[{"id":"a","text":"'Plenty of people would value you'","trick":false},{"id":"b","text":"'You're a loser nobody could want'","trick":true},{"id":"c","text":"'Small steps count, no rush'","trick":false},{"id":"d","text":"'Only my course can fix what you are'","trick":true},{"id":"e","text":"'Rough days don't define you'","trick":false}],"why":"'You're a loser nobody wants' then 'only my course fixes you' is shame-then-sell.","relearn":"Manufacturing your insecurity, then selling the fix, is the whole grift.","persona":"any","source":"follow-the-money"},
  {"id":"rh-1219","cat":"spot-the-hook","type":"spot","hook":"Spot the two lines that fake belonging to hook you in.","scene":[{"id":"a","text":"'You belong here once you subscribe'","trick":true},{"id":"b","text":"'Friends you can text anytime'","trick":false},{"id":"c","text":"'Outsiders aren't real brothers'","trick":true},{"id":"d","text":"'A school club you can just join'","trick":false},{"id":"e","text":"'People who'd notice if you went quiet'","trick":false}],"why":"'Belong once you subscribe' and 'outsiders aren't brothers' sell belonging as a paid, walled club.","relearn":"Real belonging isn't a subscription, and doesn't wall off everyone else.","persona":"any","source":"the need underneath / grift"},
  {"id":"rh-1220","cat":"spot-the-hook","type":"reflect","hook":"Lensy: spotting one of these hooks doesn't mean you 'fell for it'. It means your radar works. Sound right?","prompt":"What do you think?","options":["Yes","My radar's on","Good to know"],"affirm":"Noticing the trick is the whole skill; every one you catch makes the next easier to see.","relearn":"Catching a hook means your radar works, not that you fell for it.","persona":"any","source":"no shame"},
  {"id":"rh-1221","cat":"spot-the-hook","type":"reflect","hook":"Lensy: which of these makes a take easier to question for you?","prompt":"Pick what helps you pause:","options":["Asking who profits","Noticing the insult-as-argument","Checking if it's rage-bait","Spotting the missing evidence"],"affirm":"Any of those is a real off-switch for a hook. Use whichever comes to you first.","relearn":"Asking who profits, or spotting rage-bait, helps you pause and question a take.","persona":"any","source":"media-literacy toolkit"},
  {"id":"rh-1222","cat":"spot-the-hook","type":"reflect","hook":"Lensy: a claim can sound confident and still be wrong. How does that sit with you?","prompt":"Sit with it a moment:","options":["Makes sense","Confidence isn't proof","I'll check more"],"affirm":"Confidence is a tone, not evidence. Letting a calm 'let me check' beat a loud claim is real strength.","relearn":"Confidence is a tone, not proof; a calm 'let me check' beats a loud claim.","persona":"any","source":"media literacy"},
  {"id":"rh-1223","cat":"spot-the-hook","type":"reflect","hook":"Lensy: it's okay if some of these takes once felt true to you. What matters is now. Fair?","prompt":"What do you think?","options":["Fair","No shame","I see it now"],"affirm":"They're built by pros to feel true. Seeing through one now is the win, not a thing to regret.","relearn":"It's okay if a take once felt true; seeing through it now is the win.","persona":"Veer","source":"no shame"},
  {"id":"rh-1224","cat":"spot-the-hook","type":"reflect","hook":"Lensy: which question would you keep in your pocket for a too-confident clip?","prompt":"Pick one to keep:","options":["'Who makes money if I believe this?'","'Is this an argument or an insult?'","'Would this hold up if I checked it?'"],"affirm":"Any one of those is a key that unlocks the trick. Carry the one that feels most like you.","relearn":"A pocket question like 'who profits?' unlocks a too-confident clip.","persona":"any","source":"media-literacy toolkit"},
  {"id":"rh-1225","cat":"spot-the-hook","type":"reflect","hook":"Lensy: noticing a feeling a clip is poking at, like loneliness, can defuse it. Try it?","prompt":"What do you think?","options":["I'll try","That helps","Worth a go"],"affirm":"Naming the feeling it targets ('this is poking my lonely spot') puts you back in charge of it.","relearn":"Naming the feeling a clip pokes at puts you back in charge of it.","persona":"Veer","source":"the need underneath"},
  {"id":"rh-1226","cat":"spot-the-hook","type":"reflect","hook":"Lensy: which truth feels steadiest to stand on when a hook gets loud?","prompt":"Pick your anchor:","options":["'My worth isn't a rank'","'Kindness is real strength'","'No one owes me anything'","'I can ask for help'"],"affirm":"That's a solid anchor. When a hook gets loud, standing on one true thing is enough.","relearn":"A simple truth like 'my worth isn't a rank' anchors you when a hook gets loud.","persona":"any","source":"real-strong toolkit"},
  {"id":"rh-1227","cat":"spot-the-hook","type":"match","hook":"Match each claim to the fact that busts it.","pairs":[{"left":"'Alpha and beta males are science'","right":"People aren't ranked into wolf tiers"},{"left":"'Women are why life is hard'","right":"Loneliness is common, not a group's fault"},{"left":"'Feelings make you weak'","right":"Naming feelings takes strength"},{"left":"'She owes you for being nice'","right":"No one owes you their interest"},{"left":"'Real men need no one'","right":"Everyone needs connection"}],"relearn":"Every confident claim has a calm, true fact that busts it.","persona":"any","source":"claim to bust"},
  {"id":"rh-1228","cat":"spot-the-hook","type":"match","hook":"Match each tactic to what it really is.","pairs":[{"left":"'Loser' first, then a course","right":"Shame used to sell a cure"},{"left":"'Stay mad, snowflake'","right":"An insult, not an argument"},{"left":"A clip made to make you furious","right":"Rage-bait farmed for views"},{"left":"'Only my paid tier has the secret'","right":"A sales funnel, not help"},{"left":"'Outsiders aren't real brothers'","right":"Fake belonging that walls you off"}],"relearn":"Each tactic is a sales or control move once you name it.","persona":"any","source":"tactic to truth"},
  {"id":"rh-1229","cat":"spot-the-hook","type":"match","hook":"Match each hook to the unmet need it's hijacking.","pairs":[{"left":"'Blame them and you'll feel strong'","right":"A wish to feel respected"},{"left":"'Join us, real brothers'","right":"A wish to belong"},{"left":"'Dominate and they'll want you'","right":"A wish to be liked"},{"left":"'We're the only ones who get it'","right":"A wish to feel understood"},{"left":"'You're owed more than this life'","right":"A wish for things to feel fair"}],"relearn":"Each hook hijacks a real, normal need and answers it with contempt.","persona":"Counsellor","source":"hook to need"},
  {"id":"rh-1230","cat":"spot-the-hook","type":"match","hook":"Match each red-flag phrase to the question that defuses it.","pairs":[{"left":"'Everyone agrees with me'","right":"'Did one feed serve them all this?'"},{"left":"'I'm the only honest voice'","right":"'Who profits if I believe that?'"},{"left":"'Science proves it'","right":"'Where's the actual evidence?'"},{"left":"'You're behind every other man'","right":"'Says who, and why now?'"},{"left":"'Buy before it's gone'","right":"'Why the rush to sell me?'"}],"relearn":"Every red-flag phrase has a question that takes its power away.","persona":"any","source":"phrase to question"},
  {"id":"rh-1231","cat":"spot-the-hook","type":"match","hook":"Match each 'strength' he sells to the real strength it imitates.","pairs":[{"left":"Make people fear you","right":"Earn people's respect"},{"left":"Win every argument","right":"Stay open to being wrong"},{"left":"Never show a feeling","right":"Name a feeling honestly"},{"left":"Put others down to rise","right":"Lift others as you rise"},{"left":"Need no one, ever","right":"Let people in"}],"relearn":"Each 'strength' the grift sells is a hollow imitation of a real one.","persona":"any","source":"imitation to real"},
  {"id":"rh-1232","cat":"spot-the-hook","type":"match","hook":"Match each on-ramp topic to the contempt it can get funnelled toward.","pairs":[{"left":"A gym routine","right":"'Soft men get walked over'"},{"left":"Dating tips","right":"'Girls owe you for your effort'"},{"left":"'Be more disciplined'","right":"'You're behind real men already'"},{"left":"Money and hustle","right":"'Anyone broke is just a loser'"},{"left":"'Find your brotherhood'","right":"'Outsiders are the enemy'"}],"relearn":"A relatable topic is the on-ramp; the contempt is what gets bolted on next.","persona":"Veer","source":"on-ramp to contempt"},
  {"id":"rh-1233","cat":"spot-the-hook","type":"match","hook":"Match each cynical line to the warmer truth that answers it.","pairs":[{"left":"'Trusting anyone is naive'","right":"Most people aren't out to use you"},{"left":"'Kindness gets you used'","right":"Kindness builds what you want"},{"left":"'Caring hands people power'","right":"Caring is what closeness is made of"},{"left":"'Looks decide your worth'","right":"Worth isn't something you can see"},{"left":"'You're on your own'","right":"Reaching out is always allowed"}],"relearn":"Each cynical line has a warmer, truer answer.","persona":"any","source":"cynicism to truth"},
  {"id":"rh-1234","cat":"spot-the-hook","type":"branch","hook":"A clip says reply to every 'beta' comment or you've lost. You see one aimed at you.","options":[{"text":"Don't engage; bait only wins if you react","consequence":"The thread fizzles and your evening stays yours.","outcome":"steady","best":true},{"text":"Fire back hard to 'win' it","consequence":"It escalates and feeds the post more views."}],"debrief":"Rage-bait farms your reaction; not replying is the stronger move.","relearn":"Not feeding the bait beats 'winning' the reply.","persona":"any","source":"rage-bait"},
  {"id":"rh-1235","cat":"spot-the-hook","type":"branch","hook":"A creator says: 'Comment ALPHA and I'll DM you the secret to confidence.'","options":[{"text":"Skip it; confidence isn't DM'd to you","consequence":"You keep your details and lose nothing real.","outcome":"clear","best":true},{"text":"Comment and wait for the 'secret'","consequence":"You get a sales link and a paid-tier pitch."}],"debrief":"A gated 'secret to confidence' is a sales funnel; confidence is built.","relearn":"Confidence isn't a secret someone DMs you; it's built over time.","persona":"any","source":"follow-the-money"},
  {"id":"rh-1236","cat":"spot-the-hook","type":"branch","hook":"A video claims 'studies prove women are less logical.' It sounds authoritative.","options":[{"text":"Ask where the study is and check it","consequence":"You find no real study, just a confident voice.","outcome":"checked","best":true},{"text":"Take it as fact since he sounded sure","consequence":"A confident tone becomes 'evidence' you never saw."}],"debrief":"'Studies prove' with no findable study is a confidence trick, not evidence.","relearn":"'Studies prove' means nothing until you find the actual study.","persona":"any","source":"fake stats"},
  {"id":"rh-1237","cat":"spot-the-hook","type":"branch","hook":"After a breakup, your feed fills with 'all women are the same' clips that feel comforting.","options":[{"text":"Notice the feed is feeding your hurt, and reset it","consequence":"You step out of the loop and let the grief move.","outcome":"aware","best":true},{"text":"Lean in; the contempt dulls the ache","consequence":"The relief is the hook; it pulls you deeper."}],"debrief":"The funnel bites hardest in low moments; blame's comfort is the hook.","relearn":"When blame feels comforting after a hurt, it's the hook.","persona":"Veer","source":"low moments"},
  {"id":"rh-1238","cat":"spot-the-hook","type":"branch","hook":"A mentor account says 'real men don't need therapy, just discipline.'","options":[{"text":"Trust your read; talking to someone is strong","consequence":"You book the chat and feel lighter naming things.","outcome":"strong","best":true},{"text":"Drop it so you don't look 'weak'","consequence":"You stay stuck to protect a stranger's image."}],"debrief":"'Real men don't need help' keeps boys from support that works.","relearn":"Talking to someone is a stronger kind of discipline, not weakness.","persona":"Counsellor","source":"help-seeking"},
  {"id":"rh-1239","cat":"spot-the-hook","type":"branch","hook":"A reel ranks people 'high-value' and 'low-value' and invites you to 'find your tier.'","options":[{"text":"Reject the ranking; people aren't value tiers","consequence":"You keep seeing people as people, not scores.","outcome":"clear","best":true},{"text":"Try to find your 'tier' and climb it","consequence":"You measure your worth on a scale he invented."}],"debrief":"'High/low value' is the human-ranking trick; it exists to sell you a climb.","relearn":"People aren't 'high' or 'low' value; the ranking sells a climb.","persona":"any","source":"pseudo-science"},
  {"id":"rh-1240","cat":"spot-the-hook","type":"branch","hook":"A clip says: 'If she rejected you, post the screenshots so everyone sees what she's like.'","options":[{"text":"Don't; a no isn't to punish, and it'd harm her","consequence":"You keep your integrity and drag no one publicly.","outcome":"decent","best":true},{"text":"Post it to 'expose' her","consequence":"You humiliate someone for a no; it follows you both."}],"debrief":"'Expose her for rejecting you' weaponises a normal no; no one owes a yes.","relearn":"A no isn't to punish; exposing someone for it is cruelty.","persona":"any","source":"consent"},
  {"id":"rh-1241","cat":"spot-the-hook","type":"role-play","hook":"A friend repeats a clip's line: 'feminism is just a war on men.' He looks to you.","setup":"You answer calmly, without making it a fight. Say:","yourLine":[{"text":"\"Equality isn't a war. The same fairness helps boys too.\"","best":true},{"text":"\"Yeah, I guess it is kind of against us.\""},{"text":"\"Don't be dumb, that's such a loser take.\""}],"relearn":"You can answer 'war on men' calmly: fairness frees boys too.","persona":"Riya","source":"us-vs-them"},
  {"id":"rh-1242","cat":"spot-the-hook","type":"role-play","hook":"Someone in the group says 'alpha and beta males, it's just biology.'","setup":"You bust it without sounding superior. Say:","yourLine":[{"text":"\"That 'alpha wolf' idea got debunked even in wolves. It's not biology.\"","best":true},{"text":"\"Maybe, I've heard that too.\""},{"text":"\"Only an idiot would believe that.\""}],"relearn":"You can bust 'alpha/beta is biology' with the facts, calmly.","persona":"any","source":"pseudo-science"},
  {"id":"rh-1243","cat":"spot-the-hook","type":"role-play","hook":"A classmate quotes a creator: 'kindness just gets you used.'","setup":"Push back gently but clearly. Say:","yourLine":[{"text":"\"Kindness actually builds the friendships and respect people want.\"","best":true},{"text":"\"Honestly, maybe he's got a point.\""},{"text":"\"You're pathetic for believing that.\""}],"relearn":"You can answer 'kindness gets you used' with what it really builds.","persona":"any","source":"the hook / respect"},
  {"id":"rh-1244","cat":"spot-the-hook","type":"role-play","hook":"A friend says 'she rejected me, so she owes me a real reason.'","setup":"Reframe it kindly, without piling on. Say:","yourLine":[{"text":"\"It stings, but no one owes us their interest, a no is enough.\"","best":true},{"text":"\"True, she should at least explain herself.\""},{"text":"\"Forget her, all girls are like that.\""}],"relearn":"You can reframe 'she owes me' to 'no one owes us their interest.'","persona":"Veer","source":"the hook / consent"},
  {"id":"rh-1245","cat":"spot-the-hook","type":"role-play","hook":"A creator's fan says 'he's the only one brave enough to tell the truth.'","setup":"Question the 'brave truth-teller' framing. Say:","yourLine":[{"text":"\"Saying cruel stuff loudly isn't brave. Shock is just how he gets views.\"","best":true},{"text":"\"Yeah, no one else says it like he does.\""},{"text":"\"You're a sheep for buying that.\""}],"relearn":"You can name 'brave truth-teller' as a costume for rage-bait.","persona":"any","source":"media literacy"},
  {"id":"rh-1246","cat":"spot-the-hook","type":"role-play","hook":"In the group chat someone says 'crying means you're not a real man.'","setup":"Take the shame out of it. Say:","yourLine":[{"text":"\"Everyone cries. It's a release, not a weakness.\"","best":true},{"text":"\"Yeah, you should probably hold it in.\""},{"text":"\"Grow up, only weaklings cry.\""}],"relearn":"You can answer 'crying isn't manly' with: it's a normal release.","persona":"Veer","source":"the hook / wellbeing"},
  {"id":"rh-1247","cat":"spot-the-hook","type":"role-play","hook":"A friend insists 'if loads of guys online believe it, it must be true.'","setup":"Bust the 'numbers = truth' idea. Say:","yourLine":[{"text":"\"A crowd agreeing online isn't proof, the feed served them all the same clip.\"","best":true},{"text":"\"Fair, that many guys can't all be wrong.\""},{"text":"\"You'll believe literally anything, huh.\""}],"relearn":"You can bust 'lots of guys believe it': that's reach, not proof.","persona":"any","source":"media literacy"},
  {"id":"rh-1248","cat":"spot-the-hook","type":"role-play","hook":"A friend says 'asking for help just proves you've failed as a man.'","setup":"Flip the shame, gently. Say:","yourLine":[{"text":"\"Asking for help is one of the strongest things you can do.\"","best":true},{"text":"\"Yeah, better to just tough it out alone.\""},{"text":"\"Only losers can't handle their own stuff.\""}],"relearn":"You can answer 'asking help is failing' with: it's real strength.","persona":"Counsellor","source":"the need underneath"},
  {"id":"rh-1260","cat":"the-funnel","type":"spot","hook":"Spot the two clips where 'looksmaxxing' becomes rating people.","scene":[{"id":"a","text":"A skincare and sleep routine","trick":false},{"id":"b","text":"\"Score your jawline out of 10\"","trick":true},{"id":"c","text":"A posture tip for back pain","trick":false},{"id":"d","text":"\"Most guys are 'low-value', cope\"","trick":true},{"id":"e","text":"A reminder to drink more water","trick":false}],"why":"The flagged clips slide from self-care into ranking people's worth.","relearn":"Self-care content gets funnelled into rating people; spot the swerve.","persona":"Veer","source":"the funnel / looksmaxxing"},
  {"id":"rh-1261","cat":"the-funnel","type":"spot","hook":"Spot the two lines where 'study with me' turns to blame.","scene":[{"id":"a","text":"A Pomodoro timer for revision","trick":false},{"id":"b","text":"\"The system is rigged for girls\"","trick":true},{"id":"c","text":"A note-making method for chemistry","trick":false},{"id":"d","text":"\"Stop simping, hate is fuel\"","trick":true},{"id":"e","text":"A tip on sleeping before an exam","trick":false}],"why":"The flagged lines turn study content into grievance and contempt.","relearn":"Even study content gets funnelled into blame; notice the swerve.","persona":"any","source":"the funnel"},
  {"id":"rh-1262","cat":"the-funnel","type":"spot","hook":"Spot the two clips where 'money mindset' becomes resentment.","scene":[{"id":"a","text":"A clip on a small side hustle","trick":false},{"id":"b","text":"\"Women only want your wallet\"","trick":true},{"id":"c","text":"A budgeting tip for pocket money","trick":false},{"id":"d","text":"\"You're a beta until you dominate her\"","trick":true},{"id":"e","text":"A reel on saving for a phone","trick":false}],"why":"The flagged clips swap money advice for contempt and us-vs-them.","relearn":"'Hustle' content gets funnelled into resentment; catch the swerve.","persona":"Veer","source":"the funnel"},
  {"id":"rh-1263","cat":"the-funnel","type":"spot","hook":"Spot the two signs the feed is steered toward outrage.","scene":[{"id":"a","text":"Every video now has a furious thumbnail","trick":true},{"id":"b","text":"You followed one fitness account","trick":false},{"id":"c","text":"The calm channels rarely show up now","trick":true},{"id":"d","text":"You watched one highlights reel once","trick":false},{"id":"e","text":"You searched 'pull-up tips' once","trick":false}],"why":"All-angry thumbnails and your calm channels vanishing mean it's being steered.","relearn":"When the feed fills with rage and calm stuff vanishes, it's being steered.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1264","cat":"the-funnel","type":"spot","hook":"Spot the two moments 'motivation' slides into us-vs-them.","scene":[{"id":"a","text":"\"Wake up early, train hard, read more\"","trick":false},{"id":"b","text":"\"Modern girls are why you fail\"","trick":true},{"id":"c","text":"\"Drink water, fix your sleep\"","trick":false},{"id":"d","text":"\"It's us against them, pick a side\"","trick":true},{"id":"e","text":"\"Small wins each day add up\"","trick":false}],"why":"The flagged lines bolt blame and a 'side' onto plain motivation.","relearn":"Motivation pages sneak in us-vs-them; spot 'show up' becoming 'pick a side'.","persona":"Veer","source":"the funnel"},
  {"id":"rh-1265","cat":"the-funnel","type":"spot","hook":"Spot the two clips built to keep you watching, not to help.","scene":[{"id":"a","text":"A clear two-minute breathing exercise","trick":false},{"id":"b","text":"\"PART 1 of 9: the truth THEY hide\"","trick":true},{"id":"c","text":"A short tip you can use today","trick":false},{"id":"d","text":"\"Comment 'awake' or stay a sheep\"","trick":true},{"id":"e","text":"A calm explainer, no cliffhanger","trick":false}],"why":"Endless 'parts' and bait comments hook your time, not help you.","relearn":"Cliffhangers and bait-comments are engagement traps, not help.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1266","cat":"the-funnel","type":"spot","hook":"Spot the two reasons the late-night feed hits hardest.","scene":[{"id":"a","text":"It's 1am, he can't sleep, scrolling alone","trick":true},{"id":"b","text":"He had a normal day at school","trick":false},{"id":"c","text":"He's feeling rejected after being left out","trick":true},{"id":"d","text":"He watched one cooking video at lunch","trick":false},{"id":"e","text":"He texts a friend goodnight","trick":false}],"why":"Late, alone and hurting is when the funnel's 'answers' feel most true.","relearn":"The funnel bites hardest when you're lonely and hurting; guard those moments.","persona":"Veer","source":"vulnerability"},
  {"id":"rh-1267","cat":"the-funnel","type":"spot","hook":"Spot the two clips dressing grievance as 'just facts'.","scene":[{"id":"a","text":"\"Here's a referenced study on sleep\"","trick":false},{"id":"b","text":"\"FACTS don't care about feelings: girls bad\"","trick":true},{"id":"c","text":"\"Source linked in the description\"","trick":false},{"id":"d","text":"\"It's just biology, accept your rank\"","trick":true},{"id":"e","text":"\"Read it and decide yourself\"","trick":false}],"why":"Calling contempt 'just facts' or 'just biology' is a costume, not evidence.","relearn":"'Just facts' / 'just biology' can dress up contempt; look underneath.","persona":"any","source":"the funnel / pseudo-science"},
  {"id":"rh-1268","cat":"the-funnel","type":"spot","hook":"Spot the two moves that widen the funnel over a week.","scene":[{"id":"a","text":"Watching a 'grindset' clip to the end","trick":true},{"id":"b","text":"Scrolling past it after two seconds","trick":false},{"id":"c","text":"Rewatching and sharing the angriest one","trick":true},{"id":"d","text":"Closing the app and going for a walk","trick":false},{"id":"e","text":"Reporting a clip that felt hateful","trick":false}],"why":"Full watches and shares teach the feed to bring more; scroll-pasts starve it.","relearn":"What you finish and share trains the feed; quick scroll-pasts starve it.","persona":"Veer","source":"algorithm / engagement"},
  {"id":"rh-1269","cat":"the-funnel","type":"spot","hook":"Spot the two lines where 'dating advice' becomes entitlement.","scene":[{"id":"a","text":"\"Be genuinely interested in people\"","trick":false},{"id":"b","text":"\"If she says no, she's testing you, push\"","trick":true},{"id":"c","text":"\"Have your own hobbies and friends\"","trick":false},{"id":"d","text":"\"You're owed attention, go take it\"","trick":true},{"id":"e","text":"\"Be honest about how you feel\"","trick":false}],"why":"'Push past a no' and 'you're owed attention' are entitlement, not advice.","relearn":"Dating reels smuggle in entitlement; spot respect flipping to 'you're owed'.","persona":"any","source":"the funnel"},
  {"id":"rh-1270","cat":"the-funnel","type":"spot","hook":"Spot the two signs the 'brotherhood' is a feed loop.","scene":[{"id":"a","text":"A group chat of real friends","trick":false},{"id":"b","text":"\"Only WE see the truth, others are sheep\"","trick":true},{"id":"c","text":"Mates who disagree with you sometimes","trick":false},{"id":"d","text":"\"Leave and you're weak and alone\"","trick":true},{"id":"e","text":"Friends who'd help if you were stuck","trick":false}],"why":"'Only we know' and 'leaving means weak' are funnel walls, not brotherhood.","relearn":"A real circle lets you leave and disagree; a funnel guilt-trips you.","persona":"Veer","source":"the funnel"},
  {"id":"rh-1271","cat":"the-funnel","type":"spot","hook":"Spot the two clips where 'discipline' adds contempt.","scene":[{"id":"a","text":"\"Make your bed, plan your day\"","trick":false},{"id":"b","text":"\"Soft people deserve to lose, mock them\"","trick":true},{"id":"c","text":"\"Train three times a week\"","trick":false},{"id":"d","text":"\"Look down on anyone who feels\"","trick":true},{"id":"e","text":"\"Keep promises to yourself\"","trick":false}],"why":"Discipline needs no contempt; the flagged lines bolt on cruelty.","relearn":"Real discipline needs no contempt; spot it adding 'mock the weak'.","persona":"any","source":"the funnel"},
  {"id":"rh-1272","cat":"the-funnel","type":"spot","hook":"Spot the two tricks making reach feel like truth.","scene":[{"id":"a","text":"\"10 million views can't be wrong\"","trick":true},{"id":"b","text":"A clip labelled as one person's opinion","trick":false},{"id":"c","text":"\"Everyone in your feed agrees, so true\"","trick":true},{"id":"d","text":"A creator who says 'I could be wrong'","trick":false},{"id":"e","text":"A video showing two sides","trick":false}],"why":"Views and an 'agreeing' feed are engineered reach, not proof.","relearn":"Big view counts and an agreeing feed are reach, not evidence.","persona":"any","source":"popularity vs truth"},
  {"id":"rh-1273","cat":"the-funnel","type":"spot","hook":"Spot the two 'edgy jokes' that are really the on-ramp.","scene":[{"id":"a","text":"A silly meme about exams","trick":false},{"id":"b","text":"A daily 'joke' that women are objects","trick":true},{"id":"c","text":"A harmless pun a friend shared","trick":false},{"id":"d","text":"'Ironic' clips that end on real contempt","trick":true},{"id":"e","text":"A funny clip of a cat","trick":false}],"why":"A daily 'joke' and 'ironic' contempt normalise the real thing.","relearn":"Repeated 'jokes' and 'ironic' contempt are the on-ramp, not harmless.","persona":"any","source":"normalisation"},
  {"id":"rh-1274","cat":"the-funnel","type":"spot","hook":"Spot the two moments a gaming feed is steered to grievance.","scene":[{"id":"a","text":"Clips of clutch plays and new maps","trick":false},{"id":"b","text":"\"Girls ruin every lobby\"","trick":true},{"id":"c","text":"A guide to a tricky boss fight","trick":false},{"id":"d","text":"\"Real gamers hate them, prove you're real\"","trick":true},{"id":"e","text":"A funny montage of fails","trick":false}],"why":"The flagged lines turn a gaming feed into us-vs-them and a loyalty test.","relearn":"Even a gaming feed gets steered to grievance; spot the swerve.","persona":"any","source":"the funnel"},
  {"id":"rh-1275","cat":"the-funnel","type":"spot","hook":"Spot the two clips turning a low feeling into blame.","scene":[{"id":"a","text":"\"Feeling left out is normal, here's help\"","trick":false},{"id":"b","text":"\"You feel low because girls rejected you\"","trick":true},{"id":"c","text":"\"Talk to someone you trust\"","trick":false},{"id":"d","text":"\"They did this to you, get angry\"","trick":true},{"id":"e","text":"\"Small steps, you're not alone\"","trick":false}],"why":"The flagged clips take a real feeling and hand you a scapegoat.","relearn":"The funnel turns a real low feeling into blame; the scapegoat is the trick.","persona":"Veer","source":"who it targets"},
  {"id":"rh-1276","cat":"the-funnel","type":"spot","hook":"Spot the two ways autoplay keeps the slide going.","scene":[{"id":"a","text":"The next video plays before you decide","trick":true},{"id":"b","text":"You tap each new video on purpose","trick":false},{"id":"c","text":"Each clip is a bit more extreme","trick":true},{"id":"d","text":"You set a timer and stop","trick":false},{"id":"e","text":"You pick what to watch from search","trick":false}],"why":"Autoplay and each clip nudging more extreme keep the slide going for you.","relearn":"Autoplay plus a steady step-up in extremity keeps the funnel sliding.","persona":"any","source":"the funnel / design"},
  {"id":"rh-1277","cat":"the-funnel","type":"spot","hook":"Spot the two lines where 'be a better man' becomes ranking.","scene":[{"id":"a","text":"\"Keep your word and back your friends\"","trick":false},{"id":"b","text":"\"Sort men into alpha and beta\"","trick":true},{"id":"c","text":"\"Learn a skill you're proud of\"","trick":false},{"id":"d","text":"\"Climb over the 'low-value' men\"","trick":true},{"id":"e","text":"\"Be someone your younger self admires\"","trick":false}],"why":"'Alpha/beta' and 'climbing over' others is fake ranking, not being better.","relearn":"'Be a better man' content sneaks in fake rankings; spot the swerve.","persona":"Veer","source":"the funnel / pseudo-science"},
  {"id":"rh-1278","cat":"the-funnel","type":"spot","hook":"Spot the two clips that punish you for stepping back.","scene":[{"id":"a","text":"\"Unfollow whatever doesn't help you\"","trick":false},{"id":"b","text":"\"Quit watching us and you'll stay a loser\"","trick":true},{"id":"c","text":"\"It's fine to take a break\"","trick":false},{"id":"d","text":"\"Doubting us means you're brainwashed\"","trick":true},{"id":"e","text":"\"Touch grass, log off, go outside\"","trick":false}],"why":"Threatening you for leaving or doubting is a funnel trap.","relearn":"If content punishes you for leaving or doubting, it's a funnel wall.","persona":"any","source":"the funnel"},
  {"id":"rh-1279","cat":"the-funnel","type":"spot","hook":"Spot the two signs a 'transformation' is an escalation.","scene":[{"id":"a","text":"\"Week 1: I started running and journaling\"","trick":false},{"id":"b","text":"\"By week 6 I cut off everyone 'soft'\"","trick":true},{"id":"c","text":"\"I learned to cook for myself\"","trick":false},{"id":"d","text":"\"Now I see the world as predators and prey\"","trick":true},{"id":"e","text":"\"I sleep better and feel calmer\"","trick":false}],"why":"Cutting people off and 'predators and prey' are escalation, not growth.","relearn":"A 'glow-up' that ends in cutting people off is escalation, not growth.","persona":"Veer","source":"the funnel"},
  {"id":"rh-1280","cat":"the-funnel","type":"spot","hook":"Spot the two clips where 'protect yourself' tips into paranoia.","scene":[{"id":"a","text":"\"Lock your accounts, use strong passwords\"","trick":false},{"id":"b","text":"\"Never trust a single girl\"","trick":true},{"id":"c","text":"\"Be careful what you share online\"","trick":false},{"id":"d","text":"\"Assume everyone's out to use you\"","trick":true},{"id":"e","text":"\"Think before you click a strange link\"","trick":false}],"why":"'Trust no one' and 'everyone's using you' are paranoia sold as 'protection'.","relearn":"Real safety advice never asks you to distrust everyone; spot the swerve.","persona":"any","source":"the funnel"},
  {"id":"rh-1281","cat":"the-funnel","type":"spot","hook":"Spot the two reasons the same clip keeps returning.","scene":[{"id":"a","text":"He paused on it once, so the feed noted it","trick":true},{"id":"b","text":"He skipped it instantly","trick":false},{"id":"c","text":"He watched a reaction, so it counts again","trick":true},{"id":"d","text":"He never searched anything like it","trick":false},{"id":"e","text":"He closed the app right after","trick":false}],"why":"A pause and watching a reaction both count as interest, so it returns.","relearn":"Even pausing or watching a reaction teaches the feed to serve it again.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1282","cat":"the-funnel","type":"spot","hook":"Spot the two lines where 'fix your confidence' turns toxic.","scene":[{"id":"a","text":"\"Practice small talk, it gets easier\"","trick":false},{"id":"b","text":"\"Confidence means making others small\"","trick":true},{"id":"c","text":"\"Stand tall, take up space\"","trick":false},{"id":"d","text":"\"Put people down so you look bigger\"","trick":true},{"id":"e","text":"\"Try one new thing each week\"","trick":false}],"why":"Real confidence never needs anyone smaller; the flagged lines are the fake version.","relearn":"Confidence that needs others to feel small is the funnel's fake version.","persona":"any","source":"the funnel"},
  {"id":"rh-1336","cat":"the-funnel","type":"branch","hook":"You searched 'how to talk to a girl' and the feed soon serves 'why girls are the problem'.","options":[{"text":"Spot the swerve and search for what you actually wanted","consequence":"You steer back to your real question.","outcome":"out","best":true},{"text":"Watch on, the feed clearly knows you","consequence":"It pivoted your question to grievance; steer back."}],"debrief":"The funnel answers a real question with blame; return to the question.","relearn":"When the feed swaps your question for grievance, steer back.","persona":"Veer","source":"the funnel"},
  {"id":"rh-1283","cat":"the-funnel","type":"branch","hook":"You notice every reel today is angrier than yesterday's.","options":[{"text":"Name it: 'the feed's escalating' and refresh your follows","consequence":"You see the slope and step off.","outcome":"out","best":true},{"text":"Assume the world just got worse overnight","consequence":"It's the feed escalating; name it and reset."}],"debrief":"A feed getting steadily angrier is the funnel, not reality.","relearn":"If each day's feed is angrier, that's the funnel escalating, not the world.","persona":"any","source":"the funnel / design"},
  {"id":"rh-1284","cat":"the-funnel","type":"branch","hook":"A reel tells you to 'comment AWAKE' to prove you see the truth.","options":[{"text":"Skip it, that's engagement bait, not a truth test","consequence":"You don't feed it the reaction it wants.","outcome":"clear","best":true},{"text":"Comment, you don't want to be a 'sheep'","consequence":"It's bait to boost the clip; skipping starves it."}],"debrief":"'Comment to prove you're awake' is engagement bait, not a loyalty test.","relearn":"'Comment to prove you're awake' is bait, not a real test.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1285","cat":"the-funnel","type":"branch","hook":"You feel a rush of relief: 'so none of it is my fault'.","options":[{"text":"Notice the relief is the hook, sit with the real feeling","consequence":"You catch the manipulation as it happens.","outcome":"aware","best":true},{"text":"Chase that relief, watch ten more","consequence":"That relief is the bait; noticing it resists it."}],"debrief":"The funnel sells the relief of blame; spotting the rush defuses it.","relearn":"The 'none of it's my fault' rush is the hook; notice it and pause.","persona":"Veer","source":"emotional manipulation"},
  {"id":"rh-1286","cat":"the-funnel","type":"branch","hook":"A friend shows you a creator: 'just watch one, you'll get hooked'.","options":[{"text":"Ask what he keeps selling before you binge","consequence":"You stay curious and in control.","outcome":"clear","best":true},{"text":"Binge the whole playlist that night","consequence":"'You'll get hooked' is the point; ask what's sold first."}],"debrief":"'You'll get hooked' is a warning, not a recommendation.","relearn":"When something's built to hook you, ask what it sells first.","persona":"any","source":"the funnel"},
  {"id":"rh-1287","cat":"the-funnel","type":"branch","hook":"After a rough day, the angry 'truth' clips feel extra convincing.","options":[{"text":"Notice you're low, not the best moment to judge this","consequence":"You guard a vulnerable moment.","outcome":"aware","best":true},{"text":"Decide it's all true, it really feels true now","consequence":"The funnel bites when you're low; wait to judge."}],"debrief":"Low moments make the funnel feel truest; wait before deciding.","relearn":"When you're low, the funnel feels truest; pause, don't decide.","persona":"Veer","source":"vulnerability"},
  {"id":"rh-1288","cat":"the-funnel","type":"branch","hook":"A 'history' channel you like keeps slipping into 'men are under attack' takes.","options":[{"text":"Unfollow and find creators who stay on the topic","consequence":"You keep what you liked, drop the grievance.","outcome":"out","best":true},{"text":"Keep watching, the history bits are good","consequence":"The grievance is the funnel riding your topic; swap."}],"debrief":"A funnel hides behind a topic you like; keep the topic, drop the funnel.","relearn":"Keep the topic you like; drop the creator that adds grievance.","persona":"any","source":"the funnel"},
  {"id":"rh-1289","cat":"the-funnel","type":"branch","hook":"A clip insists 'you chose to watch this, so deep down you agree'.","options":[{"text":"Remember the feed served it; watching isn't agreeing","consequence":"You separate what you were fed from what you believe.","outcome":"clear","best":true},{"text":"Accept that watching it means you believe it","consequence":"The feed served it; watching isn't choosing to believe."}],"debrief":"'You watched it so you believe it' ignores that the feed chose it.","relearn":"Being served content isn't choosing to believe it.","persona":"Veer","source":"no shame / algorithm"},
  {"id":"rh-1290","cat":"the-funnel","type":"branch","hook":"You find a 'reset': a feed full of cooking, football and music you enjoy.","options":[{"text":"Like and follow those for a week to retrain the feed","consequence":"You teach the algorithm what you want more of.","outcome":"out","best":true},{"text":"Wait and hope the angry stuff fades","consequence":"The feed learns from what you engage with; feed it good stuff."}],"debrief":"You retrain a feed by engaging with what you actually want.","relearn":"Engaging with what you enjoy retrains the feed faster than waiting.","persona":"any","source":"stepping out"},
  {"id":"rh-1291","cat":"the-funnel","type":"branch","hook":"A reel claims 'millions of guys watch this, so it must be right'.","options":[{"text":"Note a funnel pushing one thing to millions isn't proof","consequence":"You separate engineered reach from truth.","outcome":"clear","best":true},{"text":"Figure that many views settles it","consequence":"Engineered reach isn't evidence; views don't make it true."}],"debrief":"A funnel can push one clip to millions; that's reach, not truth.","relearn":"Millions of views is engineered reach, not proof of truth.","persona":"any","source":"popularity vs truth"},
  {"id":"rh-1292","cat":"the-funnel","type":"branch","hook":"You feel embarrassed you ever believed some of it, and want to quit in shame.","options":[{"text":"Skip the shame, just clean up your follows","consequence":"You step out without punishing yourself.","outcome":"kind","best":true},{"text":"Spiral into 'I'm an idiot' and give up","consequence":"It was designed to convince you; no shame, just reset."}],"debrief":"Self-blame isn't fair; the content was engineered to convince you.","relearn":"You needn't feel shame for being targeted; just step out and reset.","persona":"Veer","source":"no shame"},
  {"id":"rh-1293","cat":"the-funnel","type":"branch","hook":"A creator promises 'the full truth' after you watch nine more parts.","options":[{"text":"See the cliffhanger as an engagement trap and bail","consequence":"You spot the hook holding 'truth' hostage.","outcome":"clear","best":true},{"text":"Watch all nine, the payoff must be worth it","consequence":"The endless 'parts' are a trap; real answers don't stall."}],"debrief":"Dangling 'the truth' across nine parts is a trap, not honesty.","relearn":"When 'the truth' is always one more part away, it's a trap.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1294","cat":"the-funnel","type":"branch","hook":"Your younger cousin starts quoting the angry clips you used to watch.","options":[{"text":"Calmly explain how the funnel works, no shame on him","consequence":"You hand him the map out.","outcome":"out","best":true},{"text":"Laugh at him for falling for it","consequence":"He was funnelled too; explaining without shame reaches him."}],"debrief":"Mocking pushes someone deeper; explaining without shame helps them out.","relearn":"Explaining the funnel without shame helps someone step out.","persona":"any","source":"no shame / stepping out"},
  {"id":"rh-1333","cat":"the-funnel","type":"branch","hook":"A pop-up asks if you want to 'see fewer videos like this'.","options":[{"text":"Tap 'fewer like this', it's a real lever","consequence":"You tell the algorithm to back off that lane.","outcome":"out","best":true},{"text":"Ignore it, the feed will sort itself out","consequence":"That button works; using it steers the funnel away."}],"debrief":"Feed controls like 'show fewer' really work; use them to step out.","relearn":"'Show fewer like this' is a real lever that steers the funnel away.","persona":"any","source":"stepping out / design"},
  {"id":"rh-1337","cat":"the-funnel","type":"branch","hook":"A clip says doubting it proves you've been 'brainwashed by the other side'.","options":[{"text":"See that as a trap that punishes questions, and keep asking","consequence":"You hold your own judgement.","outcome":"clear","best":true},{"text":"Stop doubting so you don't look 'brainwashed'","consequence":"Punishing questions is a trap; good ideas survive doubt."}],"debrief":"'Doubting proves you're brainwashed' is built to shut down questions.","relearn":"When doubting is called proof you're wrong, keep asking.","persona":"any","source":"the funnel"},
  {"id":"rh-1295","cat":"the-funnel","type":"strike-rewrite","hook":"\"My feed reflects exactly who I am.\"","myth":{"un":"My feed is a mirror of who I really am inside.","re":"A feed is shaped by what keeps you watching, not your values.","why":"Recommendation systems optimise for watch time, not for you."},"relearn":"Your feed reflects what holds your attention, not who you are.","persona":"any","source":"algorithm / design"},
  {"id":"rh-1296","cat":"the-funnel","type":"strike-rewrite","hook":"\"If I disagreed with it, it wouldn't get to me.\"","myth":{"un":"If this were wrong for me, the feed wouldn't show it.","re":"The feed shows what keeps you watching, even what upsets you.","why":"Engagement, not agreement, decides what you're served."},"relearn":"A feed serves what holds your attention, not only what's right.","persona":"Veer","source":"algorithm / engagement"},
  {"id":"rh-1297","cat":"the-funnel","type":"strike-rewrite","hook":"\"It escalated, so it's closer to the truth.\"","myth":{"un":"The content got more extreme, so it must be truer.","re":"It got extreme because extreme keeps you watching, not truer.","why":"Algorithms escalate toward outrage to hold attention."},"relearn":"More extreme means more engaging, not more true.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1298","cat":"the-funnel","type":"strike-rewrite","hook":"\"Everyone in my feed agrees, so it's settled.\"","myth":{"un":"Everyone the feed shows me agrees, so it's settled.","re":"The feed gathers people who agree; it's an echo, not consensus.","why":"Recommendation loops cluster similar content and hide the rest."},"relearn":"A feed where everyone agrees is an echo, not real agreement.","persona":"any","source":"the funnel / echo"},
  {"id":"rh-1299","cat":"the-funnel","type":"strike-rewrite","hook":"\"I'm too deep in to ever step out.\"","myth":{"un":"I've watched too much of this to ever step out now.","re":"You can step out any time; resetting follows works at once.","why":"Feeds adjust quickly to new signals you give them."},"relearn":"It's never too late to step out; resetting works right away.","persona":"Veer","source":"stepping out / no shame"},
  {"id":"rh-1300","cat":"the-funnel","type":"strike-rewrite","hook":"\"The angriest creators are the most honest.\"","myth":{"un":"The angriest, most extreme creators are the most honest.","re":"Anger gets boosted because it spreads, not because it's honest.","why":"Outrage travels further, so it gets amplified."},"relearn":"Anger gets amplified because it spreads, not because it's honest.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1301","cat":"the-funnel","type":"strike-rewrite","hook":"\"If I avoid the worst videos, the funnel can't reach me.\"","myth":{"un":"As long as I skip the bad videos, the funnel won't affect me.","re":"It works gradually through mild content too; noticing the slide matters most.","why":"Escalation is step-by-step, so the mild early steps let it in."},"relearn":"The funnel works through mild content; noticing the slide beats dodging one clip.","persona":"any","source":"the funnel / normalisation"},
  {"id":"rh-1302","cat":"the-funnel","type":"strike-rewrite","hook":"\"Watching this just informs me, it doesn't influence me.\"","myth":{"un":"I only watch this to stay informed; it doesn't change me.","re":"Repeated exposure shifts what feels normal, even when you just watch.","why":"Steady repetition normalises ideas whether you mean to or not."},"relearn":"Repeated exposure shifts what feels normal, even if you're just watching.","persona":"Veer","source":"normalisation"},
  {"id":"rh-1303","cat":"the-funnel","type":"reflect","hook":"Lensy: noticing the slide, 'this is escalating', is a skill you can build. Worth practising?","prompt":"What do you think?","options":["Yes","I can try","I want to get better"],"affirm":"Catching the slide early is the skill that keeps you free.","relearn":"Noticing the funnel escalating is a skill you can practise.","persona":"any","source":"media literacy"},
  {"id":"rh-1304","cat":"the-funnel","type":"reflect","hook":"Lensy: a designed feed did the steering, not some flaw in you. Sit with that?","prompt":"How does that land?","options":["It's a relief","Makes sense","I needed that"],"affirm":"The feed was built to steer; that's on the design, not on you.","relearn":"A designed feed did the steering; being funnelled was never a flaw in you.","persona":"Veer","source":"no shame / design"},
  {"id":"rh-1305","cat":"the-funnel","type":"reflect","hook":"Lensy: you decide what your feed feeds you, more than it admits. Notice that?","prompt":"What comes up?","options":["Yes","More control than I thought","Good reminder"],"affirm":"What you follow and finish trains the feed; that power is yours.","relearn":"You shape your feed more than it pretends; what you engage with trains it.","persona":"any","source":"agency / stepping out"},
  {"id":"rh-1306","cat":"the-funnel","type":"reflect","hook":"Lensy: the wish to belong the funnel uses, that part of you is good. Fair?","prompt":"What do you think?","options":["Fair","Yes","That helps"],"affirm":"Wanting to belong is human; the funnel just abuses something good.","relearn":"The wish to belong is healthy; only the funnel's use of it isn't.","persona":"Veer","source":"vulnerability / compassion"},
  {"id":"rh-1307","cat":"the-funnel","type":"reflect","hook":"Lensy: once you name the machinery, an angry clip feels more like a sales pitch. Notice that?","prompt":"How does it feel now?","options":["Yes","Less gripping","I can see through it"],"affirm":"Seeing the strings turns the spell back into just a clip.","relearn":"Naming the machinery turns a gripping clip back into just a pitch.","persona":"any","source":"media literacy"},
  {"id":"rh-1308","cat":"the-funnel","type":"reflect","hook":"Lensy: stepping back from a feed is a strong move, not a defeat. Sit right?","prompt":"What do you think?","options":["Yes","It is strong","I'll remember that"],"affirm":"Choosing what not to watch is one of the strongest moves there is.","relearn":"Stepping back from a feed is a strong, deliberate move, not a defeat.","persona":"any","source":"agency"},
  {"id":"rh-1309","cat":"the-funnel","type":"reflect","hook":"Lensy: the curiosity that pulled you toward 'self-improvement' is a good instinct. Keep it?","prompt":"What comes up?","options":["Yes","I want to keep that","Good point"],"affirm":"That drive to grow is real; point it somewhere that lifts you.","relearn":"The drive to improve the funnel hijacks is a good instinct worth keeping.","persona":"Veer","source":"compassion / real strength"},
  {"id":"rh-1310","cat":"the-funnel","type":"reflect","hook":"Lensy: you can be curious online without a feed deciding for you. Sound right?","prompt":"What do you think?","options":["Yes","I like that","Makes sense"],"affirm":"Curiosity plus a hand on the wheel is how you stay free online.","relearn":"Stay curious online while keeping your hand on the wheel of your feed.","persona":"any","source":"media literacy / agency"},
  {"id":"rh-1311","cat":"the-funnel","type":"match","hook":"Match each funnel step to what it's really doing.","pairs":[{"left":"Fitness and study tips","right":"Relatable bait to get you in"},{"left":"Edgier 'truth' clips","right":"First step of escalation"},{"left":"'Girls are the problem'","right":"Grievance, the real payload"},{"left":"Full contempt, us-vs-them","right":"The bottom of the funnel"},{"left":"Naming it, resetting your feed","right":"The exit out"}],"relearn":"The funnel runs bait, escalation, grievance, contempt; naming it exits.","persona":"any","source":"the funnel"},
  {"id":"rh-1312","cat":"the-funnel","type":"match","hook":"Match each feed trick to how it keeps you watching.","pairs":[{"left":"Autoplay","right":"Starts the next clip for you"},{"left":"Outrage thumbnails","right":"Spike attention to boost the clip"},{"left":"'Part 1 of 9'","right":"Holds the point hostage"},{"left":"'Comment if you're awake'","right":"Farms reactions to spread it"},{"left":"'More like this'","right":"Deepens the loop you're in"}],"relearn":"Autoplay, rage thumbnails, cliffhangers and bait keep you watching.","persona":"any","source":"algorithm / engagement"},
  {"id":"rh-1313","cat":"the-funnel","type":"match","hook":"Match each feeling the funnel targets to its bait.","pairs":[{"left":"Loneliness","right":"A fake 'brotherhood' to join"},{"left":"Rejection","right":"Someone to blame for it"},{"left":"Feeling unsure","right":"A rigid 'high-value' script"},{"left":"Boredom","right":"Endless outrage to scroll"},{"left":"Wanting to grow","right":"A hijacked 'self-improvement' path"}],"relearn":"The funnel matches each need with a bait: belonging, blame, a script.","persona":"Counsellor","source":"who it targets"},
  {"id":"rh-1314","cat":"the-funnel","type":"match","hook":"Match each move to whether it steps you out or deeper in.","pairs":[{"left":"Naming the escalation aloud","right":"Steps you out"},{"left":"Liking the angriest clips","right":"Pulls you deeper in"},{"left":"Following calm, varied creators","right":"Steps you further out"},{"left":"Watching every 'part'","right":"Pulls you deeper, again"},{"left":"Turning off autoplay","right":"Steps you cleanly out"}],"relearn":"Naming, varying and muting step you out; liking and finishing rage pull you in.","persona":"any","source":"stepping out"},
  {"id":"rh-1315","cat":"the-funnel","type":"match","hook":"Match each 'proof' the funnel offers to what it is.","pairs":[{"left":"'10 million views'","right":"Engineered reach, not truth"},{"left":"'Everyone agrees'","right":"An echo chamber"},{"left":"'More extreme, so truer'","right":"Outrage optimisation"},{"left":"'I sought it out'","right":"The algorithm served it"},{"left":"'It's just biology'","right":"Pseudo-science costume"}],"relearn":"Views, an agreeing feed, extremity and 'biology' are reach and tricks.","persona":"any","source":"popularity vs truth"},
  {"id":"rh-1316","cat":"the-funnel","type":"match","hook":"Match each early funnel sign to its quiet exit.","pairs":[{"left":"Feed all about one 'enemy'","right":"Unfollow and diversify"},{"left":"Each clip a bit angrier","right":"Name 'this is escalating'"},{"left":"Autoplay carrying you","right":"Turn autoplay off"},{"left":"Watching most at lonely hours","right":"Guard that time, text a friend"},{"left":"A rush of 'all their fault'","right":"Pause and notice the hook"}],"relearn":"Each early sign of the funnel has a small exit you can take.","persona":"any","source":"stepping out"},
  {"id":"rh-1317","cat":"the-funnel","type":"match","hook":"Match each 'self-improvement' hook to its hidden contempt.","pairs":[{"left":"'Become high-value'","right":"Rank people's worth"},{"left":"'Stop being soft'","right":"Mock anyone who feels"},{"left":"'Protect your energy'","right":"Distrust everyone"},{"left":"'Know your worth'","right":"Decide others are beneath you"},{"left":"'Wake up to the truth'","right":"Treat outsiders as sheep"}],"relearn":"The funnel hides contempt inside healthy-sounding phrases.","persona":"Veer","source":"the funnel / normalisation"},
  {"id":"rh-1334","cat":"the-funnel","type":"match","hook":"Match each funnel claim to the question that pops it.","pairs":[{"left":"'I sought this out'","right":"Did I choose it, or was it served?"},{"left":"'Millions of views'","right":"Does reach make it true?"},{"left":"'The angriest is realest'","right":"Is anger honesty or engagement?"},{"left":"'Everyone agrees'","right":"Consensus, or an echo?"},{"left":"'It keeps escalating'","right":"Extreme, or just stickier?"}],"relearn":"Each funnel claim has a simple question that pops it.","persona":"any","source":"media literacy"},
  {"id":"rh-1318","cat":"the-funnel","type":"sort","hook":"Sort each line: relatable bait at the top, or contempt at the bottom.","items":[{"id":"i1","text":"\"A simple workout to start with\""},{"id":"i2","text":"\"Study tips before exams\""},{"id":"i3","text":"\"Women are why life is hard\""},{"id":"i4","text":"\"A pocket-money budgeting tip\""},{"id":"i5","text":"\"They deserve no respect\""},{"id":"i6","text":"\"Us versus them, pick a side\""}],"bins":[{"id":"bait","label":"Bait (top)","valence":"neutral"},{"id":"contempt","label":"Contempt","valence":"neg"}],"key":{"i1":"bait","i2":"bait","i3":"contempt","i4":"bait","i5":"contempt","i6":"contempt"},"relearn":"The funnel runs from relatable bait to contempt at the bottom.","persona":"any","source":"the funnel"},
  {"id":"rh-1319","cat":"the-funnel","type":"sort","hook":"Sort each move: steps you out, or feeds the funnel.","items":[{"id":"i1","text":"Naming it 'a funnel'"},{"id":"i2","text":"Liking every angry clip"},{"id":"i3","text":"Following calm creators"},{"id":"i4","text":"Watching all nine 'parts'"},{"id":"i5","text":"Turning autoplay off"},{"id":"i6","text":"Sharing the most outrageous reel"}],"bins":[{"id":"out","label":"Steps out","valence":"pos"},{"id":"feed","label":"Feeds it","valence":"neg"}],"key":{"i1":"out","i2":"feed","i3":"out","i4":"feed","i5":"out","i6":"feed"},"relearn":"Naming, varying and muting step you out; liking and sharing feed it.","persona":"any","source":"stepping out"},
  {"id":"rh-1320","cat":"the-funnel","type":"sort","hook":"Sort each claim: engineered reach, or actual evidence.","items":[{"id":"i1","text":"\"It has 10 million views\""},{"id":"i2","text":"\"A study with its method is linked\""},{"id":"i3","text":"\"Everyone in my feed agrees\""},{"id":"i4","text":"\"Check the original source\""},{"id":"i5","text":"\"It trended, so it's true\""},{"id":"i6","text":"\"Two experts disagree, both shown\""}],"bins":[{"id":"reach","label":"Reach","valence":"neg"},{"id":"evidence","label":"Evidence","valence":"pos"}],"key":{"i1":"reach","i2":"evidence","i3":"reach","i4":"evidence","i5":"reach","i6":"evidence"},"relearn":"Views, an agreeing feed and trending are reach; checkable sources are evidence.","persona":"any","source":"popularity vs truth"},
  {"id":"rh-1321","cat":"the-funnel","type":"sort","hook":"Sort each clip: a real healthy tip, or bait in a costume.","items":[{"id":"i1","text":"\"Drink water, fix your sleep\""},{"id":"i2","text":"\"Become high-value so they obey\""},{"id":"i3","text":"\"Learn a skill you enjoy\""},{"id":"i4","text":"\"Cut off everyone 'soft'\""},{"id":"i5","text":"\"Take a walk when stressed\""},{"id":"i6","text":"\"Real men dominate, never feel\""}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"costume","label":"In costume","valence":"neg"}],"key":{"i1":"healthy","i2":"costume","i3":"healthy","i4":"costume","i5":"healthy","i6":"costume"},"relearn":"Some 'self-improvement' is real; some is contempt in a healthy costume.","persona":"Veer","source":"the funnel / normalisation"},
  {"id":"rh-1322","cat":"the-funnel","type":"sort","hook":"Sort each moment: funnel bites hardest, or you're guarded.","items":[{"id":"i1","text":"Alone at 2am, can't sleep"},{"id":"i2","text":"Just after being left out"},{"id":"i3","text":"Hanging out with real friends"},{"id":"i4","text":"Bored, scrolling for hours"},{"id":"i5","text":"Busy with a hobby you love"},{"id":"i6","text":"Resting after time with family"}],"bins":[{"id":"risky","label":"Bites hardest","valence":"uhoh"},{"id":"guarded","label":"Guarded","valence":"pos"}],"key":{"i1":"risky","i2":"risky","i3":"guarded","i4":"risky","i5":"guarded","i6":"guarded"},"relearn":"The funnel bites in lonely, hurting, bored hours; connection guards you.","persona":"any","source":"vulnerability"},
  {"id":"rh-1323","cat":"the-funnel","type":"sort","hook":"Sort each line: names the funnel, or hands you a scapegoat.","items":[{"id":"i1","text":"\"This feed is escalating on purpose\""},{"id":"i2","text":"\"Women are why you're miserable\""},{"id":"i3","text":"\"Outrage is being sold to me\""},{"id":"i4","text":"\"They ruined everything for guys\""},{"id":"i5","text":"\"The algorithm chose this for me\""},{"id":"i6","text":"\"It's all their fault, get angry\""}],"bins":[{"id":"names","label":"Names it","valence":"tell"},{"id":"scapegoat","label":"Scapegoat","valence":"neg"}],"key":{"i1":"names","i2":"scapegoat","i3":"names","i4":"scapegoat","i5":"names","i6":"scapegoat"},"relearn":"Naming the funnel frees you; being handed a scapegoat is the bait.","persona":"any","source":"the funnel / emotional manipulation"},
  {"id":"rh-1324","cat":"the-funnel","type":"sort","hook":"Sort each feature: carries you along, or hands control back.","items":[{"id":"i1","text":"Autoplay starting the next clip"},{"id":"i2","text":"A 'why am I seeing this?' button"},{"id":"i3","text":"Infinite scroll with no end"},{"id":"i4","text":"A 'not interested' option"},{"id":"i5","text":"Cliffhanger 'part 1 of 9'"},{"id":"i6","text":"A screen-time limit you set"}],"bins":[{"id":"carries","label":"Carries you","valence":"uhoh"},{"id":"control","label":"You control","valence":"pos"}],"key":{"i1":"carries","i2":"control","i3":"carries","i4":"control","i5":"carries","i6":"control"},"relearn":"Autoplay and infinite scroll carry you; 'not interested' and limits give control.","persona":"any","source":"the funnel / design"},
  {"id":"rh-1335","cat":"the-funnel","type":"sort","hook":"Sort each clip: the on-ramp, or the grievance core.","items":[{"id":"i1","text":"\"A morning routine to feel in control\""},{"id":"i2","text":"\"How to start lifting safely\""},{"id":"i3","text":"\"Feminism is your real enemy\""},{"id":"i4","text":"\"Save your first 1000 rupees\""},{"id":"i5","text":"\"They want you weak, fight back\""},{"id":"i6","text":"\"You're a victim, someone's to blame\""}],"bins":[{"id":"onramp","label":"On-ramp","valence":"neutral"},{"id":"core","label":"Grievance core","valence":"neg"}],"key":{"i1":"onramp","i2":"onramp","i3":"core","i4":"onramp","i5":"core","i6":"core"},"relearn":"The funnel's on-ramp is relatable; its core is grievance and blame.","persona":"any","source":"the funnel"},
  {"id":"rh-1325","cat":"the-funnel","type":"role-play","hook":"A friend says, 'You watch that angry-guy content too, right? Everyone does.'","setup":"You used to, and you've started seeing the funnel. Say it without shame.","yourLine":[{"text":"\"I did, then I noticed it kept escalating, so I reset it.\"","best":true},{"text":"\"Yeah, whatever, it's just videos.\""}],"relearn":"You can name stepping out plainly, with no shame on you or your friend.","persona":"Veer","source":"stepping out / no shame"},
  {"id":"rh-1326","cat":"the-funnel","type":"role-play","hook":"Your cousin says, 'This creator finally explained why life feels unfair to guys.'","setup":"You want to plant a doubt without putting him down.","yourLine":[{"text":"\"What's he actually selling? Notice how it always escalates.\"","best":true},{"text":"\"You're so dumb for believing him.\""}],"relearn":"A curious question reaches further than mocking someone.","persona":"any","source":"have each other's backs / the funnel"},
  {"id":"rh-1327","cat":"the-funnel","type":"role-play","hook":"Someone says, 'The algorithm just shows the truth, that's why it's all the same.'","setup":"You want to name the echo chamber calmly, for the room.","yourLine":[{"text":"\"It shows what keeps you watching, so it all agreeing is an echo.\"","best":true},{"text":"\"I dunno, maybe it is all true then.\""}],"relearn":"A feed that all agrees is an echo chamber, and you can say so.","persona":"Riya","source":"the funnel / echo"},
  {"id":"rh-1328","cat":"the-funnel","type":"role-play","hook":"A friend admits, 'I watch this most at night when I feel rubbish.'","setup":"You want to meet the feeling and name the funnel's timing.","yourLine":[{"text":"\"Makes sense, it hits hardest when we're low. Do something else then?\"","best":true},{"text":"\"You should just have more willpower.\""}],"relearn":"Meeting the low feeling helps more than 'just willpower'.","persona":"Veer","source":"vulnerability / have each other's backs"},
  {"id":"rh-1329","cat":"the-funnel","type":"role-play","hook":"Someone insists, 'If you watched it, you secretly agree with it.'","setup":"You want to push back without taking the bait.","yourLine":[{"text":"\"The feed served it to me. Watching isn't choosing to believe it.\"","best":true},{"text":"\"Maybe you're right, maybe I do agree.\""}],"relearn":"Being served content isn't the same as believing it, and you can say so.","persona":"any","source":"no shame / algorithm"},
  {"id":"rh-1330","cat":"the-funnel","type":"role-play","hook":"A younger student asks you, 'How do I make my feed less angry?'","setup":"You want to give one clear, doable step.","yourLine":[{"text":"\"Unfollow the angry accounts and like calm stuff, it retrains fast.\"","best":true},{"text":"\"You can't really, the algorithm does what it wants.\""}],"relearn":"Unfollowing rage and engaging with calm content retrains a feed fast.","persona":"any","source":"stepping out"},
  {"id":"rh-1331","cat":"the-funnel","type":"role-play","hook":"A mate brags, 'I'm immune, this can't change me, I watch for laughs.'","setup":"You want to name how mild repetition still works, no lecture.","yourLine":[{"text":"\"Even 'just laughs' on repeat shifts what feels normal, that's the trick.\"","best":true},{"text":"\"Yeah, you're too smart for it.\""}],"relearn":"Repeated 'just for laughs' content still shifts what feels normal.","persona":"any","source":"normalisation"},
  {"id":"rh-1332","cat":"the-funnel","type":"role-play","hook":"Your brother says, 'I feel stupid for ever buying into that stuff.'","setup":"You want to take the shame off him while backing his step.","yourLine":[{"text":"\"It was built to convince you, no shame. Reset your feed, you're out.\"","best":true},{"text":"\"Yeah, that was pretty stupid of you.\""}],"relearn":"You can drop the shame and back someone's step out of the funnel.","persona":"Veer","source":"no shame"},
  {"id":"rh-1350","cat":"the-need-underneath","type":"reflect","hook":"Lensy: when a feed makes you feel small, what's one real thing that steadies you?","prompt":"Pick what fits.","options":["A walk outside","Texting a mate","Music I love","Calling family"],"affirm":"That's a real anchor, no subscription, no grift, just yours.","relearn":"Real, free things steady you better than anything the feed sells.","persona":"any","source":"wellbeing / belonging"},
  {"id":"rh-1351","cat":"the-need-underneath","type":"reflect","hook":"Lensy: it's late, you feel low, and the autoplay keeps rolling. What could you try instead?","prompt":"Choose one.","options":["Put the phone down","Message someone","Sleep on it","Note how I feel"],"affirm":"Any of those is a kinder move than letting the feed mine your low moment.","relearn":"Lonely, late moments are when to step away, not scroll deeper.","persona":"Veer","source":"guarding low moments"},
  {"id":"rh-1352","cat":"the-need-underneath","type":"reflect","hook":"Lensy: 'asking for help' can feel huge. What's the smallest first step you'd actually take?","prompt":"Pick a starting point.","options":["Tell one friend","Text a cousin","Talk to a teacher","Call Tele-MANAS 14416"],"affirm":"Small is fine, one honest sentence to one person is already strength.","relearn":"Reaching out can start tiny, one person, one line, Tele-MANAS 14416 is there too.","persona":"any","source":"Tele-MANAS (verified)"},
  {"id":"rh-1353","cat":"the-need-underneath","type":"reflect","hook":"Lensy: who's someone who'd pick up if you called at a rough hour, no judgement?","prompt":"Name one to yourself.","options":["A close friend","An older sibling","A relative","A coach or teacher"],"affirm":"Knowing that name before you need it is quiet power.","relearn":"Knowing one trusted person you can reach beats any online 'brotherhood'.","persona":"any","source":"trusted adult / connection"},
  {"id":"rh-1354","cat":"the-need-underneath","type":"reflect","hook":"Lensy: the feed says you're 'not enough'. Sit a second, what's actually true about you?","prompt":"Finish it your way.","options":["I'm still learning","I help my friends","I keep trying","I'm enough as I am"],"affirm":"All true, and none of it needs a course to unlock.","relearn":"You're already enough and you can still grow, both true at once.","persona":"Veer","source":"self-worth"},
  {"id":"rh-1355","cat":"the-need-underneath","type":"reflect","hook":"Lensy: loneliness is a signal, like hunger. What is it asking you to do?","prompt":"What do you reckon?","options":["Reach out","Connect","Reconnect with someone","Not hide it"],"affirm":"Exactly, it's a nudge toward people, not proof anything's wrong with you.","relearn":"Loneliness is a normal cue to connect, not a defect in you.","persona":"any","source":"wellbeing"},
  {"id":"rh-1356","cat":"the-need-underneath","type":"reflect","hook":"Lensy: after a hard day, the angry clips feel oddly soothing. What might they actually be feeding?","prompt":"Be honest with yourself.","options":["A need to belong","Wanting respect","Feeling unseen","Just being tired"],"affirm":"The need is real and okay, only the 'blame them' answer it sells isn't.","relearn":"The need under the rage is real; the hateful 'answer' sold for it isn't.","persona":"Veer","source":"the need underneath"},
  {"id":"rh-1357","cat":"the-need-underneath","type":"reflect","hook":"Lensy: if a younger cousin felt this low, what would you tell him to do?","prompt":"Pick your advice.","options":["Talk to someone","You're not alone","Ask for help","It gets better"],"affirm":"Now offer yourself the same kindness, you'd deserve it too.","relearn":"The kind advice you'd give a friend is the advice you deserve yourself.","persona":"any","source":"self-compassion"},
  {"id":"rh-1358","cat":"the-need-underneath","type":"reflect","hook":"Lensy: what's one place, offline, where people are actually glad you showed up?","prompt":"Picture it.","options":["A sports ground","A study group","Family meals","A friend's place"],"affirm":"That belonging is real and yours, no 'high-value' badge required.","relearn":"Real belonging shows up in places that are glad you came, free of charge.","persona":"any","source":"belonging"},
  {"id":"rh-1359","cat":"the-need-underneath","type":"reflect","hook":"Lensy: getting nasty replies online stings. What's one way you protect your own head?","prompt":"Pick a guard.","options":["Mute and step back","Tell a friend","Save proof, report","Touch grass"],"affirm":"Each one keeps your worth in your hands, not a stranger's comment box.","relearn":"Your worth isn't a troll's to set; protect your head and report abuse.","persona":"Riya","source":"refuse to absorb / wellbeing"},
  {"id":"rh-1360","cat":"the-need-underneath","type":"reflect","hook":"Lensy: 'strong men feel nothing' is a line you've heard. What does real strength let you feel?","prompt":"Pick what rings true.","options":["Everything, honestly","Sadness too","Whatever's there","Then ask for help"],"affirm":"Feeling it and naming it is the strong move, not bottling it.","relearn":"Real strength feels things and names them; bottling up isn't strength.","persona":"Veer","source":"positive masculinity / wellbeing"},
  {"id":"rh-1361","cat":"the-need-underneath","type":"reflect","hook":"Lensy: imagine a week from now you reached out and felt lighter. What got you there?","prompt":"Choose a first move.","options":["I told someone","I made a call","I joined something","I just started"],"affirm":"That future is reachable, and it starts with one small, real step.","relearn":"Relief is reachable; it usually starts with one small honest step toward people.","persona":"any","source":"help-seeking / hope"},
  {"id":"rh-1362","cat":"the-need-underneath","type":"reflect","hook":"Lensy: 'no one gets what I'm going through' is a heavy thought. Is it the whole truth?","prompt":"Sit with it.","options":["Maybe not","Someone might","I haven't asked yet","Worth finding out"],"affirm":"Most feelings are more shared than they seem, you're less alone than the thought says.","relearn":"'No one understands' usually shrinks the moment you actually let someone in.","persona":"any","source":"wellbeing / connection"},
  {"id":"rh-1363","cat":"the-need-underneath","type":"reflect","hook":"Lensy: what's one thing you're quietly building, skill, friendship, anything, that's actually yours?","prompt":"Name it.","options":["A skill I'm learning","A real friendship","A small goal","Something I make"],"affirm":"That's confidence you built, not bought, and no one can sell it back to you.","relearn":"Confidence is built through real skills and people, never bought from a 'mentor'.","persona":"Veer","source":"self-worth / built not bought"},
  {"id":"rh-1364","cat":"the-need-underneath","type":"branch","hook":"It's 1am, you feel hollow, and the feed serves 'why you're owed more'.","options":[{"text":"Close it; message a friend tomorrow","consequence":"You break the loop and reconnect for real.","outcome":"help","best":true},{"text":"Keep watching to feel less alone","consequence":"The feed mines the low moment; a real message helps more."}],"debrief":"Low, late moments are when the funnel bites; reach for a person.","relearn":"The funnel bites hardest when you're low; step away, reach a real person.","persona":"Veer","source":"guarding low moments"},
  {"id":"rh-1365","cat":"the-need-underneath","type":"branch","hook":"You've felt flat for weeks. A trusted adult asks how you're really doing.","options":[{"text":"Be honest: 'Not great, actually'","consequence":"They can finally help, because they know.","outcome":"supported","best":true},{"text":"Say 'I'm fine' and change the subject","consequence":"Understandable, but 'fine' shuts the door; honesty is what lets help in."}],"debrief":"One honest answer to a caring adult is how real support starts.","relearn":"Telling a trusted adult the honest truth is how real help can begin.","persona":"any","source":"trusted adult"},
  {"id":"rh-1366","cat":"the-need-underneath","type":"branch","hook":"You're being piled on with misogynist abuse in a group chat.","options":[{"text":"Screenshot, report at cybercrime.gov.in / 1930, tell an adult","consequence":"It's on record and you're not alone with it.","outcome":"supported","best":true},{"text":"Reply with worse abuse","consequence":"That feeds it; save proof and report instead."}],"debrief":"Targeted abuse is reportable; the shame is the abuser's.","relearn":"Online misogynist abuse: save proof, report at cybercrime.gov.in / 1930, tell someone.","persona":"Riya","source":"harassment routing (verified)"},
  {"id":"rh-1367","cat":"the-need-underneath","type":"branch","hook":"A friend admits the angry content made him feel less alone.","options":[{"text":"'That makes sense. I'm here, want to hang out?'","consequence":"He feels met, not judged, and stays connected.","outcome":"caring","best":true},{"text":"'That stuff is toxic, what's wrong with you?'","consequence":"Shame pushes him back to the feed; meet the need instead."}],"debrief":"Normalise the need, drop the shame, offer real connection.","relearn":"When a friend admits the content eased loneliness: meet the need, lose the shame.","persona":"any","source":"call-in / the need underneath"},
  {"id":"rh-1368","cat":"the-need-underneath","type":"branch","hook":"You keep telling yourself you'll feel better once you 'fix' everything alone.","options":[{"text":"Let one person in this week","consequence":"Shared weight is lighter; you don't have to solo it.","outcome":"help","best":true},{"text":"Keep handling it solo so no one worries","consequence":"Going solo is the funnel's whole script; one person in changes it."}],"debrief":"'Handle it alone' is the trap, not the cure; connection is.","relearn":"You don't have to fix everything alone; letting one person in is strength.","persona":"Veer","source":"help-seeking"},
  {"id":"rh-1369","cat":"the-need-underneath","type":"branch","hook":"Your younger brother feels worthless and quotes 'high-value man' clips.","options":[{"text":"'You matter to me. Let's talk to someone together'","consequence":"He feels valued; you open a door to real help.","outcome":"caring","best":true},{"text":"'Stop watching that rubbish and grow up'","consequence":"That shames the hurt; name his worth and help him instead."}],"debrief":"Name his worth, then route the real hurt to real help.","relearn":"Affirm a sibling's worth and help him reach support; mockery deepens it.","persona":"any","source":"family / support"},
  {"id":"rh-1370","cat":"the-need-underneath","type":"branch","hook":"You want to reach out, but worry you'll 'burden' the person.","options":[{"text":"Reach out; let them decide if they can help","consequence":"Most people are glad to be asked; you let them show up.","outcome":"supported","best":true},{"text":"Stay silent to avoid bothering them","consequence":"'I'd be a burden' is the loneliness talking, not the truth."}],"debrief":"People who care want to be asked; silence only isolates you.","relearn":"'I'd be a burden' is the loneliness talking; reaching out rarely is one.","persona":"any","source":"wellbeing / connection"},
  {"id":"rh-1371","cat":"the-need-underneath","type":"branch","hook":"A 'mentor' DMs a 'free' confidence call that needs your card.","options":[{"text":"Decline; talk to a real person you trust","consequence":"You skip the upsell and meet the need for free.","outcome":"help","best":true},{"text":"Hand over your details for the call","consequence":"'Free' that needs your card is a sales funnel, not help."}],"debrief":"Real help for how you feel doesn't start with your card.","relearn":"Real support for how you feel is free; a 'free' call needing your card is a sale.","persona":"Veer","source":"grift vs help"},
  {"id":"rh-1372","cat":"the-need-underneath","type":"branch","hook":"A forum says 'real men just push through, never therapy'.","options":[{"text":"Ignore it; talk to a trusted adult or Tele-MANAS 14416","consequence":"You meet the real need instead of toughing it out alone.","outcome":"help","best":true},{"text":"'Push through' silently","consequence":"'Push through alone' is the hook that traps you; real help exists."}],"debrief":"'Just push through' is a hook, not help; support is strength.","relearn":"'Push through alone' is a hook; a trusted adult or Tele-MANAS 14416 helps.","persona":"Veer","source":"Tele-MANAS (verified)"},
  {"id":"rh-1373","cat":"the-need-underneath","type":"branch","hook":"A girl in your class is getting rated and mocked online by some boys.","options":[{"text":"Check she's okay and offer to help her report it","consequence":"She feels backed, and the abuse gets challenged.","outcome":"supported","best":true},{"text":"Stay out of it; not your problem","consequence":"Silence leaves her alone with it; backing her is real, quiet strength."}],"debrief":"Backing someone targeted is on the bystander's strength, not her shame.","relearn":"Back someone targeted: check on them and help them report it.","persona":"any","source":"have each other's backs"},
  {"id":"rh-1374","cat":"the-need-underneath","type":"branch","hook":"You finally typed out how bad you've felt, finger hovering over send to a friend.","options":[{"text":"Send it","consequence":"You let someone in, and the weight starts to lift.","outcome":"supported","best":true},{"text":"Delete it; they'll think you're weak","consequence":"That fear is the myth talking; sending it is the strong, human move."}],"debrief":"Hitting send on the honest message is courage, not weakness.","relearn":"Sharing how you really feel with a friend is courage, not weakness.","persona":"any","source":"help-seeking"},
  {"id":"rh-1375","cat":"the-need-underneath","type":"branch","hook":"You want help but don't know where low mood even goes in India.","options":[{"text":"Talk to a trusted adult, or call Tele-MANAS 14416","consequence":"You reach a free, real route made for this.","outcome":"help","best":true},{"text":"Decide nothing official is for this","consequence":"There is a route: a trusted adult, or Tele-MANAS 14416."}],"debrief":"Low mood has a real home: a trusted adult, Tele-MANAS 14416.","relearn":"Loneliness and low mood route to a trusted adult or Tele-MANAS 14416 in India.","persona":"Counsellor","source":"Tele-MANAS (verified)"},
  {"id":"rh-1376","cat":"the-need-underneath","type":"branch","hook":"You quit the toxic feed, but the lonely feeling it filled remains.","options":[{"text":"Fill it for real: a call, a club, a walk","consequence":"You meet the need the feed was faking.","outcome":"help","best":true},{"text":"Wait for the feeling to just vanish","consequence":"The gap won't fill itself; one real connection beats waiting."}],"debrief":"Leaving the funnel works best when you replace it with connection.","relearn":"After the feed, fill the real need with real connection, not waiting.","persona":"Veer","source":"belonging / aftercare"},
  {"id":"rh-1377","cat":"the-need-underneath","type":"branch","hook":"A friend's posts turn dark and you fear it's beyond a chat.","options":[{"text":"Keep caring and quietly loop in a trusted adult","consequence":"He stays cared for and gets help bigger than you.","outcome":"safeguarding","best":true},{"text":"Handle it all yourself to keep his trust","consequence":"Some worries are too big to solo; care AND tell an adult."}],"debrief":"When it's beyond you, keep caring and bring in a trusted adult.","relearn":"If a friend worries you beyond a chat, keep caring and loop in an adult.","persona":"any","source":"safeguarding"},
  {"id":"rh-1378","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Real men handle their problems alone.\"","myth":{"un":"Real men handle their problems alone.","re":"Real strength includes knowing when to ask, everyone leans on people sometimes.","why":"'Handle it alone' is exactly the rule that isolates boys and traps them in the funnel."},"relearn":"Real strength includes asking for help; 'handle it alone' just isolates you.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1379","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Talking about feelings makes it worse.\"","myth":{"un":"Talking about feelings just makes it worse.","re":"Naming feelings out loud usually shrinks them; bottling them is what festers.","why":"The 'don't talk' rule keeps you stuck and alone, which is what the funnel wants."},"relearn":"Naming feelings out loud usually shrinks them; bottling up is what festers.","persona":"any","source":"wellbeing"},
  {"id":"rh-1380","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"If I feel this low, I'm broken.\"","myth":{"un":"Feeling this low means I'm broken.","re":"Low patches are a part of being human, not proof you're broken, and they pass with support.","why":"Calling a normal low 'broken' adds shame on top of pain and stops you reaching out."},"relearn":"Low patches are human, not 'broken', and they ease with support.","persona":"Veer","source":"wellbeing"},
  {"id":"rh-1381","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Needing people is a weakness to outgrow.\"","myth":{"un":"Needing other people is a weakness I should outgrow.","re":"Humans are wired to need each other; connection is a strength, not a flaw.","why":"'Need no one' sounds tough but it just leaves you alone, which the funnel feeds on."},"relearn":"Needing people is human strength, not a weakness to outgrow.","persona":"any","source":"connection"},
  {"id":"rh-1382","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Helplines are for people way worse off than me.\"","myth":{"un":"Helplines are only for people way worse off than me.","re":"Lines like Tele-MANAS 14416 are for anyone feeling low or stuck, no minimum required.","why":"The 'not bad enough' rule stops people reaching out until things get much harder."},"relearn":"Support lines like Tele-MANAS 14416 are for anyone low, no 'bad enough' bar.","persona":"Counsellor","source":"Tele-MANAS (verified)"},
  {"id":"rh-1383","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"If I ask for help, people will think less of me.\"","myth":{"un":"If I ask for help, people will think less of me.","re":"Most people respect honesty and want to help; asking deepens real bonds.","why":"Fear of judgement keeps you silent, which is exactly when loneliness grows."},"relearn":"Asking for help usually earns respect and deepens bonds, not the opposite.","persona":"any","source":"help-seeking"},
  {"id":"rh-1384","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Online hate is just words, I should be able to shrug it off.\"","myth":{"un":"Online hate is just words; I should be able to shrug it off.","re":"Targeted abuse hurts for real; you can report it and lean on people, no shame.","why":"'Just shrug it off' makes you carry it silently and lets the abuse continue."},"relearn":"Targeted online abuse hurts for real; report it and lean on people, no shame.","persona":"Riya","source":"refuse to absorb / wellbeing"},
  {"id":"rh-1385","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"A mentor's course will fix how empty I feel.\"","myth":{"un":"A mentor's paid course will fix how empty I feel.","re":"Emptiness eases through real connection and support, not a checkout page.","why":"Selling a 'cure' for a feeling he stoked is the grift, not help for the need."},"relearn":"Emptiness eases through real connection, not a mentor's paid 'cure'.","persona":"Veer","source":"grift vs help"},
  {"id":"rh-1386","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"If my own family doesn't get it, no one will.\"","myth":{"un":"If my own family doesn't get it, then no one ever will.","re":"Help can come from many people: a friend, teacher, counsellor, or Tele-MANAS 14416.","why":"Pinning all hope on one source, then losing it, is what 'no help exists' feeds on."},"relearn":"If one person doesn't get it, others can: a friend, teacher, or Tele-MANAS 14416.","persona":"Counsellor","source":"Tele-MANAS (verified)"},
  {"id":"rh-1387","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Feeling left out means there's something wrong with me.\"","myth":{"un":"Feeling left out means there's something wrong with me.","re":"Feeling left out is a common, passing signal, not a verdict on your worth.","why":"The funnel reframes a normal feeling as a personal defect so it can sell a 'fix'."},"relearn":"Feeling left out is a common signal, not a verdict on your worth.","persona":"Veer","source":"wellbeing"},
  {"id":"rh-1388","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Crying or breaking down means I've lost control.\"","myth":{"un":"Crying or breaking down means I've lost control as a man.","re":"Letting feelings out is a healthy release, not a failure of control.","why":"The 'never crack' rule bottles pressure until it costs far more later."},"relearn":"Letting feelings out is healthy release, not a loss of control.","persona":"Veer","source":"positive masculinity / wellbeing"},
  {"id":"rh-1389","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"My problems are too small to bother anyone with.\"","myth":{"un":"My problems are too small to bother anyone with.","re":"There's no size limit on reaching out; small worries shared early often stay small.","why":"'Too small to mention' keeps you silent until things pile up and feel huge."},"relearn":"There's no 'too small' for reaching out; sharing early keeps worries small.","persona":"any","source":"help-seeking"},
  {"id":"rh-1390","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"If I block the haters, they win.\"","myth":{"un":"If I block the people abusing me, they win.","re":"Blocking and reporting protects your peace; that's you winning, not them.","why":"Staying in range of abuse to 'not let them win' just lets the abuse keep landing."},"relearn":"Blocking and reporting abuse protects your peace, that's a win, not a loss.","persona":"Riya","source":"refuse to absorb"},
  {"id":"rh-1391","cat":"the-need-underneath","type":"strike-rewrite","hook":"\"Once you've felt this low, it never really gets better.\"","myth":{"un":"Once you've felt this low, it never really gets better.","re":"Low feelings shift, especially with support; 'never' is the low mood speaking, not fact.","why":"Believing it's permanent removes the reason to reach out, which keeps you stuck."},"relearn":"Low feelings shift with support; 'it never gets better' is the mood, not the truth.","persona":"any","source":"wellbeing / hope"},
  {"id":"rh-1392","cat":"the-need-underneath","type":"match","hook":"Match each real feeling to a real, healthy answer for it.","pairs":[{"left":"Lonely tonight","right":"Message a friend"},{"left":"Feeling worthless","right":"Talk to a trusted adult"},{"left":"Restless, low energy","right":"Move or get outside"},{"left":"Overwhelmed and stuck","right":"Call Tele-MANAS 14416"},{"left":"Bored and doom-scrolling","right":"Do one real thing"}],"relearn":"Real feelings have real, free answers; the feed's 'cures' aren't them.","persona":"Counsellor","source":"the need underneath"},
  {"id":"rh-1393","cat":"the-need-underneath","type":"match","hook":"Match the worry to where real help is, in India.","pairs":[{"left":"Low mood for weeks","right":"Tele-MANAS 14416"},{"left":"Need someone right now","right":"A trusted adult"},{"left":"Online misogynist abuse","right":"cybercrime.gov.in / 1930"},{"left":"A child being harassed","right":"Childline 1098"},{"left":"Just need to belong","right":"A real-life team or club"}],"relearn":"India routes: Tele-MANAS 14416, a trusted adult, 1930, Childline 1098, real-life belonging.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"rh-1394","cat":"the-need-underneath","type":"match","hook":"Match the grift's pitch to the real need it's exploiting.","pairs":[{"left":"'Join the brotherhood'","right":"Wanting to belong"},{"left":"'Become high-value'","right":"Wanting respect"},{"left":"'Stop being a beta'","right":"Fear of being unseen"},{"left":"'I'll fix your life'","right":"Feeling stuck"},{"left":"'They're why you hurt'","right":"Real, unplaced pain"}],"relearn":"Every grift pitch targets a real need; the need is yours, the 'answer' is a sale.","persona":"any","source":"grift vs need"},
  {"id":"rh-1395","cat":"the-need-underneath","type":"match","hook":"Match each 'tough guy' rule to the kinder truth that frees you from it.","pairs":[{"left":"Never ask for help","right":"Asking is strength"},{"left":"Feelings are weakness","right":"Naming them is brave"},{"left":"Handle it alone","right":"People want to help"},{"left":"Push through silently","right":"Support actually works"},{"left":"Need no one","right":"Everyone needs people"}],"relearn":"Each 'tough guy' rule has a kinder, truer answer that frees you from it.","persona":"Veer","source":"positive masculinity"},
  {"id":"rh-1396","cat":"the-need-underneath","type":"match","hook":"Match the unhelpful response to the caring one that actually meets the need.","pairs":[{"left":"'Just man up'","right":"'That sounds hard, I'm here'"},{"left":"'Stop being dramatic'","right":"'Tell me more'"},{"left":"'What's wrong with you?'","right":"'Want to talk to someone?'"},{"left":"'Get over it'","right":"'Let's find help together'"},{"left":"'Toughen up'","right":"'You don't have to do this alone'"}],"relearn":"Caring responses meet the need; 'man up' and 'get over it' just deepen it.","persona":"any","source":"call-in / support"},
  {"id":"rh-1397","cat":"the-need-underneath","type":"match","hook":"Match the feeling to the truer thought that answers it.","pairs":[{"left":"'I'm not enough'","right":"You already are"},{"left":"'I'm completely alone'","right":"Connection is reachable"},{"left":"'It's all their fault'","right":"The hurt's real, blame isn't"},{"left":"'Nothing will help'","right":"Real help exists"},{"left":"'I have to be tough'","right":"You can just be human"}],"relearn":"Each heavy thought has a truer one; you're enough, not alone, and help is real.","persona":"any","source":"self-worth"},
  {"id":"rh-1398","cat":"the-need-underneath","type":"match","hook":"Match the small first step to what it quietly builds.","pairs":[{"left":"Texting one friend","right":"A thread back to people"},{"left":"Joining a local team","right":"Real belonging"},{"left":"Telling a teacher","right":"An adult in your corner"},{"left":"Calling Tele-MANAS 14416","right":"Free, trained support"},{"left":"Naming the feeling","right":"It loosens its grip"}],"relearn":"Small real steps build belonging, support and relief, no grift required.","persona":"Counsellor","source":"help-seeking (verified)"},
  {"id":"rh-1399","cat":"the-need-underneath","type":"role-play","hook":"A mate seems off and quiet lately. Open the door gently.","setup":"You text him. Say:","yourLine":[{"text":"\"Hey, you've seemed a bit off. I'm around if you ever want to talk.\"","best":true},{"text":"\"You good? Cool.\""}],"relearn":"A warm, open check-in invites a friend to talk without pressure.","persona":"any","source":"connection"},
  {"id":"rh-1400","cat":"the-need-underneath","type":"role-play","hook":"You finally want to tell your dad you've been struggling. Find the words.","setup":"You sit down with him. Say:","yourLine":[{"text":"\"Dad, I've been feeling really low lately. Can we talk?\"","best":true},{"text":"\"Nothing's wrong, forget it.\""}],"relearn":"Naming it plainly to a parent opens the door to real support.","persona":"Veer","source":"trusted adult / family"},
  {"id":"rh-1401","cat":"the-need-underneath","type":"role-play","hook":"A friend just admitted the angry content made him feel less alone. Respond.","setup":"He looks braced for judgement. You say:","yourLine":[{"text":"\"That makes total sense. Let's find something that actually helps.\"","best":true},{"text":"\"Mate, that stuff rots your brain.\""}],"relearn":"Meeting a friend's need without shame keeps the door open to help.","persona":"any","source":"call-in / the need underneath"},
  {"id":"rh-1402","cat":"the-need-underneath","type":"role-play","hook":"You're at a counsellor's door and nearly walked off. Push through and speak.","setup":"You knock and go in. Say:","yourLine":[{"text":"\"I'm not sure how to start, but I've not been okay.\"","best":true},{"text":"\"Actually, I think I'm fine. Sorry.\""}],"relearn":"You don't need the perfect words; 'I've not been okay' is enough to start.","persona":"Veer","source":"help-seeking"},
  {"id":"rh-1403","cat":"the-need-underneath","type":"role-play","hook":"Someone's mocking a classmate online and tags you to join in. Set the line.","setup":"You reply in the thread. Say:","yourLine":[{"text":"\"Not joining this. Leave her alone.\"","best":true},{"text":"\"Haha, not my business.\""}],"relearn":"A calm, clear refusal backs the person targeted and won't reward the pile-on.","persona":"Riya","source":"have each other's backs"},
  {"id":"rh-1404","cat":"the-need-underneath","type":"role-play","hook":"An older cousin asks how you're really doing, no rush. Be honest.","setup":"You take a breath. Say:","yourLine":[{"text":"\"Honestly? Some days are heavy. It helps to say it out loud.\"","best":true},{"text":"\"All good, same as always.\""}],"relearn":"An honest answer to a caring relative lets real support reach you.","persona":"any","source":"connection / family"},
  {"id":"rh-1405","cat":"the-need-underneath","type":"role-play","hook":"Your friend keeps saying he doesn't need anyone. Offer connection anyway.","setup":"You sit beside him and say:","yourLine":[{"text":"\"You don't have to need anyone. I just like having you around.\"","best":true},{"text":"\"Fine, do it your way then.\""}],"relearn":"Offering steady connection, no pressure, meets the need 'I need no one' hides.","persona":"any","source":"belonging / connection"},
  {"id":"rh-1406","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines telling you NOT to reach for help.","scene":[{"id":"a","text":"'Real men deal with it alone, never therapy'","trick":true},{"id":"b","text":"'It's okay to tell someone how you feel'","trick":false},{"id":"c","text":"'Asking for help proves you're weak'","trick":true},{"id":"d","text":"'Tele-MANAS 14416 is free, there for this'","trick":false},{"id":"e","text":"'Low patches are human, they ease'","trick":false}],"why":"Both flagged lines push 'suffer alone', the rule that traps you.","relearn":"'Deal with it alone' and 'asking is weakness' are traps, not truth.","persona":"Veer","source":"help-seeking"},
  {"id":"rh-1407","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines selling a 'cure' for the real need.","scene":[{"id":"a","text":"'Buy my course, never feel empty again'","trick":true},{"id":"b","text":"'Talking to a friend can really help'","trick":false},{"id":"c","text":"'Only my paid academy fixes loneliness'","trick":true},{"id":"d","text":"'A trusted adult or Tele-MANAS 14416 helps'","trick":false},{"id":"e","text":"'Belonging is built, not bought'","trick":false}],"why":"Both flagged lines sell a feeling-fix at a checkout; the cure is a grift.","relearn":"A paywall 'cure' for loneliness is a grift; help with people is free.","persona":"any","source":"grift vs help"},
  {"id":"rh-1408","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines calling a normal feeling proof you're broken.","scene":[{"id":"a","text":"'If you feel lonely, something's wrong with you'","trick":true},{"id":"b","text":"'Loneliness is a normal cue to connect'","trick":false},{"id":"c","text":"'Feeling low means you're permanently broken'","trick":true},{"id":"d","text":"'Low patches pass, especially with support'","trick":false},{"id":"e","text":"'It's okay to ask for help'","trick":false}],"why":"Both flagged lines paint normal feelings as a defect.","relearn":"Lonely or low isn't 'broken'; it's a human signal that eases with support.","persona":"any","source":"wellbeing"},
  {"id":"rh-1409","cat":"the-need-underneath","type":"spot","hook":"Spot the two replies that shame a hurting friend.","scene":[{"id":"a","text":"'Man up, stop being so soft'","trick":true},{"id":"b","text":"'That sounds really hard, I'm here'","trick":false},{"id":"c","text":"'What's even wrong with you?'","trick":true},{"id":"d","text":"'Want to talk to someone together?'","trick":false},{"id":"e","text":"'You don't have to do this alone'","trick":false}],"why":"Both flagged replies shame the hurt and push him back to the feed.","relearn":"'Man up' and 'what's wrong with you' shame a friend; care helps.","persona":"any","source":"call-in / support"},
  {"id":"rh-1410","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines telling a targeted girl to absorb abuse silently.","scene":[{"id":"a","text":"'Just ignore it, that's how strong girls cope'","trick":true},{"id":"b","text":"'You can save proof and report it'","trick":false},{"id":"c","text":"'Saying anything makes you a snitch'","trick":true},{"id":"d","text":"'Your worth isn't theirs to set'","trick":false},{"id":"e","text":"'Tell an adult, you're not alone'","trick":false}],"why":"Both flagged lines pressure silent absorption.","relearn":"'Just absorb it silently' is a trap; you can report abuse and lean on people.","persona":"Riya","source":"refuse to absorb"},
  {"id":"rh-1411","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines claiming no real help exists.","scene":[{"id":"a","text":"'No one can actually help with this'","trick":true},{"id":"b","text":"'A trusted adult can really help'","trick":false},{"id":"c","text":"'Helplines never do anything, don't bother'","trick":true},{"id":"d","text":"'Tele-MANAS 14416 is free, 24x7, for this'","trick":false},{"id":"e","text":"'A teacher or counsellor is worth it'","trick":false}],"why":"Both flagged lines push hopelessness so you won't reach out; real routes exist.","relearn":"'No help exists' is false; trusted people and Tele-MANAS 14416 are real routes.","persona":"Counsellor","source":"Tele-MANAS (verified)"},
  {"id":"rh-1412","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines disguising isolation as 'independence'.","scene":[{"id":"a","text":"'Real men need absolutely no one'","trick":true},{"id":"b","text":"'Leaning on people is part of strength'","trick":false},{"id":"c","text":"'Cut everyone off, rely only on yourself'","trick":true},{"id":"d","text":"'Friends and family are real belonging'","trick":false},{"id":"e","text":"'Be independent and still have people'","trick":false}],"why":"Both flagged lines sell isolation as strength; that's what the funnel feeds on.","relearn":"'Need no one' is isolation in disguise; real strength keeps people close.","persona":"Veer","source":"connection"},
  {"id":"rh-1413","cat":"the-need-underneath","type":"spot","hook":"Spot the two lines gatekeeping help behind 'bad enough?'.","scene":[{"id":"a","text":"'Helplines are only for serious cases'","trick":true},{"id":"b","text":"'Tele-MANAS 14416 is for anyone low'","trick":false},{"id":"c","text":"'You must hit rock bottom to deserve help'","trick":true},{"id":"d","text":"'No minimum, reaching out early is fine'","trick":false},{"id":"e","text":"'A trusted adult is worth it anytime'","trick":false}],"why":"Both flagged lines set a fake 'bad enough' bar; help has no minimum.","relearn":"No 'bad enough' bar; Tele-MANAS 14416 and trusted adults are for anyone low.","persona":"Counsellor","source":"Tele-MANAS (verified)"},
  {"id":"rh-1414","cat":"the-need-underneath","type":"sort","hook":"Sort each move: does it meet the real need, or just feed the funnel?","items":[{"id":"a","text":"Message a friend when you feel low"},{"id":"b","text":"Doom-scroll angry clips till 2am"},{"id":"c","text":"Join a local team or club"},{"id":"d","text":"Rage-share an 'enemy' video"},{"id":"e","text":"Call Tele-MANAS 14416"},{"id":"f","text":"Buy the 'alpha' course to feel better"}],"bins":[{"id":"meets","label":"Meets the need","valence":"pos"},{"id":"feeds","label":"Feeds the funnel","valence":"neg"}],"key":{"a":"meets","b":"feeds","c":"meets","d":"feeds","e":"meets","f":"feeds"},"relearn":"Real connection and support meet the need; scrolling, rage and courses feed the funnel.","persona":"any","source":"the need underneath"},
  {"id":"rh-1415","cat":"the-need-underneath","type":"sort","hook":"Sort each line: real support, or a trap dressed as advice?","items":[{"id":"a","text":"'It's okay to tell someone how you feel'"},{"id":"b","text":"'Real men suffer in silence'"},{"id":"c","text":"'Tele-MANAS 14416 is free and there for this'"},{"id":"d","text":"'Asking for help means you've failed'"},{"id":"e","text":"'A trusted adult can really help'"},{"id":"f","text":"'Just bottle it up and push through'"}],"bins":[{"id":"support","label":"Real support","valence":"pos"},{"id":"trap","label":"A trap","valence":"neg"}],"key":{"a":"support","b":"trap","c":"support","d":"trap","e":"support","f":"trap"},"relearn":"'Tell someone' is support; 'suffer in silence' is a trap.","persona":"Veer","source":"help-seeking (verified)"},
  {"id":"rh-1416","cat":"the-need-underneath","type":"sort","hook":"Sort what genuinely fills the gap from what only fakes it.","items":[{"id":"a","text":"A real friend who checks in"},{"id":"b","text":"A paid 'brotherhood' subscription"},{"id":"c","text":"A team that's glad you came"},{"id":"d","text":"A feed that flatters then enrages you"},{"id":"e","text":"Family who have your back"},{"id":"f","text":"A 'mentor' selling belonging by tier"}],"bins":[{"id":"real","label":"Real belonging","valence":"pos"},{"id":"fake","label":"Faked for sale","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Real belonging comes free from people; the funnel only sells a fake version.","persona":"any","source":"belonging"},
  {"id":"rh-1417","cat":"the-need-underneath","type":"sort","hook":"Sort each response to a friend: pulls him toward help, or pushes him away?","items":[{"id":"a","text":"'That sounds heavy, want to talk?'"},{"id":"b","text":"'Stop whining and man up'"},{"id":"c","text":"'Let's find someone who can help'"},{"id":"d","text":"'What's wrong with you, honestly?'"},{"id":"e","text":"'You're not alone in this'"},{"id":"f","text":"'Sort yourself out, it's pathetic'"}],"bins":[{"id":"toward","label":"Pulls toward help","valence":"pos"},{"id":"away","label":"Pushes away","valence":"neg"}],"key":{"a":"toward","b":"away","c":"toward","d":"away","e":"toward","f":"away"},"relearn":"Care and connection pull a friend toward help; shame pushes him away.","persona":"any","source":"call-in / support"},
  {"id":"rh-1418","cat":"the-need-underneath","type":"sort","hook":"Sort each thought: a kind truth to keep, or a hook to drop?","items":[{"id":"a","text":"'Loneliness is a cue to connect'"},{"id":"b","text":"'I'm broken for feeling this'"},{"id":"c","text":"'Real help exists for how I feel'"},{"id":"d","text":"'No one could ever understand'"},{"id":"e","text":"'Asking for help is strength'"},{"id":"f","text":"'I have to handle it all alone'"}],"bins":[{"id":"keep","label":"Kind truth","valence":"pos"},{"id":"drop","label":"A hook to drop","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"Keep the kind truths about connection and help; drop the 'broken, alone' hooks.","persona":"any","source":"wellbeing / self-worth"},
  {"id":"rh-1419","cat":"the-need-underneath","type":"sort","hook":"Sort where each problem actually goes for real help, in India.","items":[{"id":"a","text":"Weeks of low mood"},{"id":"b","text":"Needing someone in person now"},{"id":"c","text":"Misogynist abuse online"},{"id":"d","text":"A child being harassed"},{"id":"e","text":"Just wanting to belong"},{"id":"f","text":"'Buy my course to feel okay'"}],"bins":[{"id":"route","label":"A real route","valence":"pos"},{"id":"sale","label":"Not help, a sale","valence":"neg"}],"key":{"a":"route","b":"route","c":"route","d":"route","e":"route","f":"sale"},"relearn":"Low mood, abuse, a child's safety and belonging all have real routes; a 'course' is a sale.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"rh-1420","cat":"the-need-underneath","type":"sort","hook":"Sort each habit for a low night: steadies you, or sinks you deeper?","items":[{"id":"a","text":"Texting one person before bed"},{"id":"b","text":"Endless autoplay of outrage clips"},{"id":"c","text":"Jotting down what you feel"},{"id":"d","text":"Refreshing the haters' comments"},{"id":"e","text":"A short walk or some music"},{"id":"f","text":"Comparing yourself to 'high-value' edits"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"sink","label":"Sinks you deeper","valence":"neg"}],"key":{"a":"steady","b":"sink","c":"steady","d":"sink","e":"steady","f":"sink"},"relearn":"On a low night, reach for people and small real acts; the feed only sinks you deeper.","persona":"Veer","source":"guarding low moments"},
  {"id":"rh-1421","cat":"the-need-underneath","type":"sort","hook":"Sort each sign: wants you stronger, or wants you hooked?","items":[{"id":"a","text":"Points you to free, local support"},{"id":"b","text":"Says only it can fix you"},{"id":"c","text":"Wants you to need it less over time"},{"id":"d","text":"Charges more the worse you feel"},{"id":"e","text":"Encourages real friends and family"},{"id":"f","text":"Isolates you from people who care"}],"bins":[{"id":"stronger","label":"Wants you stronger","valence":"pos"},{"id":"hooked","label":"Wants you hooked","valence":"neg"}],"key":{"a":"stronger","b":"hooked","c":"stronger","d":"hooked","e":"stronger","f":"hooked"},"relearn":"Genuine help builds independence and connection; a grift isolates and upsells.","persona":"any","source":"grift vs help"},
];

